		SHADOW_BARRAGE("Shadow Barrage"),
		RED_KERIS("Red Keris");

		private final String label;

		Effect(String label) {
			this.label = label;
		}
	}

	private final Client client;
	private final DefenceTracker tracker;
	private final Map<Effect, EffectBox> boxes = new EnumMap<>(Effect.class);

	BossEffectInfoBoxes(Client client, DefenceTracker tracker) {
		this.client = client;
		this.tracker = tracker;
	}

	void update(Plugin plugin, InfoBoxManager manager, ItemManager items, SkillIconManager icons,
			boolean showRedKeris, boolean showShadowBarrage, boolean showVulnerability) {
		int tick = client.getTickCount();
		NPC selected = selectedBoss();
		EffectState state = tracker.effectState(selected, false);
		int kerisRemaining = state == null ? 0 : Math.max(0, state.kerisExpiry - tick);

		updateBox(Effect.VULNERABILITY,
				showVulnerability && ((state != null && state.vulnerabilityLanded)
						|| tracker.hasLandedSpell(selected, SpellDrain.VULNERABILITY)
						|| tracker.hasLandedSpell(selected, SpellDrain.VULNERABILITY_TOME)),
				"", "Landed", plugin, manager, items, icons);
		updateBox(Effect.SHADOW_BARRAGE,
				showShadowBarrage && ((state != null && state.shadowLanded)
						|| tracker.hasLandedSpell(selected, SpellDrain.SHADOW_BARRAGE)),
				"", state != null && state.shadowLandedOnReducedDefence
						? "Landed Â· Defence already reduced"
						: "Landed",
				plugin, manager, items, icons);
		updateBox(Effect.RED_KERIS, showRedKeris && kerisRemaining > 0,
				Integer.toString(kerisRemaining),
				"Landed Â· Target takes increased damage", plugin, manager, items, icons);
	}

	void hide(InfoBoxManager manager) {
		for (EffectBox box : boxes.values()) {
			manager.removeInfoBox(box);
		}
		boxes.clear();
	}

	private NPC selectedBoss() {
		Player local = client.getLocalPlayer();
		Actor target = local == null ? null : local.getInteracting();
		if (target != null) {
			return target instanceof NPC && isCurrentActor((NPC) target) ? (NPC) target : null;
		}
		DefenceTracker.DefenceState state = tracker.state();
		return state != null && tracker.hasBoundNpc() ? npcAtIndex(state.getNpcIndex()) : null;
	}

	private NPC npcAtIndex(int index) {
		WorldView world = client.getTopLevelWorldView();
		return world == null || world.npcs() == null ? null : world.npcs().byIndex(index);
	}

	private boolean isCurrentActor(NPC npc) {
		return BossDefence.isLiveNpc(npc) && npcAtIndex(npc.getIndex()) == npc;
	}

	private void updateBox(Effect effect, boolean show, String text, String status, Plugin plugin,
			InfoBoxManager manager, ItemManager items, SkillIconManager icons) {
		EffectBox box = boxes.get(effect);
		if (!show) {
			if (box != null) {
				manager.removeInfoBox(box);
				boxes.remove(effect);
			}
			return;
		}
		if (box == null) {
			BufferedImage icon = effect == Effect.VULNERABILITY
					? icons.getSkillImage(Skill.MAGIC)
					: items.getImage(effect == Effect.RED_KERIS
							? ItemID.KERIS_PARTISAN_CORRUPTION
							: ItemID.ANCIENT_SCEPTRE_SHADOW);
			box = new EffectBox(icon, plugin);
			boxes.put(effect, box);
			manager.addInfoBox(box);
		}
		box.text = text;
		box.setTooltip(effect.label + "<br>" + status);
	}

	private static final class EffectBox extends InfoBox {
		private String text = "";

		private EffectBox(BufferedImage image, Plugin plugin) {
			super(image, plugin);
		}

		@Override
		public String getText() {
			return text;
		}

		@Override
		public Color getTextColor() {
			return Color.WHITE;
		}
	}
}

package net.betterpartydefence;

import java.util.IdentityHashMap;
import java.util.Map;
import net.betterpartydefence.DefenceTracker.EffectState;
import net.betterpartydefence.DefenceTracker.SpellDrain;
import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.WorldView;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;

// Detects Vulnerability, Shadow Barrage, and Red Keris effects.
final class BossEffectTracker {
	static final int KERIS_EFFECT_TICKS = 10;
	private static final int VULNERABILITY_PROJECTILE = 168;
	private static final int CHARGED_TOME_OF_WATER = 25574;
	private static final int ANCIENT_BARRAGE_ANIMATION = 1979;
	private static final int CLIENT_CYCLES_PER_TICK = 30;
	private static final int NO_TICK = Integer.MIN_VALUE;

	private final Client client;
	private final ClientThread clientThread;
	private final DefenceTracker tracker;
	private final Map<NPC, Observation> observations = new IdentityHashMap<>();
	private NPC shadowCasterTarget;
	private int shadowCastTick = NO_TICK;
	private int specialEnergy;
	private NPC kerisTarget;
	private int kerisHitTick = NO_TICK;
	private int kerisHitAmount;
	private long kerisHitAtMillis;
	private int kerisArmGeneration;

	BossEffectTracker(Client client, ClientThread clientThread, DefenceTracker tracker) {
		this.client = client;
		this.clientThread = clientThread;
		this.tracker = tracker;
		this.specialEnergy = client.getVarpValue(VarPlayerID.SA_ENERGY);
	}

	void onLocalAnimation(Actor actor) {
		Player player = client.getLocalPlayer();
		if (player == null || actor != player || player.getAnimation() != ANCIENT_BARRAGE_ANIMATION
				|| !hasShadowSceptre()) {
			return;
		}

		Actor target = player.getInteracting();
		if (target instanceof NPC && BossDefence.matchingNpc((NPC) target) != null) {
			shadowCasterTarget = (NPC) target;
			shadowCastTick = client.getTickCount();
		}
	}

	void onProjectileMoved(Projectile projectile) {
		Player player = client.getLocalPlayer();
		if (player == null || projectile.getId() != VULNERABILITY_PROJECTILE
				|| projectile.getSourceActor() != player || !(projectile.getTargetActor() instanceof NPC)) {
			return;
		}
		NPC npc = (NPC) projectile.getTargetActor();
		if (BossDefence.matchingNpc(npc) == null) {
			return;
		}
		Observation state = observations.computeIfAbsent(npc, key -> new Observation());
		if (state.vulnerabilityProjectile != projectile) {
			state.vulnerabilityProjectile = projectile;
			state.vulnerabilitySpell = equippedItem(EquipmentInventorySlot.SHIELD) == CHARGED_TOME_OF_WATER
					? SpellDrain.VULNERABILITY_TOME
					: SpellDrain.VULNERABILITY;
		}
	}

	void onGraphicChanged(Actor actor) {
		if (!(actor instanceof NPC)) {
			return;
		}
		NPC npc = (NPC) actor;
		if (BossDefence.matchingNpc(npc) == null) {
			return;
		}

		int tick = client.getTickCount();
		for (ActorSpotAnim spot : npc.getSpotAnims()) {
			if (spot.getId() == SpotanimID.VULNERABILITY_IMPACT) {
				EffectState effects = tracker.effectState(npc, true);
				if (effects != null) {
					effects.vulnerabilityLanded = true;
					Observation state = observations.get(npc);
					if (state != null && state.vulnerabilityGraphicCycle != spot.getStartCycle()) {
						state.vulnerabilityGraphicCycle = spot.getStartCycle();
						if (state.vulnerabilitySpell != null && Math.abs(
								state.vulnerabilityProjectile.getEndCycle()
										- spot.getStartCycle()) <= CLIENT_CYCLES_PER_TICK) {
							tracker.queueSpell(state.vulnerabilitySpell, npc, tick);
							state.vulnerabilitySpell = null;
						}
					}
				}
			} else if (spot.getId() == SpotanimID.SHADOW_BARRAGE_IMPACT) {
				Observation state = observations.computeIfAbsent(npc, key -> new Observation());
				if (spot.getStartCycle() != state.shadowGraphicCycle) {
					state.shadowGraphicCycle = spot.getStartCycle();
					state.shadowGraphicTick = tick;
					confirmShadow(state, npc);
				}
			}
		}
	}

	void onSpecialEnergy(int energy) {
		int spent = specialEnergy - energy;
		specialEnergy = energy;
		if ((spent != 750 && spent != 375) || weaponId() != ItemID.KERIS_PARTISAN_CORRUPTION) {
			return;
		}

		int hitTick = client.getTickCount() + 1;
		int generation = ++kerisArmGeneration;
		clientThread.invokeLater(() -> {
			if (generation != kerisArmGeneration) {
				return;
			}
			Player local = client.getLocalPlayer();
			Actor target = local == null ? null : local.getInteracting();
			if (target instanceof NPC && BossDefence.matchingNpc((NPC) target) != null) {
				kerisTarget = (NPC) target;
				kerisHitTick = hitTick;
				kerisHitAmount = 0;
			}
		});
	}

	void onHitsplatApplied(HitsplatApplied event) {
		if (!(event.getActor() instanceof NPC) || !event.getHitsplat().isMine()) {
			return;
		}
		NPC npc = (NPC) event.getActor();
		int tick = client.getTickCount();
		int damage = event.getHitsplat().getAmount();
		if (npc == kerisTarget && tick == kerisHitTick) {
			// Instant weapon hits follow other owned hits.
			kerisHitAmount = damage;
			kerisHitAtMillis = System.currentTimeMillis();
		}
		if (npc == shadowCasterTarget && tick - shadowCastTick >= 0
				&& tick - shadowCastTick <= 1 && damage > 0) {
			Observation state = observations.computeIfAbsent(npc, key -> new Observation());
			state.shadowHitTick = tick;
			confirmShadow(state, npc);
		}
	}

	private void confirmShadow(Observation state, NPC npc) {
		if (npc == shadowCasterTarget && state.shadowGraphicTick != NO_TICK
				&& state.shadowHitTick == state.shadowGraphicTick
				&& state.shadowHitTick - shadowCastTick >= 0 && state.shadowHitTick - shadowCastTick <= 1) {
			tracker.queueSpell(SpellDrain.SHADOW_BARRAGE, npc, state.shadowHitTick);
			shadowCasterTarget = null;
		}
	}

	void settleKeris(BetterPartyDefencePlugin plugin) {
		int tick = client.getTickCount();
		if (kerisTarget == null || tick <= kerisHitTick) {
			return;
		}

		NPC target = kerisTarget;
		kerisTarget = null;
		int expiry = kerisHitTick + KERIS_EFFECT_TICKS;
		if (kerisHitAmount > 0 && tick < expiry && isCurrentActor(target)) {
			applyKerisTimer(target, expiry, kerisHitAtMillis);
			plugin.broadcastKeris(target, kerisHitTick, kerisHitAtMillis);
		}
	}

	void applyKerisTimer(NPC target, int expiry, long hitAtMillis) {
		EffectState effects = tracker.effectState(target, true);
		if (effects != null && expiry > effects.kerisExpiry && hitAtMillis != effects.kerisHitAtMillis) {
			effects.kerisExpiry = expiry;
			effects.kerisHitAtMillis = hitAtMillis;
		}
	}

	void updateObservations() {
		int tick = client.getTickCount();
		observations.keySet().removeIf(npc -> !isCurrentActor(npc));
		if (shadowCasterTarget != null && tick - shadowCastTick > 1) {
			shadowCasterTarget = null;
		}
	}

	void clearBoss(BossDefence boss) {
		observations.keySet().removeIf(npc -> BossDefence.matchingNpc(npc) == boss);
		if (kerisTarget != null && BossDefence.matchingNpc(kerisTarget) == boss) {
			kerisTarget = null;
		}
		if (shadowCasterTarget != null && BossDefence.matchingNpc(shadowCasterTarget) == boss) {
			shadowCasterTarget = null;
		}
	}

	void reset() {
		observations.clear();
		kerisTarget = null;
		kerisArmGeneration++;
		shadowCasterTarget = null;
		specialEnergy = client.getVarpValue(VarPlayerID.SA_ENERGY);
	}

	private boolean hasShadowSceptre() {
		int item = weaponId();
		return item == ItemID.ANCIENT_SCEPTRE_SHADOW || item == ItemID.ANCIENT_SCEPTRE_SHADOW_TROUVER;
	}

	private int weaponId() {
		return equippedItem(EquipmentInventorySlot.WEAPON);
	}

	private int equippedItem(EquipmentInventorySlot slot) {
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		Item item = equipment == null ? null : equipment.getItem(slot.getSlotIdx());
		return item == null ? -1 : item.getId();
	}

	private NPC npcAtIndex(int index) {
		WorldView world = client.getTopLevelWorldView();
		return world == null || world.npcs() == null ? null : world.npcs().byIndex(index);
	}

	private boolean isCurrentActor(NPC npc) {
		return BossDefence.isLiveNpc(npc) && npcAtIndex(npc.getIndex()) == npc;
	}

	private static final class Observation {
		private int shadowGraphicCycle = NO_TICK;
		private int shadowGraphicTick = NO_TICK;
		private int shadowHitTick = NO_TICK;
		private Projectile vulnerabilityProjectile;
		SpellDrain vulnerabilitySpell;
		int vulnerabilityGraphicCycle = NO_TICK;
	}
}

package net.betterpartydefence;

import lombok.ToString;
import net.runelite.client.party.messages.PartyMemberMessage;

// Request stored defence history after a boss appears.
@ToString(doNotUseGetters = true)
public class BpdBossPresence extends PartyMemberMessage {
	public static final int PROTOCOL_VERSION = 1;

	private int protocolVersion;
	private int world;
	private String bossType;
	private int scopeType;
	private int scopeId;
	private int bossX;
	private int bossY;
	private int bossPlane;
	private int healthPercent;
	private long sentAtMillis;
	private BpdDefenceSync offeredHistory;
	// Sender party session; zero is legacy.
	@ToString.Exclude
	private long partyId;

	// Gson.
	public BpdBossPresence() {
	}

	public BpdBossPresence(
			int world,
			BossDefence boss,
			int scopeType,
			int scopeId,
			int bossX,
			int bossY,
			int bossPlane,
			int healthPercent) {
		this.protocolVersion = PROTOCOL_VERSION;
		this.world = world;
		this.bossType = boss == null ? null : boss.name();
		this.scopeType = scopeType;
		this.scopeId = scopeId;
		this.bossX = bossX;
		this.bossY = bossY;
		this.bossPlane = bossPlane;
		this.healthPercent = healthPercent;
		this.sentAtMillis = System.currentTimeMillis();
	}

	public BossDefence toBossType() {
		if (bossType == null) {
			return null;
		}
		try {
			return BossDefence.valueOf(bossType).trackingType();
		} catch (RuntimeException ex) {
			return null;
		}
	}

	public int getProtocolVersion() {
		return protocolVersion;
	}
	public int getWorld() {
		return world;
	}
	public int getScopeType() {
		return scopeType;
	}
	public int getScopeId() {
		return scopeId;
	}
	public int getBossX() {
		return bossX;
	}
	public int getBossY() {
		return bossY;
	}
	public int getBossPlane() {
		return bossPlane;
	}
	public int getHealthPercent() {
		return healthPercent;
	}
	public long getSentAtMillis() {
		return sentAtMillis;
	}
	public long getPartyId() {
		return partyId;
	}
	public BpdBossPresence withPartyId(long partyId) {
		this.partyId = partyId;
		return this;
	}
	BpdDefenceSync getOfferedHistory() {
		return offeredHistory;
	}
	void offerHistory(BpdDefenceSync history) {
		offeredHistory = history;
	}
}

package net.betterpartydefence;

import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import lombok.ToString;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.betterpartydefence.DefenceTracker.SpellDrain;
import net.betterpartydefence.DefenceTracker.SyncState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.party.messages.PartyMemberMessage;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

// Full defence snapshot used to recover party state.
@ToString(doNotUseGetters = true)
public class BpdDefenceSync extends PartyMemberMessage {
	public static final int PROTOCOL_VERSION = 2;
	private static final int LEGACY_PROTOCOL_VERSION = 1;
	private static final int COORDINATE_MASK = 0x3fff;
	public static final int SCOPE_WORLD = 0;
	public static final int SCOPE_COX = 1;
	public static final int SCOPE_TOB = 2;
	public static final int SCOPE_INSTANCE = 3;

	@SerializedName(value = "v", alternate = "protocolVersion")
	private int protocolVersion;

	@SerializedName(value = "w", alternate = "world")
	private int world;

	@SerializedName(value = "b", alternate = "bossType")
	private String bossType;

	@SerializedName(value = "n", alternate = "bossName")
	private String bossName;

	@SerializedName(value = "s", alternate = "scopeType")
	private Integer scopeType;

	@SerializedName(value = "i", alternate = "scopeId")
	private Integer scopeId;

	@SerializedName("p")
	@ToString.Exclude
	private Integer bossLocation;

	@SerializedName(value = "h", alternate = "healthPercent")
	private Integer healthPercent;

	@SerializedName(value = "t", alternate = "sentAtMillis")
	private long sentAtMillis;

	@SerializedName(value = "r", alternate = "stateVersion")
	private Long stateVersion;

	@SerializedName(value = "u", alternate = "syncUncertain")
	private Boolean syncUncertain;

	@SerializedName(value = "d", alternate = "current")
	private long current;

	@SerializedName(value = "f", alternate = "min")
	private long min;

	@SerializedName(value = "a", alternate = "base")
	private long base;

	@SerializedName(value = "at", alternate = "attackLevel")
	private Long attackLevel;

	@SerializedName(value = "st", alternate = "strengthLevel")
	private Long strengthLevel;

	@SerializedName(value = "ml", alternate = "magicLevel")
	private long magicLevel;

	@SerializedName(value = "mb", alternate = "magicBaseLevel")
	private long magicBaseLevel;

	@SerializedName(value = "md", alternate = "magicDef")
	private Long magicDef;

	@SerializedName(value = "m", alternate = "magicBaseDef")
	private Long magicBaseDef;

	@SerializedName(value = "mu", alternate = "magicUsesDefence")
	private Boolean magicUsesDefence;

	@SerializedName(value = "dm", alternate = "demon")
	private Boolean demon;

	@SerializedName(value = "ac", alternate = "accursedApplied")
	private Boolean accursedApplied;

	@SerializedName(value = "dr", alternate = "drained")
	private Boolean drained;

	@SerializedName(value = "hp", alternate = "historyPlayers")
	private List<String> historyPlayers;

	@SerializedName(value = "hw", alternate = "historyWeapons")
	private List<String> historyWeapons;

	@SerializedName(value = "hh", alternate = "historyHits")
	private List<Integer> historyHits;

	@SerializedName(value = "ev", alternate = "eventVersion")
	private Integer eventVersion;

	@SerializedName(value = "ei", alternate = "historyEventIds")
	private List<String> historyEventIds;

	@SerializedName(value = "ea", alternate = "historyTickAnchors")
	private List<String> historyTickAnchors;

	@SerializedName(value = "et", alternate = "historyEncounterTicks")
	private List<Long> historyEncounterTicks;

	@SerializedName(value = "eo", alternate = "historyObservedAtMillis")
	private List<Long> historyObservedAtMillis;

	// Version 1 location and session fields.
	@ToString.Exclude
	private Integer bossX;
	@ToString.Exclude
	private Integer bossY;
	@ToString.Exclude
	private Integer bossPlane;
	@ToString.Exclude
	private Long partyId;

	// Gson.
	public BpdDefenceSync() {
	}

	// Keep the constructor used by older callers.
	public BpdDefenceSync(int world, SyncState state, int scopeType, int scopeId,
			int bossX, int bossY, int bossPlane, int healthPercent) {
		this(world, state, scopeType, scopeId, bossX, bossY, bossPlane, healthPercent, 0L);
	}

	public BpdDefenceSync(
			int world,
			SyncState state,
			int scopeType,
			int scopeId,
			int bossX,
			int bossY,
			int bossPlane,
			int healthPercent,
			long stateVersion) {
		this.protocolVersion = PROTOCOL_VERSION;
		this.world = world;
		this.bossType = state.getBossType().name();
		this.bossName = state.getBossType().getNpcName().equals(state.getBossName()) ? null : state.getBossName();
		this.scopeType = scopeType == SCOPE_WORLD ? null : scopeType;
		this.scopeId = scopeId == 0 ? null : scopeId;
		this.bossLocation = packBossLocation(bossX, bossY, bossPlane);
		this.healthPercent = scopeType == SCOPE_WORLD && healthPercent >= 0 ? healthPercent : null;
		this.sentAtMillis = System.currentTimeMillis();
		this.stateVersion = stateVersion > 0 ? stateVersion : null;
		this.current = state.getCurrent();
		this.min = state.getMin();
		this.base = state.getBase();
		this.attackLevel = state.getAttackLevel() == state.getBossType().getBaseAtk() ? null : state.getAttackLevel();
		this.strengthLevel = state.getStrengthLevel() == state.getBossType().getBaseStr()
				? null
				: state.getStrengthLevel();
		this.magicLevel = state.getMagicLevel();
		this.magicBaseLevel = state.getMagicBaseLevel();
		this.magicDef = state.getMagicDef() == 0 ? null : state.getMagicDef();
		this.magicBaseDef = state.getMagicBaseDef() == 0 ? null : state.getMagicBaseDef();
		this.magicUsesDefence = state.isMagicUsesDefence() ? Boolean.TRUE : null;
		this.demon = state.isDemon() ? Boolean.TRUE : null;
		this.accursedApplied = state.isAccursedApplied() ? Boolean.TRUE : null;
		this.drained = state.isDrained() ? Boolean.TRUE : null;

		List<SpecHistoryEntry> history = state.getHistory();

		this.historyEventIds = new ArrayList<>(history.size());
		this.historyTickAnchors = new ArrayList<>(history.size());
		this.historyEncounterTicks = new ArrayList<>(history.size());
		this.historyObservedAtMillis = new ArrayList<>(history.size());
		this.historyPlayers = new ArrayList<>(history.size());
		this.historyWeapons = new ArrayList<>(history.size());
		this.historyHits = new ArrayList<>(history.size());
		for (SpecHistoryEntry entry : history) {
			historyEventIds.add(entry.getEventId());
			historyTickAnchors.add(entry.getTickAnchor());
			historyEncounterTicks.add(entry.getEncounterTick());
			historyObservedAtMillis.add(entry.getObservedAtMillis() > 0 ? entry.getObservedAtMillis() : null);
			historyPlayers.add(entry.getPlayerName());
			historyWeapons.add(entry.getSpell() == null
					? (entry.getWeapon() == null ? "" : entry.getWeapon().name())
					: "spell:" + entry.getSpell().name());
			historyHits.add(entry.getHit());
		}
		if (historyEventIds.stream().anyMatch(Objects::nonNull)) {
			this.eventVersion = EncounterTimeline.VERSION;
		} else {
			historyEventIds = null;
			historyTickAnchors = null;
			historyEncounterTicks = null;
		}
		if (historyObservedAtMillis.stream().allMatch(Objects::isNull)) {
			historyObservedAtMillis = null;
		}
	}

	static Integer packBossLocation(int x, int y, int plane) {
		if ((x == 0 && y == 0) || (x & ~COORDINATE_MASK) != 0
				|| (y & ~COORDINATE_MASK) != 0 || plane < 0 || plane > 3) {
			return null;
		}
		return (plane << 28) | (x << 14) | y;
	}

	@ToString.Include(name = "location")
	public WorldPoint getBossLocation() {
		if (bossLocation != null) {
			return bossLocation > 0 && bossLocation >>> 30 == 0 ? WorldPoint.fromCoord(bossLocation) : null;
		}
		Integer legacy = bossX == null || bossY == null || bossPlane == null
				? null
				: packBossLocation(bossX, bossY, bossPlane);
		return legacy == null ? null : WorldPoint.fromCoord(legacy);
	}

	public boolean isSupportedProtocol() {
		return protocolVersion == PROTOCOL_VERSION || protocolVersion == LEGACY_PROTOCOL_VERSION;
	}

	public SyncState toSyncState() {
		if (!isSupportedProtocol()) {
			return null;
		}
		BossDefence boss;
		BossDefence decodedBoss;
		try {
			decodedBoss = BossDefence.valueOf(bossType);
			boss = decodedBoss.trackingType();
		} catch (RuntimeException ex) {
			return null;
		}

		// BGS spillover needs NPC attack and strength levels.
		long bossAttack = attackLevel != null
				? attackLevel
				: protocolVersion == LEGACY_PROTOCOL_VERSION ? 0L : boss.getBaseAtk();
		long bossStrength = strengthLevel != null
				? strengthLevel
				: protocolVersion == LEGACY_PROTOCOL_VERSION ? 0L : boss.getBaseStr();

		// Reject partial or inconsistent histories.
		if (Boolean.TRUE.equals(syncUncertain) || historyPlayers == null || historyWeapons == null
				|| historyHits == null
				|| historyPlayers.size() != historyWeapons.size() || historyPlayers.size() != historyHits.size()
				|| historyPlayers.size() > 4096 || (isDrained() && historyPlayers.isEmpty())
				|| base < 0 || min < 0 || min > base || current < min || current > base
				|| bossAttack < 0 || bossStrength < 0 || magicLevel < 0 || magicBaseLevel < 0) {
			return null;
		}
		List<SpecHistoryEntry> history = new ArrayList<>();
		int size = historyPlayers.size();
		boolean eventsSupported = getEventVersion() == EncounterTimeline.VERSION
				&& size <= EncounterTimeline.MAX_EVENTS
				&& historyEventIds != null && historyEventIds.size() == size
				&& historyTickAnchors != null && historyTickAnchors.size() == size
				&& historyEncounterTicks != null && historyEncounterTicks.size() == size;
		boolean timestampsSupported = eventsSupported && historyObservedAtMillis != null
				&& historyObservedAtMillis.size() == size;
		for (int i = 0; i < size; i++) {
			try {
				String weaponName = historyWeapons.get(i);
				Integer hit = historyHits.get(i);
				if (weaponName == null || hit == null || hit < 0) {
					return null;
				}
				SpellDrain spell = weaponName.startsWith("spell:") ? SpellDrain.valueOf(weaponName.substring(6)) : null;
				SpecialWeapon weapon = spell == null ? SpecialWeapon.valueOf(weaponName) : null;
				if (spell == null ? !SpecialWeaponRules.isSupported(weapon) : hit != 1) {
					return null;
				}
				String player = historyPlayers.get(i);
				if (player == null || player.trim().isEmpty()) {
					player = "Unknown";
				}
				String id = eventsSupported ? historyEventIds.get(i) : null;
				String anchor = eventsSupported ? historyTickAnchors.get(i) : null;
				Long tick = eventsSupported ? historyEncounterTicks.get(i) : null;
				if (id != null && !id.isEmpty() && id.length() <= 128 && anchor != null
						&& !anchor.isEmpty() && anchor.length() <= 128 && tick != null && tick >= 0) {
					Long observedAt = timestampsSupported ? historyObservedAtMillis.get(i) : null;
					history.add(new SpecHistoryEntry(player, weapon, spell, hit, id, anchor, tick,
							observedAt == null ? 0L : Math.max(0L, observedAt)));
				} else {
					history.add(new SpecHistoryEntry(player, weapon, spell, hit, null, null, -1));
				}
			} catch (RuntimeException ignored) {
				// Unknown rows invalidate the snapshot.
				return null;
			}
		}

		return new SyncState(
				decodedBoss == BossDefence.TEKTON_ENRAGED
						? boss.getNpcName()
						: bossName == null ? boss.getNpcName() : bossName,
				boss,
				current,
				min,
				base,
				bossAttack,
				bossStrength,
				magicLevel,
				magicBaseLevel,
				magicDef == null ? 0L : magicDef,
				magicBaseDef == null ? 0L : magicBaseDef,
				Boolean.TRUE.equals(magicUsesDefence),
				Boolean.TRUE.equals(demon),
				Boolean.TRUE.equals(accursedApplied),
				Boolean.TRUE.equals(drained),
				Collections.unmodifiableList(history));
	}

	public int getEventVersion() {
		return eventVersion == null ? 0 : eventVersion;
	}
	public int getProtocolVersion() {
		return protocolVersion;
	}
	public int getWorld() {
		return world;
	}
	public String getBossType() {
		return bossType;
	}
	public int getScopeType() {
		return scopeType == null ? SCOPE_WORLD : scopeType;
	}
	public int getScopeId() {
		return scopeId == null ? 0 : scopeId;
	}
	public int getHealthPercent() {
		return healthPercent == null ? -1 : healthPercent;
	}
	public long getSentAtMillis() {
		return sentAtMillis;
	}
	public long getPartyId() {
		return partyId == null ? 0L : partyId;
	}
	public long getStateVersion() {
		return stateVersion == null ? 0L : stateVersion;
	}
	public boolean isDrained() {
		return Boolean.TRUE.equals(drained);
	}
}

