// One observed spec; the party message supplies the sender.
@Getter
@ToString(doNotUseGetters = true)
public final class BpdSpecEvent extends PartyMemberMessage {
	@SerializedName("w")
	private int world;
	@SerializedName("s")
	private int scopeType;
	@SerializedName("i")
	private Integer scopeId;
	@SerializedName("b")
	private BossDefence boss;
	@ToString.Exclude
	@SerializedName("p")
	private int tile;
	@SerializedName("n")
	private int npcIndex;
	@SerializedName("hp")
	private Integer healthPercent;
	@SerializedName("a")
	private String anchor;
	@SerializedName("t")
	private long tick;
	@SerializedName("u")
	private Long observedAt;
	@SerializedName("m")
	private long sentAt;
	@SerializedName("e")
	private String eventId;
	@SerializedName("r")
	private String previousId;
	@SerializedName("k")
	private SpecialWeapon weapon;
	@SerializedName("l")
	private SpellDrain spell;
	@SerializedName("h")
	private int hit;

	BpdSpecEvent() {
		// Gson.
	}

	BpdSpecEvent(int world, int scopeType, int scopeId, BossDefence boss, int npcIndex, int tile, int healthPercent,
			SpecHistoryEntry entry, String previousId) {
		this.world = world;
		this.scopeType = scopeType;
		this.scopeId = scopeId == 0 ? null : scopeId;
		this.boss = boss;
		this.tile = tile;
		this.npcIndex = npcIndex;
		this.healthPercent = healthPercent >= 0 ? healthPercent : null;
		this.anchor = entry.getTickAnchor().equals(entry.getEventId()) ? null : entry.getTickAnchor();
		this.tick = entry.getEncounterTick();
		this.sentAt = System.currentTimeMillis();
		this.observedAt = entry.getObservedAtMillis() > 0 ? entry.getObservedAtMillis() : null;
		this.eventId = entry.getEventId();
		this.previousId = previousId;
		this.weapon = entry.getWeapon();
		this.spell = entry.getSpell();
		this.hit = entry.getHit();
	}

	int getScopeId() {
		return scopeId == null ? 0 : scopeId;
	}

	int getHealthPercent() {
		return healthPercent == null ? -1 : healthPercent;
	}

	BossDefence getBoss() {
		return boss == null ? null : boss.trackingType();
	}

	@ToString.Include
	WorldPoint location() {
		return tile > 0 && tile >>> 30 == 0 ? WorldPoint.fromCoord(tile) : null;
	}

	SpecHistoryEntry historyEntry(String player) {
		if (!validId(eventId) || anchor != null && !validId(anchor)
				|| previousId != null && (!validId(previousId) || eventId.equals(previousId))
				|| tick < 0 || hit < 0 || hit > 65535 || weapon == SpecialWeapon.TONALZTICS_OF_RALOS && hit > 2
				|| healthPercent != null && (healthPercent < 0 || healthPercent > 100)) {
			return null;
		}
		SpecHistoryEntry entry = new SpecHistoryEntry(player, weapon, spell, hit, eventId,
				anchor == null ? eventId : anchor, tick,
				observedAt != null && observedAt > 0 && observedAt <= sentAt ? observedAt : 0);
		return entry.isSupported() ? entry : null;
	}

	private static boolean validId(String id) {
		return id != null && !id.isEmpty() && id.length() <= 128;
	}

}

package net.betterpartydefence;

import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.betterpartydefence.DefenceTracker.SpellDrain;
import net.betterpartydefence.DefenceTracker.SyncState;
import net.runelite.api.NPC;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

// Mutable stats for one encounter. The tracker owns target and party state.
final class CombatStats {
	private static final int DWH_DRAIN_PCT = 30;
	private static final int ELDER_MAUL_DRAIN_PCT = 35;
	// Condemn keeps 85% of current values.
	private static final int CONDEMN_KEEPS_PCT = 85;
	private static final int ARCLIGHT_DRAIN_PCT = 5;
	private static final int ARCLIGHT_DEMON_DRAIN_PCT = 10;
	private static final int EMBERLIGHT_DRAIN_PCT = 5;
	private static final int EMBERLIGHT_DEMON_DRAIN_PCT = 15;
	// Each Ralos glaive drains one eighth of current Magic.
	private static final int RALOS_GLAIVE_MAGIC_DIVISOR = 8;
	private static final int ANCHOR_DAMAGE_DIVISOR = 10;

	private static final int CM_SCALE_PCT = 50;
	private static final int TEKTON_CM_SMALL_PARTY = 4;
	private static final int TEKTON_CM_DEFENCE_PCT_SMALL_PARTY = 20;
	private static final int TEKTON_CM_DEFENCE_PCT = 35;

	long defence = -1;
	long startDefence;
	long minDefence;
	long attackLevel;
	long strengthLevel;
	long magicLevel;
	long startMagicLevel;
	long magicDefenceBonus;
	long startMagicDefenceBonus;
	boolean magicUsesDefence;
	boolean demon;
	boolean accursedApplied;
	boolean drained;

	static CombatStats initial(BossDefence boss, int partySize, boolean inCoxRaid, boolean challengeMode) {
		CombatStats stats = new CombatStats();
		if (boss == null) {
			return stats;
		}

		stats.defence = boss.getBaseDef();
		stats.minDefence = boss.getMinDef();
		stats.attackLevel = boss.getBaseAtk();
		stats.strengthLevel = boss.getBaseStr();
		stats.magicLevel = boss.getBaseMagic();
		stats.magicDefenceBonus = boss.getBaseMagicDef();
		stats.magicUsesDefence = boss.has(BossDefence.Flag.MAGIC_USES_DEFENCE);
		stats.demon = boss.has(BossDefence.Flag.DEMON);

		// CoX scales combat levels, not the magic-defence bonus.
		if (boss.has(BossDefence.Flag.COX_SCALED) && inCoxRaid) {
			int players = Math.max(1, partySize);
			int extraPlayers = players - 1;
			int defensivePercent = DefenceMath.coxDefensivePercent(extraPlayers);
			int offensivePercent = DefenceMath.coxOffensivePercent(extraPlayers);
			boolean magicIsDefensive = boss.has(BossDefence.Flag.COX_MAGIC_SCALED);

			stats.defence = stats.defence * defensivePercent / DefenceMath.PERCENT;
			stats.magicLevel = stats.magicLevel
					* (magicIsDefensive ? defensivePercent : offensivePercent) / DefenceMath.PERCENT;

			if (challengeMode) {
				int challengeModeDefence = boss.has(BossDefence.Flag.TEKTON_CM)
						? (players < TEKTON_CM_SMALL_PARTY
								? TEKTON_CM_DEFENCE_PCT_SMALL_PARTY
								: TEKTON_CM_DEFENCE_PCT)
						: CM_SCALE_PCT;
				stats.defence = DefenceMath.addPercent(stats.defence, challengeModeDefence);
				stats.magicLevel = DefenceMath.addPercent(
						stats.magicLevel, magicIsDefensive ? challengeModeDefence : CM_SCALE_PCT);
			}
		}

		stats.startDefence = stats.defence;
		stats.startMagicLevel = stats.magicLevel;
		stats.startMagicDefenceBonus = stats.magicDefenceBonus;
		return stats;
	}

	static CombatStats fromSync(SyncState sync) {
		CombatStats stats = new CombatStats();
		stats.defence = sync.getCurrent();
		stats.minDefence = sync.getMin();
		stats.startDefence = sync.getBase();
		stats.attackLevel = sync.getAttackLevel();
		stats.strengthLevel = sync.getStrengthLevel();
		stats.magicLevel = sync.getMagicLevel();
		stats.startMagicLevel = sync.getMagicBaseLevel();
		stats.magicDefenceBonus = sync.getMagicDef();
		stats.startMagicDefenceBonus = sync.getMagicBaseDef();
		stats.magicUsesDefence = sync.isMagicUsesDefence();
		stats.demon = sync.isDemon();
		stats.accursedApplied = sync.isAccursedApplied();
		stats.drained = true;
		return stats;
	}

	CombatStats copy() {
		CombatStats copy = new CombatStats();
		copy.defence = defence;
		copy.startDefence = startDefence;
		copy.minDefence = minDefence;
		copy.attackLevel = attackLevel;
		copy.strengthLevel = strengthLevel;
		copy.magicLevel = magicLevel;
		copy.startMagicLevel = startMagicLevel;
		copy.magicDefenceBonus = magicDefenceBonus;
		copy.startMagicDefenceBonus = startMagicDefenceBonus;
		copy.magicUsesDefence = magicUsesDefence;
		copy.demon = demon;
		copy.accursedApplied = accursedApplied;
		copy.drained = drained;
		return copy;
	}

	CombatStats undrainedBaseline(BossDefence boss) {
		CombatStats baseline = copy();
		baseline.defence = baseline.startDefence;
		baseline.attackLevel = boss.getBaseAtk();
		baseline.strengthLevel = boss.getBaseStr();
		baseline.magicLevel = baseline.startMagicLevel;
		baseline.magicDefenceBonus = baseline.startMagicDefenceBonus;
		baseline.accursedApplied = false;
		baseline.drained = false;
		return baseline;
	}

	void applyHistoryEvent(SpecHistoryEntry event, NPC npc, BossDefence bossType, String bossName) {
		if (event.getSpell() != null) {
			applySpell(event.getSpell(), bossType);
			return;
		}
		int hit = npc == null ? event.getHit() : event.getWeapon().computeHit(event.getHit(), npc);
		applyWeapon(event.getWeapon(), hit, npc, bossName);
	}

	void applySpell(SpellDrain spell, BossDefence bossType) {
		defence = spell.reduce(defence, startDefence, minDefence);
		if (spell == SpellDrain.SHADOW_BARRAGE) {
			attackLevel = spell.reduce(attackLevel, bossType.getBaseAtk(), 0);
			strengthLevel = spell.reduce(strengthLevel, bossType.getBaseStr(), 0);
		}
	}

	void applyWeapon(SpecialWeapon weapon, int hit, NPC npc, String bossName) {
		// DWH and Elder Maul use current defence.
		// Arclight-family drains use the encounter base.
		long base = startDefence;
		switch (weapon) {
			case DRAGON_WARHAMMER:
				drainCurrentDefence(weapon, hit, npc, DWH_DRAIN_PCT);
				break;
			case ELDER_MAUL:
				drainCurrentDefence(weapon, hit, npc, ELDER_MAUL_DRAIN_PCT);
				break;
			case BANDOS_GODSWORD:
				if (hit > 0) {
					// Corp and undowned Bloat take double BGS.
					boolean doubled = bossName.equalsIgnoreCase("Corporeal Beast")
							|| bossName.equalsIgnoreCase("Pestilent Bloat");
					applyBandos(doubled ? hit * 2L : hit);
				}
				break;
			case TONALZTICS_OF_RALOS:
				// hit is the number of connected glaives, not damage.
				defence -= (magicLevel / RALOS_GLAIVE_MAGIC_DIVISOR) * Math.max(0, hit);
				break;
			case ARCLIGHT:
			case DARKLIGHT:
				drainBaseDefence(hit, ARCLIGHT_DRAIN_PCT, ARCLIGHT_DEMON_DRAIN_PCT);
				break;
			case EMBERLIGHT:
				drainBaseDefence(hit, EMBERLIGHT_DRAIN_PCT, EMBERLIGHT_DEMON_DRAIN_PCT);
				break;
			case BARRELCHEST_ANCHOR:
				defence -= hit / ANCHOR_DAMAGE_DIVISOR;
				break;
			case BONE_DAGGER:
			case DORGESHUUN_CROSSBOW:
				if (defence >= base) {
					defence -= hit;
				}
				break;
			case ACCURSED_SCEPTRE:
				// Only the first landed Condemn applies.
				if (hit > 0 && !accursedApplied) {
					accursedApplied = true;
					defence = defence * CONDEMN_KEEPS_PCT / DefenceMath.PERCENT;
					magicLevel = magicLevel * CONDEMN_KEEPS_PCT / DefenceMath.PERCENT;
				}
				break;
			case SEERCULL:
				// Soulshot drains Magic by damage and stacks.
				magicLevel -= hit;
				break;
			case EYE_OF_AYAK:
				// Soul Rend drains magic-defence bonus down to zero.
				if (hit > 0 && magicDefenceBonus > 0) {
					magicDefenceBonus = Math.max(0, magicDefenceBonus - hit);
				}
				break;
			default:
				return;
		}
		defence = Math.max(defence, minDefence);
		magicLevel = Math.max(magicLevel, 0);
	}

	void keepConservativeMaximum(CombatStats other) {
		defence = Math.max(defence, other.defence);
		attackLevel = Math.max(attackLevel, other.attackLevel);
		strengthLevel = Math.max(strengthLevel, other.strengthLevel);
		magicLevel = Math.max(magicLevel, other.magicLevel);
		magicDefenceBonus = Math.max(magicDefenceBonus, other.magicDefenceBonus);
		accursedApplied &= other.accursedApplied;
	}

	// Skip equivalent orders that unlock the same events.
	static String effectKey(SpecHistoryEntry event, NPC npc) {
		if (event != null && event.getSpell() != null) {
			return event.getSpell().name();
		}
		if (event == null || event.getWeapon() == null) {
			return null;
		}
		SpecialWeapon weapon = event.getWeapon();
		int hit = npc == null ? event.getHit() : weapon.computeHit(event.getHit(), npc);
		switch (weapon) {
			case DRAGON_WARHAMMER:
			case ELDER_MAUL:
				// Only whether the hit landed and Tekton's miss drain affect the result.
				return hit > 0
						? weapon.name() + ":positive"
						: weapon.name() + ":zero:" + (weapon.computeDrainPercent(hit, npc) > 0 ? 1 : 0);
			case ARCLIGHT:
			case DARKLIGHT:
			case EMBERLIGHT:
				// Drain uses encounter base defence.
				return weapon.name() + (hit > 0 ? ":positive" : ":zero");
			case ACCURSED_SCEPTRE:
				// Only the first Condemn matters.
				return weapon.name() + (hit > 0 ? ":positive" : ":zero");
			default:
				// These formulas use the hit value.
				return weapon.name() + ":" + hit;
		}
	}

	private void drainCurrentDefence(SpecialWeapon weapon, int hit, NPC npc, int percent) {
		if (hit > 0) {
			defence -= defence * percent / DefenceMath.PERCENT;
		} else if (weapon.computeDrainPercent(hit, npc) > 0) {
			// Tekton hammer and maul misses drain 5%.
			defence -= defence * 5 / DefenceMath.PERCENT;
		}
	}

	private void drainBaseDefence(int hit, int percent, int demonPercent) {
		if (hit > 0) {
			defence -= startDefence * (demon ? demonPercent : percent) / DefenceMath.PERCENT + 1;
		}
	}

	private void applyBandos(long damage) {
		DefenceMath.BandosResult result = DefenceMath.applyBandos(
				defence, minDefence, strengthLevel, attackLevel, magicLevel, damage);
		defence = result.getDefence();
		strengthLevel = result.getStrength();
		attackLevel = result.getAttack();
		magicLevel = result.getMagic();
	}
}

package net.betterpartydefence;

import java.io.File;
import javax.swing.JFileChooser;
import javax.swing.SwingUtilities;
import javax.swing.filechooser.FileNameExtensionFilter;
import net.betterpartydefence.BetterPartyDefenceConfig.TrackerFont;
import net.runelite.client.config.ConfigManager;

// Selects and stores a local font without blocking the game thread.
final class CustomFontChooser {
	private final BetterPartyDefenceConfig config;
	private final ConfigManager configManager;

	CustomFontChooser(BetterPartyDefenceConfig config, ConfigManager configManager) {
		this.config = config;
		this.configManager = configManager;
	}

	void choose() {
		SwingUtilities.invokeLater(() -> {
			JFileChooser chooser = new JFileChooser();
			chooser.setDialogTitle("Choose a font for Better Party Defence");
			chooser.setFileFilter(new FileNameExtensionFilter("Font files (*.ttf, *.otf)", "ttf", "otf"));

			String current = config.customFontPath();
			if (current != null && !current.trim().isEmpty()) {
				File file = new File(current);
				if (file.getParentFile() != null) {
					chooser.setCurrentDirectory(file.getParentFile());
				}
			}

			if (chooser.showOpenDialog(null) == JFileChooser.APPROVE_OPTION) {
				setConfiguration(BetterPartyDefenceConfig.KEY_CUSTOM_FONT_PATH,
						chooser.getSelectedFile().getAbsolutePath());
				setConfiguration(BetterPartyDefenceConfig.KEY_DEFENCE_FONT, TrackerFont.CUSTOM);
			} else {
				TrackerFont fallback = current == null || current.trim().isEmpty()
						? TrackerFont.RUNESCAPE
						: TrackerFont.CUSTOM;
				setConfiguration(BetterPartyDefenceConfig.KEY_DEFENCE_FONT, fallback);
			}
		});
	}

	private void setConfiguration(String key, Object value) {
		configManager.setConfiguration(BetterPartyDefenceConfig.GROUP, key, value);
	}
}

package net.betterpartydefence;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;
import net.betterpartydefence.DefenceTracker.DefenceState;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Projectile;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.events.GraphicChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.Text;

/**
 * Owns status-bar info boxes and boss-effect presentation.
 */
final class DefenceDisplayController
{
	private final Client client;
	private final ClientThread clientThread;
	private final BetterPartyDefenceConfig config;
	private final DefenceTracker tracker;
	private final InfoBoxManager infoBoxManager;
	private final ItemManager itemManager;
	private final SkillIconManager skillIconManager;
	private final InitialSyncDisplayGate initialSyncDisplayGate;

	private DefenceOverlayRenderer.IconSource iconSource;
	private BetterPartyDefencePlugin owner;
	private DefenceInfoBox defenceBox;
	private DefenceInfoBox magicDefenceBox;
	private BossEffectTracker bossEffects;
	private BossEffectInfoBoxes bossEffectBoxes;
	private final Map<SpecialWeapon, SpecWeaponInfoBox> specWeaponBoxes = new LinkedHashMap<>();

	DefenceDisplayController(
		Client client,
		ClientThread clientThread,
		BetterPartyDefenceConfig config,
		DefenceTracker tracker,
		InfoBoxManager infoBoxManager,
		ItemManager itemManager,
		SkillIconManager skillIconManager,
		InitialSyncDisplayGate initialSyncDisplayGate)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.tracker = tracker;
		this.infoBoxManager = infoBoxManager;
		this.itemManager = itemManager;
		this.skillIconManager = skillIconManager;
		this.initialSyncDisplayGate = initialSyncDisplayGate;
	}

	void start(BetterPartyDefencePlugin plugin)
	{
		owner = plugin;
		bossEffects = new BossEffectTracker(client, clientThread, tracker);
		bossEffectBoxes = new BossEffectInfoBoxes(client, tracker);
		iconSource = new DefenceOverlayRenderer.IconSource(client, skillIconManager, config);
	}

	void shutdown()
	{
		reset();
		bossEffects = null;
		bossEffectBoxes = null;
		iconSource = null;
		owner = null;
	}

	DefenceOverlayRenderer.IconSource iconSource()
	{
		return iconSource;
	}

	void onSpecialEnergy(int energy)
	{
		if (bossEffects != null)
		{
			bossEffects.onSpecialEnergy(energy);
		}
	}

	void onHitsplatApplied(HitsplatApplied event)
	{
		if (bossEffects != null)
		{
			bossEffects.onHitsplatApplied(event);
		}
	}

	void onAnimationChanged(Actor actor)
	{
		if (bossEffects != null)
		{
			bossEffects.onLocalAnimation(actor);
		}
	}

	void onProjectileMoved(Projectile projectile)
	{
		if (bossEffects != null)
		{
			bossEffects.onProjectileMoved(projectile);
		}
	}

	void onGraphicChanged(GraphicChanged event)
	{
		if (bossEffects != null)
		{
			bossEffects.onGraphicChanged(event.getActor());
		}
	}

	void settleKeris()
	{
		if (bossEffects != null)
		{
			bossEffects.settleKeris(owner);
		}
	}

	void applyKerisTimer(NPC npc, int expiry, long hitAtMillis)
	{
		if (bossEffects != null)
		{
			bossEffects.applyKerisTimer(npc, expiry, hitAtMillis);
		}
	}

	void clearBoss(BossDefence boss)
	{
		if (bossEffects != null)
		{
			bossEffects.clearBoss(boss);
		}
	}

	boolean hasDefenceInfoBoxes()
	{
		return defenceBox != null || magicDefenceBox != null;
	}

	void update(boolean ocellusPhaseOneEnded)
	{
		DefenceState state = tracker.state();
		boolean live = state != null && trackedNpcIsLive(state, ocellusPhaseOneEnded);
		boolean awaitingInitialSync = state != null
			&& initialSyncDisplayGate.isWaiting(state, client.getTickCount());
		boolean showDefence = config.defenceInfoBox() && live && !awaitingInitialSync
			&& (tracker.hasDefenceSpecHistory() || config.defenceAlwaysShow());
		boolean showMagic = config.magicDefence() && config.magicDefenceInfoBox() && live
			&& !awaitingInitialSync
			&& DefenceReadout.magicDefenceVisible(state)
			&& (tracker.hasMagicDefenceSpecHistory() || config.defenceAlwaysShow());

		updateDefenceBox(showDefence);
		updateMagicDefenceBox(showMagic);
		updateSpecWeaponInfoBoxes(state, live && !awaitingInitialSync);
		if (bossEffects != null)
		{
			bossEffects.updateObservations();
		}
		if (bossEffectBoxes != null)
		{
			bossEffectBoxes.update(owner, infoBoxManager, itemManager, skillIconManager,
				config.showRedKeris(), config.showShadowBarrage(), config.showVulnerability());
		}
	}

	void removeAll()
	{
		if (bossEffectBoxes != null)
		{
			bossEffectBoxes.hide(infoBoxManager);
		}
		clearSpecWeaponInfoBoxes();
		removeBox(defenceBox);
		removeBox(magicDefenceBox);
		defenceBox = null;
		magicDefenceBox = null;
	}

	void reset()
	{
		if (bossEffects != null)
		{
			bossEffects.reset();
		}
		removeAll();
	}

	private void updateDefenceBox(boolean show)
	{
		if (show && defenceBox == null)
		{
			defenceBox = new DefenceInfoBox(infoBoxSkillIcon(Skill.DEFENCE), owner, tracker, config);
			infoBoxManager.addInfoBox(defenceBox);
		}
		else if (!show && defenceBox != null)
		{
			infoBoxManager.removeInfoBox(defenceBox);
			defenceBox = null;
		}
	}

	private void updateMagicDefenceBox(boolean show)
	{
		if (show && magicDefenceBox == null)
		{
			magicDefenceBox = new DefenceInfoBox(infoBoxSkillIcon(Skill.MAGIC), owner, tracker, config,
				DefenceInfoBox.Stat.MAGIC_DEFENCE);
			infoBoxManager.addInfoBox(magicDefenceBox);
		}
		else if (!show && magicDefenceBox != null)
		{
			infoBoxManager.removeInfoBox(magicDefenceBox);
			magicDefenceBox = null;
		}
	}

	private BufferedImage infoBoxSkillIcon(Skill skill)
	{
		if (config.defenceInfoBoxUseThemeSkillIcon() && iconSource != null)
		{
			return skill == Skill.MAGIC ? iconSource.magic(true) : iconSource.defence(true);
		}
		return skillIconManager.getSkillImage(skill);
	}

	private void updateSpecWeaponInfoBoxes(DefenceState state, boolean live)
	{
		if (!config.specWeaponInfoBoxes() || !live || state == null || !state.isDrained())
		{
			clearSpecWeaponInfoBoxes();
			return;
		}

		Map<SpecialWeapon, SpecWeaponSummary> summaries = SpecWeaponSummary.fromHistory(
			tracker.specHistoryForCurrentTarget(state.getNpcIndex()));
		for (SpecialWeapon existing : new ArrayList<>(specWeaponBoxes.keySet()))
		{
			if (!summaries.containsKey(existing))
			{
				infoBoxManager.removeInfoBox(specWeaponBoxes.remove(existing));
			}
		}
		for (Map.Entry<SpecialWeapon, SpecWeaponSummary> entry : summaries.entrySet())
		{
			SpecialWeapon weapon = entry.getKey();
			SpecWeaponInfoBox box = specWeaponBoxes.get(weapon);
			if (box == null)
			{
				int[] itemIds = weapon.getItemID();
				BufferedImage icon = itemIds != null && itemIds.length > 0
					? itemManager.getImage(itemIds[0])
					: null;
				if (icon == null)
				{
					icon = skillIconManager.getSkillImage(Skill.ATTACK);
				}
				box = new SpecWeaponInfoBox(icon, owner, weapon);
				specWeaponBoxes.put(weapon, box);
				infoBoxManager.addInfoBox(box);
			}
			box.update(entry.getValue());
		}
	}

	private void clearSpecWeaponInfoBoxes()
	{
		for (SpecWeaponInfoBox box : specWeaponBoxes.values())
		{
			infoBoxManager.removeInfoBox(box);
		}
		specWeaponBoxes.clear();
	}

	private boolean trackedNpcIsLive(DefenceState state, boolean ocellusPhaseOneEnded)
	{
		if (state.getNpcIndex() < 0)
		{
			return false;
		}
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null || worldView.npcs() == null)
		{
			return false;
		}

		NPC npc = worldView.npcs().byIndex(state.getNpcIndex());
		if (!BossDefence.isLiveNpc(npc))
		{
			return false;
		}
		if (state.isTfaBoss() && npc.getName() != null
			&& "Ocellus".equalsIgnoreCase(Text.removeTags(npc.getName()).trim()))
		{
			BossDefence actor = BossDefence.matchingNpc(npc);
			return actor != null
				&& (actor == BossDefence.TFA_OCELLUS_P1
					|| actor == BossDefence.TFA_OCELLUS_P2
					|| actor == BossDefence.TFA_OCELLUS_P3)
				&& actor.getBaseDef() == state.getBase()
				&& actor.getMinDef() == state.getMin()
				&& (actor != BossDefence.TFA_OCELLUS_P1 || !ocellusPhaseOneEnded);
		}
		return true;
	}

	private void removeBox(DefenceInfoBox box)
	{
		if (box != null)
		{
			infoBoxManager.removeInfoBox(box);
		}
	}
}

package net.betterpartydefence;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import net.betterpartydefence.BetterPartyDefenceConfig.DefenceInfoBoxValue;
import net.betterpartydefence.BetterPartyDefenceConfig.MagicDefenceDisplay;
import net.betterpartydefence.DefenceTracker.DefenceState;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import net.runelite.client.ui.overlay.infobox.InfoBox;

// Status-bar Defence readout with optional spec history.
public class DefenceInfoBox extends InfoBox {
	public enum Stat {
		DEFENCE, MAGIC_DEFENCE
	}

	private static final String DEFAULT_TOOLTIP = "Better Party Defence";

	private final DefenceTracker tracker;
	private final BetterPartyDefenceConfig config;
	private final Stat stat;

	// Reuse the tracker's immutable history snapshot.
	private List<SpecHistoryEntry> tooltipHistory;

	public DefenceInfoBox(BufferedImage image, Plugin plugin, DefenceTracker tracker, BetterPartyDefenceConfig config) {
		this(image, plugin, tracker, config, Stat.DEFENCE);
	}

	public DefenceInfoBox(
			BufferedImage image,
			Plugin plugin,
			DefenceTracker tracker,
			BetterPartyDefenceConfig config,
			Stat stat) {
		super(image, plugin);
		this.tracker = tracker;
		this.config = config;
		this.stat = stat;
		setTooltip(DEFAULT_TOOLTIP);
	}

	@Override
	public String getText() {
		DefenceState state = tracker.state();
		if (state == null) {
			return "";
		}
		// Prevent a stale TFA Magic frame.
		if (stat == Stat.MAGIC_DEFENCE && !DefenceReadout.magicDefenceVisible(state)) {
			return "";
		}
		updateTooltip(state);
		if (stat == Stat.MAGIC_DEFENCE) {
			return magicText(state);
		}

		// Share the overlay's defence-level mode.
		boolean full = config.defenceShowFullLevel();
		long current = DefenceReadout.shownDefence(state, full);
		long base = DefenceReadout.shownBaseDefence(state, full);
		return infoBoxValue(current, base);
	}

	private String magicText(DefenceState state) {
		long rollPercent = DefenceReadout.percentRemaining(state.getMagicRoll(), state.getMagicBaseRoll());
		switch (config.magicDefenceDisplay()) {
			case LEVEL :
				return infoBoxValue(state.getMagicLevel(), state.getMagicBaseLevel());
			case PERCENT :
				return rollPercent + "%";
			case BOTH :
				return state.getMagicDef() + " " + rollPercent + "%";
			case BONUS :
			default :
				return infoBoxValue(state.getMagicDef(), state.getMagicBaseDef());
		}
	}

	private String infoBoxValue(long current, long base) {
		switch (config.defenceInfoBoxValue()) {
			case PERCENT :
				return DefenceReadout.percentRemaining(current, base) + "%";
			case DRAINED :
				return Long.toString(Math.max(0, base - current));
			case CURRENT :
			default :
				return Long.toString(current);
		}
	}

	// Tooltip contains accepted spec history only.
	private void updateTooltip(DefenceState state) {
		if (!config.extraInfoInInfoBox()) {
			if (tooltipHistory != null) {
				tooltipHistory = null;
				setTooltip(DEFAULT_TOOLTIP);
			}
			return;
		}

		List<SpecHistoryEntry> history = tracker.specHistoryForCurrentTarget(state.getNpcIndex());
		if (history == tooltipHistory) {
			return;
		}
		tooltipHistory = history;
		List<SpecHistoryEntry> relevant = relevantHistory(history);
		if (relevant.isEmpty()) {
			setTooltip("No specs yet");
			return;
		}

		StringBuilder tip = new StringBuilder("Spec history:");
		for (SpecSummary summary : aggregateHistory(relevant)) {
			tip.append("<br>");
			if (summary.miss) {
				tip.append("<col=ff0000>");
			}
			tip.append(summary.playerName)
					.append(": ")
					.append(shortWeaponName(summary.weapon));
			if (summary.miss) {
				tip.append(" miss: ")
						.append(summary.value)
						.append("</col>");
			} else {
				tip.append(' ').append(summary.value);
			}
		}
		setTooltip(tip.toString());
	}

	private List<SpecHistoryEntry> relevantHistory(List<SpecHistoryEntry> history) {
		List<SpecHistoryEntry> relevant = new ArrayList<>();
		for (SpecHistoryEntry entry : history) {
			if (entry == null) {
				continue;
			}
			boolean include = stat == Stat.MAGIC_DEFENCE
					? SpecialWeaponRules.drainsMagicDefence(entry.getWeapon())
					: SpecialWeaponRules.drainsDefence(entry.getWeapon());
			if (include) {
				relevant.add(entry);
			}
		}
		return relevant;
	}

	// Fixed-effect specs count uses; BGS counts damage.
	// Keep misses separate and preserve first-seen order.
	private static List<SpecSummary> aggregateHistory(List<SpecHistoryEntry> history) {
		List<SpecSummary> summaries = new ArrayList<>();
		for (SpecHistoryEntry entry : history) {
			if (entry == null) {
				continue;
			}
			SpecialWeapon weapon = entry.getWeapon();
			String player = entry.getPlayerName();
			if (player == null || player.trim().isEmpty()) {
				player = "Unknown";
			}
			boolean miss = entry.getHit() <= 0;
			SpecSummary existing = null;
			for (SpecSummary summary : summaries) {
				if (summary.weapon == weapon && summary.miss == miss && summary.playerName.equals(player)) {
					existing = summary;
					break;
				}
			}

			// Misses count once and never inflate hit totals.
			int amount = miss ? 1 : SpecialWeaponRules.reportedValue(weapon, entry.getHit());
			if (existing == null) {
				summaries.add(new SpecSummary(player, weapon, amount, miss));
			} else {
				existing.value += amount;
			}
		}
		return summaries;
	}

	private static final class SpecSummary {
		private final String playerName;
		private final SpecialWeapon weapon;
		private final boolean miss;
		private int value;

		private SpecSummary(String playerName, SpecialWeapon weapon, int value, boolean miss) {
			this.playerName = playerName;
			this.weapon = weapon;
			this.value = value;
			this.miss = miss;
		}
	}

	private static String shortWeaponName(SpecialWeapon weapon) {
		return SpecialWeaponRules.shortName(weapon);
	}

	@Override
	public Color getTextColor() {
		if (stat == Stat.MAGIC_DEFENCE) {
			return config.magicDefenceColor();
		}
		DefenceState state = tracker.state();
		return state == null ? Color.WHITE : DefenceReadout.defenceColor(state, config);
	}
}

package net.betterpartydefence;

import lombok.Value;

/**
 * Stateless Defence formulas shared by tracking and synchronization.
 */
final class DefenceMath
{
	static final int PERCENT = 100;

	private static final int MAGIC_ROLL_LEVEL_OFFSET = 9;
	private static final int MAGIC_ROLL_BONUS_OFFSET = 64;

	private DefenceMath()
	{
	}

	static long magicRoll(long level, long bonus)
	{
		return (MAGIC_ROLL_LEVEL_OFFSET + level) * (bonus + MAGIC_ROLL_BONUS_OFFSET);
	}

	// Apply an integer percentage increase with truncation.
	static long addPercent(long value, int percent)
	{
		return value + value * percent / PERCENT;
	}

	// CoX defensive scaling for party size.
	static int coxDefensivePercent(int extraPlayers)
	{
		return PERCENT + (int) Math.sqrt(extraPlayers) + extraPlayers * 7 / 10;
	}

	// CoX offensive scaling for party size.
	static int coxOffensivePercent(int extraPlayers)
	{
		return PERCENT + (int) Math.sqrt(extraPlayers) * 7 + extraPlayers;
	}

	/**
	 * BGS drains Defence, then Strength, Attack, and Magic until damage is exhausted.
	 */
	static BandosResult applyBandos(long defence, long defenceFloor, long strength, long attack,
		long magic, long damage)
	{
		long remaining = damage;
		long nextDefence = Math.max(defenceFloor, defence - remaining);
		remaining = nextDefence > 0 ? 0 : remaining - defence;

		long nextStrength = strength;
		if (remaining > 0)
		{
			nextStrength = Math.max(0, strength - remaining);
			remaining = nextStrength > 0 ? 0 : remaining - strength;
		}

		long nextAttack = attack;
		if (remaining > 0)
		{
			nextAttack = Math.max(0, attack - remaining);
			remaining = nextAttack > 0 ? 0 : remaining - attack;
		}

		long nextMagic = remaining > 0 ? Math.max(0, magic - remaining) : magic;
		return new BandosResult(nextDefence, nextStrength, nextAttack, nextMagic);
	}

	@Value
	static class BandosResult
	{
		long defence;
		long strength;
		long attack;
		long magic;
	}
}

