// Tracks defence levels, magic defence, and accepted spec history.
// Uses local observations plus standard party specs.
// Formulas follow osrs-dps-calc with integer truncation.
// Magic roll: (9 + level) * (magic-def bonus + 64).
@Slf4j
@Singleton
public class DefenceTracker {
	enum SpellDrain {
		VULNERABILITY(100), VULNERABILITY_TOME(150), SHADOW_BARRAGE(165);

		private final int perThousand;

		SpellDrain(int perThousand) {
			this.perThousand = perThousand;
		}

		long reduce(long current, long base, long floor) {
			return current == base
					? Math.max(floor, current - current * perThousand / 1000)
					: current;
		}
	}

	private final Client client;
	private final BetterPartyDefenceConfig config;

	// Track live state by NPC scene index.
	private final Map<Integer, SavedState> tracked = new LinkedHashMap<>();
	// Party state saved until a matching NPC appears.
	private final Map<BossDefence, SavedState> unboundTracked = new LinkedHashMap<>();
	// Open-world state after its NPC index changes.
	private final List<SavedState> detachedPublicTargets = new ArrayList<>();

	// -1 means no active target.
	private int bossIndex = -1;
	private String bossName = "";
	private BossDefence bossType;
	private int publicWorld;
	private Integer privateInstance;
	// Last NPC id attached to this encounter.
	private int bossNpcId = -1;
	// Last observed target tile.
	private WorldPoint targetLocation;
	// The local NPC object; never use it to identify the NPC on another client.
	private NPC boundActor;
	// Kephri keeps drains until final enrage.
	private boolean kephriFinalResetApplied;
	// Sotetseg state: 1 combat, 2 maze, 0 ended.
	private int sotetsegEncounterState = -1;
	private CombatStats stats = new CombatStats();
	private EffectState effects;
	private String localTickAnchor;
	private int localAnchorTick;
	// Shared raid clock origin.
	private String sharedTickAnchor;
	private int sharedTickAnchorTick;
	// Raid tick at the shared origin.
	private long sharedTickAnchorValue;

	// Accepted history for the current target.
	private final List<SpecHistoryEntry> specHistory = new ArrayList<>();
	private List<SpecHistoryEntry> specHistorySnapshot;
	private final List<AppliedSpec> localSpecs = new ArrayList<>();
	private static final int STANDARD_SPEC_CORRELATION_TICKS = 2;
	private final Map<SpecHistoryEntry, Integer> recentStandardSpecs = new IdentityHashMap<>();
	// Boss types seen ending on this client.
	private final Set<BossDefence> endedBosses = new LinkedHashSet<>();
	private final Set<BossDefence> endedPublicBosses = new LinkedHashSet<>();

	// Hold specs whose local target is not identifiable yet.
	// Replay keeps simultaneous party hits from diverging.
	private static final int REMEMBERED_TARGET_DISTANCE = 8;
	private final PendingSpecQueue pendingSpecs;
	// Detect a real CoX raid exit.
	private boolean wasInCoxRaid;

	@Value
	public static class DefenceState {
		int npcIndex;
		// Display name without colour tags.
		String name;
		long current;
		long min;
		long base;
		// Current and starting magic roll.
		long magicRoll;
		long magicBaseRoll;
		// Magic-defence bonus drained by Eye of Ayak.
		long magicDef;
		long magicBaseDef;
		// Magic level drained by Accursed and Seercull.
		long magicLevel;
		long magicBaseLevel;
		// True after a supported spec lands.
		boolean drained;
		// Mark TFA bosses for display rules.
		boolean tfaBoss;
	}

	// One accepted encounter spec.
	@Value
	@AllArgsConstructor
	public static class SpecHistoryEntry {
		String playerName;
		SpecialWeapon weapon;
		SpellDrain spell;
		int hit;
		String eventId;
		String tickAnchor;
		long encounterTick;
		@With
		long observedAtMillis;

		public SpecHistoryEntry(String playerName, SpecialWeapon weapon, int hit) {
			this(playerName, weapon, hit, null, null, -1);
		}

		public SpecHistoryEntry(String playerName, SpecialWeapon weapon, int hit,
				String eventId, String tickAnchor, long encounterTick) {
			this(playerName, weapon, null, hit, eventId, tickAnchor, encounterTick);
		}

		public SpecHistoryEntry(String playerName, SpecialWeapon weapon, SpellDrain spell, int hit,
				String eventId, String tickAnchor, long encounterTick) {
			this(playerName, weapon, spell, hit, eventId, tickAnchor, encounterTick, 0L);
		}

		boolean isSupported() {
			return spell == null ? isSupportedWeapon(weapon) && hit >= 0 : weapon == null && hit == 1;
		}
	}

	// Absolute state for party sync.
	@Value
	public static class SyncState {
		String bossName;
		BossDefence bossType;
		long current;
		long min;
		long base;
		long attackLevel;
		long strengthLevel;
		long magicLevel;
		long magicBaseLevel;
		long magicDef;
		long magicBaseDef;
		boolean magicUsesDefence;
		boolean demon;
		boolean accursedApplied;
		boolean drained;
		List<SpecHistoryEntry> history;
	}

	@Value
	static class AppliedSpec {
		NPC npc;
		BossDefence boss;
		SpecHistoryEntry entry;
		String previousId;
	}

	// Mutable state for one target.
	static final class EffectState {
		boolean vulnerabilityLanded;
		boolean shadowLanded;
		boolean shadowLandedOnReducedDefence;
		int kerisExpiry;
		long kerisHitAtMillis;
	}

	private static class SavedState {
		int npcIndex;
		String bossName;
		BossDefence bossType;
		int publicWorld;
		Integer privateInstance;
		int bossNpcId;
		WorldPoint targetLocation;
		// The NPC object saved with this state.
		NPC boundActor;
		boolean kephriFinalResetApplied;
		int sotetsegEncounterState;
		CombatStats stats;
		String localTickAnchor;
		int localAnchorTick;
		EffectState effects;
		List<SpecHistoryEntry> history = Collections.emptyList();
	}

	@Inject
	DefenceTracker(Client client, BetterPartyDefenceConfig config) {
		this.client = client;
		this.config = config;
		this.pendingSpecs = new PendingSpecQueue(client);
	}

	public static boolean isSupportedWeapon(SpecialWeapon weapon) {
		return SpecialWeaponRules.isSupported(weapon);
	}

	public static boolean drainsDefence(SpecialWeapon weapon) {
		return SpecialWeaponRules.drainsDefence(weapon);
	}

	public static boolean drainsMagicDefence(SpecialWeapon weapon) {
		return SpecialWeaponRules.drainsMagicDefence(weapon);
	}

	// Queue a spec for the next tick.
	// Elder Maul applies before other same-tick specs.
	public void queue(SpecialWeapon weapon, int npcIndex, int hit, int world) {
		queue(weapon, npcIndex, hit, world, null);
	}

	public void queue(SpecialWeapon weapon, int npcIndex, int hit, int world, String playerName) {
		queue(weapon, npcIndex, hit, world, playerName, null);
	}

	// Store the NPC visible when a party spec arrives.
	public void queue(
			SpecialWeapon weapon, int npcIndex, int hit, int world, String playerName, NPC target) {
		if (!isSupportedWeapon(weapon)) {
			return;
		}
		int tick = client.getTickCount();
		PendingSpecQueue.Observation observation = new PendingSpecQueue.Observation(
				weapon, null, npcIndex, hit, world, playerName, null, -1, 0L, null, -1, 0L,
				PendingSpecQueue.captureTarget(target), tick, null);
		pendingSpecs.add(observation, weapon == SpecialWeapon.ELDER_MAUL);
	}

	// Standard party messages do not carry event IDs.
	public void queueLocal(SpecialWeapon weapon, int npcIndex, int hit, int world, String playerName) {
		queueLocal(weapon, npcIndex, hit, world, playerName, null);
	}

	public void queueLocal(
			SpecialWeapon weapon, int npcIndex, int hit, int world, String playerName, NPC target) {
		queueLocal(weapon, npcIndex, hit, world, playerName, target, System.currentTimeMillis());
	}

	void queueLocal(SpecialWeapon weapon, int npcIndex, int hit, int world, String playerName,
			NPC target, long observedAtMillis) {
		if (isSupportedWeapon(weapon)) {
			int tick = client.getTickCount();
			pendingSpecs.add(new PendingSpecQueue.Observation(weapon, null, npcIndex, hit, world, playerName,
					java.util.UUID.randomUUID().toString(), tick, observedAtMillis, sharedTickAnchor,
					sharedTickAnchorTick, sharedTickAnchorValue, PendingSpecQueue.captureTarget(target), tick, null),
					false);
		}
	}

	void queueSpell(SpellDrain spell, NPC npc, int tick) {
		Player local = client.getLocalPlayer();
		pendingSpecs.add(new PendingSpecQueue.Observation(null, spell, npc.getIndex(), 1, client.getWorld(),
				local == null ? null : local.getName(), java.util.UUID.randomUUID().toString(),
				tick, System.currentTimeMillis(), sharedTickAnchor, sharedTickAnchorTick, sharedTickAnchorValue,
				PendingSpecQueue.captureTarget(npc), tick, null), false);
	}

	void setSharedTickAnchor(String anchor, int tick) {
		setSharedTickAnchor(anchor, tick, 0L);
	}

	// Align different login counters to one raid tick.
	void setSharedTickAnchor(String anchor, int tick, long value) {
		sharedTickAnchor = anchor;
		sharedTickAnchorTick = tick;
		sharedTickAnchorValue = anchor == null ? 0L : value;
	}

	// Run on the client thread.
	public void onGameTick() {
		localSpecs.clear();
		reconcileSceneBindings();
		int currentTick = client.getTickCount();
		recentStandardSpecs.values().removeIf(tick -> currentTick - tick > STANDARD_SPEC_CORRELATION_TICKS);
		for (PendingSpecQueue.Observation observation = pendingSpecs.poll();
				observation != null;
				observation = pendingSpecs.poll()) {
			process(observation);
		}

		pendingSpecs.replay(this::processResolvedDrain);

		boolean inCoxRaid = client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
		if (bossType != null && bossType.has(BossDefence.Flag.COX_SCALED)
				&& wasInCoxRaid && !inCoxRaid) {
			resetInstancedState("Chambers raid ended");
		}
		wasInCoxRaid = inCoxRaid;

		if (bossType == BossDefence.SOTETSEG) {
			updateSotetsegEncounterState();
		}

		reconcileTrackedNpc();

		// Interaction may restore remembered targets.
		followInteractingTarget();
		saveCurrent();
		pruneInactiveTargets();
	}

	// Keep saved state attached to the correct live NPC.
	private void reconcileTrackedNpc() {
		if (bossIndex == -1 && bossType != null && publicWorld == 0) {
			NPC replacement = findNpcForBoss(bossType);
			if (replacement != null) {
				rebindBoss(replacement);
			}
		}

		if (bossIndex != -1) {
			NPC npc = npcByIndex(bossIndex);
			if (npc == null) {
				if (boundActor != null && boundActor.isDead()
						&& !isPhasePersistentBoss(bossType)) {
					// If a dead NPC disappears, end the encounter.
					// Do not treat it as out of render.
					if (bossType != null) {
						endedBosses.add(bossType);
					}
					removeCurrent("bound NPC died while out of render");
					npc = null;
				} else {
					// Leaving render does not reset the encounter.
					// Try to attach the state to the same boss encounter.
					NPC replacement = findNpcForBoss(bossType);
					if (replacement != null) {
						rebindBoss(replacement);
						npc = replacement;
					}
				}
			} else if (boundActor != null && npc != boundActor
					&& !isPhaseActorTransition(npc)
					&& (boundActor.isDead() || !TargetResolver.matches(
							npc, bossType, bossNpcId, targetLocation, REMEMBERED_TARGET_DISTANCE))) {
				// Never transfer state to a different actor at a reused index.
				removeCurrent("npc index now refers to a different actor");
				npc = null;
			}

			if (npc != null) {
				observeBoundActor(npc);
				handlePhaseNpc(npc);
				if (bossIndex != -1 && (npc.isDead() || npc.getHealthRatio() == 0)) {
					BossLifecycle mechanics = BossLifecycle.forBoss(bossType);
					if (mechanics.preserveStateAtZeroHp(npc.getId())) {
						log.debug("Keeping {} state while transitional actor {} is at 0 HP", bossType, npc.getId());
					} else {
						if (bossType != null) {
							recordBossDeath(bossType, publicWorld);
						}
						removeCurrent("tracked NPC died");
					}
				}
			}
		}
	}

	// Create undrained previews only when configured.
	private void followInteractingTarget() {
		NPC target = interactingNpc();
		BossDefence targetBoss = target == null || target.getName() == null
				? null
				: BossDefence.matchingNpc(target);
		if (targetBoss == null || target.getIndex() == bossIndex) {
			return;
		}

		saveCurrent();
		if (restore(target.getIndex(), targetBoss) || restoreForBoss(targetBoss, target)) {
			return;
		}
		if (shouldRebindSameEncounter(targetBoss)) {
			rebindBoss(target);
			return;
		}
		if (config.defenceAlwaysShow()) {
			setBoss(target.getName(), target.getIndex());
		}
	}

	private NPC interactingNpc() {
		Player local = client.getLocalPlayer();
		if (local == null) {
			return null;
		}
		Actor target = local.getInteracting();
		return target instanceof NPC ? (NPC) target : null;
	}

	private void process(PendingSpecQueue.Observation drain) {
		if (drain.getWorld() != client.getWorld()) {
			log.debug("{} hit {} dropped: world {} != ours {}",
					drain.getWeapon(), drain.getHit(), drain.getWorld(), client.getWorld());
			return;
		}

		// The exact cast actor may stop being live before processing.
		// Keep the spent spec on its original encounter.
		// Only an observed kill clears it.
		PendingSpecQueue.TargetEvidence evidence = drain.getTarget();
		if (drain.getEventId() != null && evidence != null && evidence.getBossType() != null) {
			BossDefence bossType = evidence.getBossType();
			NPC cast = evidence.getActor();
			if (cast != null && cast.isDead()) {
				// A genuinely dead NPC ends the encounter.
				// Leaving render does not.
				int world = publicWorldFor(cast);
				recordBossDeath(bossType, world);
				if (world > 0) {
					clearPublicState(bossType, world, "confirmed spec on a dead actor");
				}
				return;
			}
			NPC indexed = npcByIndex(drain.getNpcIndex());
			if (cast != null && indexed != cast && publicWorldFor(cast) == drain.getWorld()) {
				// Same actor in a new scene slot.
				if (npcByIndex(cast.getIndex()) == cast) {
					processResolvedDrain(drain, cast);
					return;
				}
				// If the old slot is empty, save the state without assigning it to a new NPC.
				// Never adopt a slot already used by another actor.
				if (indexed == null) {
					applyLocalSpecToDetachedBoss(drain, cast);
					return;
				}
			}
		}

		NPC target = pendingSpecs.resolveTarget(drain);
		if (target == null) {
			log.debug("{} hit {} held: no unique local target for npc {}",
					drain.getWeapon(), drain.getHit(), drain.getNpcIndex());
			pendingSpecs.hold(drain);
			return;
		}
		processResolvedDrain(drain, target);
	}

	// Apply a spent local spec after its actor leaves scene.
	// Change only the NPC that was targeted.
	// Restore the live selection afterward.
	private void applyLocalSpecToDetachedBoss(PendingSpecQueue.Observation drain, NPC cast) {
		SavedState selected = snapshotCurrent();
		saveCurrent();
		for (SavedState saved : detachedPublicTargets) {
			if (saved.boundActor == cast) {
				loadSavedState(saved);
				break;
			}
		}
		if (boundActor != cast) {
			setBoss(cast.getName(), cast.getIndex(), cast);
		}
		bossIndex = cast.getIndex();
		apply(drain, cast);
		SavedState occupant = tracked.get(drain.getNpcIndex());
		if (occupant != null && occupant.boundActor == cast) {
			tracked.remove(drain.getNpcIndex());
		}
		bossIndex = -1;
		rememberDetachedPublicTarget(snapshotCurrent());
		if (selected != null && selected.boundActor != cast) {
			loadSavedState(selected);
		}
	}

	// A local spec includes the NPC object.
	// Legacy party specs require one unambiguous local target.
	private void processResolvedDrain(PendingSpecQueue.Observation drain, NPC npc) {
		if (npc == null || !BossDefence.isLiveNpc(npc)) {
			pendingSpecs.hold(drain);
			return;
		}

		BossDefence incomingBoss = BossDefence.matchingNpc(npc);
		if (incomingBoss == null) {
			log.debug("{} hit {} dropped: {} is not a tracked monster",
					drain.getWeapon(), drain.getHit(), npc.getName());
			return;
		}
		int index = npc.getIndex();
		if (bossIndex != index || bossType != incomingBoss) {
			saveCurrent();
			if (!restore(index, incomingBoss) && !restoreForBoss(incomingBoss, npc)) {
				if (shouldRebindSameEncounter(incomingBoss)) {
					rebindBoss(npc);
				} else {
					setBoss(npc.getName(), index);
				}
			}
		}
		handlePhaseNpc(npc);
		if (bossIndex != -1) {
			apply(drain, npc);
		}
	}

	List<AppliedSpec> localSpecs() {
		return localSpecs;
	}

	void clearStandardSpecCorrelation() {
		recentStandardSpecs.clear();
	}

	boolean hasPartySpec(NPC npc, String eventId) {
		return historyForActor(npc).stream().anyMatch(entry -> eventId.equals(entry.getEventId()));
	}

	private List<SpecHistoryEntry> historyForActor(NPC npc) {
		if (boundActor == npc) {
			return specHistory;
		}
		SavedState state = tracked.get(npc.getIndex());
		if (state != null && state.boundActor == npc) {
			return state.history;
		}
		for (SavedState detached : detachedPublicTargets) {
			if (detached.boundActor == npc) {
				return detached.history;
			}
		}
		return Collections.emptyList();
	}

	enum PartySpecResult {
		ADDED, MATCHED_STANDARD, IGNORED
	}

	PartySpecResult applyPartySpec(NPC npc, SpecHistoryEntry entry) {
		int previousCount = historyForActor(npc).size();
		int tick = client.getTickCount();
		processResolvedDrain(new PendingSpecQueue.Observation(
				entry.getWeapon(), entry.getSpell(), npc.getIndex(), entry.getHit(),
				client.getWorld(), entry.getPlayerName(), entry.getEventId(), -1, 0, null, -1, 0,
				PendingSpecQueue.captureTarget(npc), tick, entry), npc);
		if (!hasPartySpec(npc, entry.getEventId())) {
			return PartySpecResult.IGNORED;
		}
		return historyForActor(npc).size() > previousCount ? PartySpecResult.ADDED : PartySpecResult.MATCHED_STANDARD;
	}

	static int specCorrelationHit(SpecialWeapon weapon, int hit) {
		return SpecialWeaponRules.correlationHit(weapon, hit);
	}

	private boolean sameStandardSpec(SpecHistoryEntry standard, SpecHistoryEntry origin) {
		Integer receivedTick = recentStandardSpecs.get(standard);
		if (receivedTick == null || client.getTickCount() - receivedTick > STANDARD_SPEC_CORRELATION_TICKS) {
			return false;
		}
		if (origin.getWeapon() == SpecialWeapon.TONALZTICS_OF_RALOS && standard.getWeapon() == origin.getWeapon()) {
			standard = new SpecHistoryEntry(standard.getPlayerName(), standard.getWeapon(), origin.getHit());
		}
		return EncounterTimeline.samePayload(standard, origin);
	}

	private void apply(PendingSpecQueue.Observation drain, NPC npc) {
		SpecHistoryEntry partyEntry = drain.getPartyEntry();
		if (partyEntry != null) {
			int match = -1;
			for (int i = 0; i < specHistory.size(); i++) {
				SpecHistoryEntry prior = specHistory.get(i);
				if (partyEntry.getEventId().equals(prior.getEventId())) {
					return;
				}
				if (sameStandardSpec(prior, partyEntry)) {
					if (match >= 0) {
						return;
					}
					match = i;
				}
			}
			if (match >= 0) {
				List<SpecHistoryEntry> corrected = new ArrayList<>(specHistory);
				recentStandardSpecs.remove(corrected.set(match, partyEntry));
				if (shouldReplayTimeline(corrected)) {
					replayTimeline(corrected, npc);
				} else if (specHistory.get(match).getHit() != partyEntry.getHit()) {
					// Correct the Ralos hit count in place.
					loadSavedState(timelineBaseline());
					for (SpecHistoryEntry event : corrected) {
						applyHistoryEvent(event, npc);
					}
					appendSpecHistory(corrected);
				} else {
					specHistory.set(match, partyEntry);
					specHistorySnapshot = null;
				}
				return;
			}
		}

		int hit = drain.getSpell() == null ? drain.getWeapon().computeHit(drain.getHit(), npc) : drain.getHit();
		stats.drained = true;
		long before = stats.defence;
		if (drain.getSpell() == null) {
			stats.applyWeapon(drain.getWeapon(), hit, npc, bossName);
		} else {
			if (drain.getSpell() == SpellDrain.SHADOW_BARRAGE) {
				EffectState observed = effectState(npc, true);
				if (observed != null) {
					observed.shadowLanded = true;
					observed.shadowLandedOnReducedDefence = before < stats.startDefence;
				}
			}
			stats.applySpell(drain.getSpell(), bossType);
		}
		if (partyEntry == null) {
			recordSpecHistory(drain);
			SpecHistoryEntry entry = specHistory.get(specHistory.size() - 1);
			if (entry.getEventId() == null) {
				recentStandardSpecs.put(entry, drain.getReceivedTick());
			} else {
				String previousId = null;
				for (int i = specHistory.size() - 2; i >= 0 && previousId == null; i--) {
					previousId = specHistory.get(i).getEventId();
				}
				localSpecs.add(new AppliedSpec(npc, bossType, entry, previousId));
			}
		} else {
			addSpecHistory(partyEntry);
		}
		if (shouldReplayTimeline(specHistory)) {
			replayTimeline(new ArrayList<>(specHistory), npc);
		}
		log.debug("{} hit {} on {}: def {} -> {} (base {}, floor {})",
				drain.getSpell() == null ? drain.getWeapon() : drain.getSpell(),
				hit, bossName, before, stats.defence, stats.startDefence, stats.minDefence);
	}

	// Drop unresolved specs for a removed NPC.
	private void clearDeferredForTarget(int npcIndex, NPC actor) {
		pendingSpecs.clearDeferredForTarget(npcIndex, actor);
	}

	// Drop unresolved specs for a reset boss.
	private void clearDeferredForBoss(BossDefence boss) {
		pendingSpecs.clearDeferredForBoss(boss);
	}

	private void setBoss(String name, int index) {
		setBoss(name, index, npcByIndex(index));
	}

	private void setBoss(String name, int index, NPC bossNpc) {
		BossDefence boss = BossDefence.matchingNpc(bossNpc);
		clearSpecHistory();
		bossName = name;
		bossIndex = index;
		bossType = boss;
		publicWorld = publicWorldFor(bossNpc);
		privateInstance = privateInstanceFor(boss, bossNpc);
		bossNpcId = bossNpc == null ? -1 : bossNpc.getId();
		observeBoundActor(bossNpc);
		kephriFinalResetApplied = boss == BossDefence.KEPHRI && isKephriFinalPhaseId(bossNpcId);
		sotetsegEncounterState = initialSotetsegState(boss);
		initializeStats(boss);
		saveCurrent();
		log.debug("Tracking supported NPC '{}' index={} id={} baseDef={} floor={}",
				bossName, bossIndex, bossNpcId, stats.startDefence, stats.minDefence);
	}

	// Reset combat stats without changing the current NPC.
	private void initializeStats(BossDefence boss) {
		effects = null;
		localTickAnchor = null;
		stats = CombatStats.initial(
				boss,
				client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE_SCALED),
				client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1,
				client.getVarbitValue(VarbitID.RAIDS_CHALLENGE_MODE) == 1);
	}

	// A new phase can restore stats without ending the encounter.
	private void resetCurrentPhaseStats() {
		clearSpecHistory();
		clearDeferredForBoss(bossType);
		clearDeferredForTarget(bossIndex, boundActor);
		initializeStats(bossType);
	}

	// Rebind a replacement actor without losing defence.
	private void rebindBoss(NPC npc) {
		if (npc == null) {
			return;
		}
		int oldIndex = bossIndex;
		int oldId = bossNpcId;
		if (oldIndex >= 0) {
			tracked.remove(oldIndex);
		}
		if (bossType != null) {
			if (publicWorld > 0) {
				NPC previousActor = boundActor;
				detachedPublicTargets.removeIf(saved -> saved.boundActor == previousActor);
			} else {
				unboundTracked.remove(bossType);
			}
		}
		bossIndex = npc.getIndex();
		bossName = npc.getName();
		bossNpcId = npc.getId();
		observeBoundActor(npc);
		log.debug("Rebound {} encounter npc {}:{} -> {}:{} without clearing defence",
				bossType, oldIndex, oldId, bossIndex, bossNpcId);
		handlePhaseNpc(npc);
		saveCurrent();
	}

	// Kephri shield cycles keep drains.
	// Final enrage restores base defence.
	private void handlePhaseNpc(NPC npc) {
		if (npc == null || bossType == null) {
			return;
		}

		bossNpcId = npc.getId();
		observeBoundActor(npc);
		BossLifecycle mechanics = BossLifecycle.forBoss(bossType);
		if (mechanics.endsEncounterOnActorEntry(bossNpcId)) {
			resetInstancedState("boss final phase ended");
			return;
		}
		if (bossType == BossDefence.KEPHRI
				&& mechanics.resetsStatsOnActorEntry(bossNpcId) && !kephriFinalResetApplied) {
			resetCurrentPhaseStats();
			kephriFinalResetApplied = true;
			log.debug("Kephri entered final phase; Defence restored to {}", stats.defence);
		}
	}

	private int initialSotetsegState(BossDefence boss) {
		return boss == BossDefence.SOTETSEG
				? client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE)
				: -1;
	}

	// Sotetseg keeps its encounter through actor swaps.
	// Each maze restores defence; state reaches zero only at the end.
	private void updateSotetsegEncounterState() {
		int state = client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE);
		if (sotetsegEncounterState == -1) {
			sotetsegEncounterState = state;
			return;
		}

		if (state == 2 && sotetsegEncounterState != 2) {
			resetCurrentPhaseStats();
			log.debug("Sotetseg maze started; Defence restored to {} without clearing encounter", stats.defence);
		} else if (state == 0 && sotetsegEncounterState != 0) {
			resetInstancedState("Sotetseg encounter ended");
			return;
		}
		sotetsegEncounterState = state;
	}

	private boolean shouldRebindSameEncounter(BossDefence incomingBoss) {
		return bossType != null && incomingBoss != null && incomingBoss == bossType
				&& isPhasePersistentBoss(incomingBoss);
	}

	private static boolean isPhasePersistentBoss(BossDefence boss) {
		return BossLifecycle.forBoss(boss).isPhasePersistent();
	}

	// A changed phase actor ID marks a transition.
	// The same NPC ID at a reused index can still be a different actor.
	private boolean isPhaseActorTransition(NPC replacement) {
		return boundActor != null && replacement != null && bossType != null
				&& isPhasePersistentBoss(bossType)
				&& BossDefence.matchingNpc(replacement) == bossType
				&& replacement.getId() != bossNpcId;
	}

	private static boolean isKephriFinalPhaseId(int npcId) {
		return BossLifecycle.KEPHRI.resetsStatsOnActorEntry(npcId);
	}

	// Find a replaced actor for the same encounter.
	private NPC findNpcForBoss(BossDefence boss) {
		if (boss == null) {
			return null;
		}
		WorldView worldView = client.getTopLevelWorldView();
		NPC remembered = TargetResolver.uniqueLiveNpcFor(
				worldView, boss, bossNpcId, targetLocation, REMEMBERED_TARGET_DISTANCE);
		if (remembered != null) {
			return remembered;
		}
		// A different same-type NPC does not mean the original changed.
		// Bosses with several NPCs keep state with the original NPC.
		// Some phases keep one encounter while replacing the NPC.
		if (boundActor != null && !isPhasePersistentBoss(boss)) {
			return null;
		}
		return TargetResolver.uniqueLiveNpc(worldView, boss);
	}

	private void recordSpecHistory(PendingSpecQueue.Observation drain) {
		String playerName = drain.getPlayerName();
		if (playerName == null || playerName.trim().isEmpty()) {
			playerName = "Unknown";
		} else {
			playerName = Text.removeTags(playerName).trim();
		}
		if (drain.getEventId() == null) {
			addSpecHistory(new SpecHistoryEntry(playerName, drain.getWeapon(), drain.getHit()));
			return;
		}
		String tickAnchor = drain.getTickAnchor();
		int tickAnchorTick = drain.getTickAnchorTick();
		long tickAnchorValue = drain.getTickAnchorValue();
		// Boundary hits can arrive before the raid anchor is installed.
		if (tickAnchor == null && sharedTickAnchor != null
				&& drain.getObservedTick() == sharedTickAnchorTick) {
			tickAnchor = sharedTickAnchor;
			tickAnchorTick = sharedTickAnchorTick;
			tickAnchorValue = sharedTickAnchorValue;
		}
		if (tickAnchor != null) {
			long encounterTick = tickAnchorValue + (long) drain.getObservedTick() - tickAnchorTick;
			// Reject only genuinely pre-raid ticks.
			if (encounterTick >= 0) {
				addSpecHistory(new SpecHistoryEntry(playerName, drain.getWeapon(), drain.getSpell(), drain.getHit(),
						drain.getEventId(), tickAnchor, encounterTick, drain.getObservedAtMillis()));
				return;
			}
		}
		if (localTickAnchor == null || drain.getObservedTick() < localAnchorTick
				|| specHistory.stream().noneMatch(e -> localTickAnchor.equals(e.getEventId()))) {
			localTickAnchor = drain.getEventId();
			localAnchorTick = drain.getObservedTick();
		}
		addSpecHistory(new SpecHistoryEntry(playerName, drain.getWeapon(), drain.getSpell(), drain.getHit(),
				drain.getEventId(), localTickAnchor, (long) drain.getObservedTick() - localAnchorTick,
				drain.getObservedAtMillis()));
	}

	private void addSpecHistory(SpecHistoryEntry entry) {
		specHistory.add(entry);
		specHistorySnapshot = null;
	}

	private void appendSpecHistory(List<SpecHistoryEntry> entries) {
		if (!entries.isEmpty()) {
			specHistory.addAll(entries);
			specHistorySnapshot = null;
		}
	}

	private void clearSpecHistory() {
		specHistory.clear();
		specHistorySnapshot = null;
	}

	// Return history only for the exact current target.
	public List<SpecHistoryEntry> specHistoryForCurrentTarget(int npcIndex) {
		if (bossType == null || stats.defence < 0 || npcIndex < 0 || npcIndex != bossIndex) {
			return Collections.emptyList();
		}
		return specHistory();
	}

	// Immutable active history snapshot.
	public List<SpecHistoryEntry> specHistory() {
		if (specHistorySnapshot == null) {
			specHistorySnapshot = specHistory.isEmpty()
					? Collections.emptyList()
					: Collections.unmodifiableList(new ArrayList<>(specHistory));
		}
		return specHistorySnapshot;
	}

	public boolean hasDefenceSpecHistory() {
		for (SpecHistoryEntry entry : specHistory) {
			if (entry != null && (entry.getSpell() != null || drainsDefence(entry.getWeapon()))) {
				return true;
			}
		}
		return false;
	}

	public boolean hasMagicDefenceSpecHistory() {
		for (SpecHistoryEntry entry : specHistory) {
			if (entry != null && drainsMagicDefence(entry.getWeapon())) {
				return true;
			}
		}
		return false;
	}

	private void applyHistoryEvent(SpecHistoryEntry event, NPC npc) {
		stats.applyHistoryEvent(event, npc, bossType, bossName);
	}

	private NPC npcByIndex(int index) {
		WorldView worldView = client.getTopLevelWorldView();
		return worldView == null || worldView.npcs() == null ? null : worldView.npcs().byIndex(index);
	}

	private int publicWorldFor(NPC npc) {
		if (npc == null || EncounterScopes.isRaidEncounterBoss(BossDefence.matchingNpc(npc))) {
			return 0;
		}
		WorldView view = client.getTopLevelWorldView();
		WorldView actorView = npc.getWorldView();
		return view != null && !view.isInstance() && (actorView == null || actorView == view)
				? client.getWorld()
				: 0;
	}

	private Integer privateInstanceFor(BossDefence boss, NPC npc) {
		WorldView view = client.getTopLevelWorldView();
		return npc != null && view != null && view.isInstance() && !EncounterScopes.isRaidEncounterBoss(boss)
				? EncounterScopes.instanceFingerprint(view)
				: null;
	}

	private void reconcileSceneBindings() {
		int world = client.getWorld();
		WorldView view = client.getTopLevelWorldView();
		boolean inInstance = view != null && view.isInstance();
		reconcileBoundTargets(world, view, inInstance);
		pruneDetachedPublicTargets(world);
		rebindDetachedPublicTargets(view, inInstance);
	}

	private void reconcileBoundTargets(int world, WorldView view, boolean inInstance) {
		Integer instance = null;
		for (Iterator<SavedState> it = tracked.values().iterator(); it.hasNext();) {
			SavedState saved = it.next();
			if (inInstance && saved.privateInstance != null && instance == null) {
				instance = EncounterScopes.instanceFingerprint(view);
			}
			if (view != null && saved.privateInstance != null && !saved.privateInstance.equals(instance)) {
				it.remove();
				if (bossIndex == saved.npcIndex && boundActor == saved.boundActor) {
					clearActiveFields();
				}
				continue;
			}
			if (saved.publicWorld <= 0 || saved.boundActor == null) {
				continue;
			}
			NPC indexed = npcByIndex(saved.npcIndex);
			if (saved.publicWorld == world && view != null && !inInstance && indexed == saved.boundActor) {
				continue;
			}

			it.remove();
			boolean selected = bossIndex == saved.npcIndex && boundActor == saved.boundActor;
			if (saved.boundActor.isDead() || saved.publicWorld != world) {
				if (saved.publicWorld == world) {
					endedPublicBosses.add(saved.bossType);
				}
				if (selected) {
					clearActiveFields();
				}
				continue;
			}
			if (selected) {
				bossIndex = -1;
				saved = snapshotCurrent();
			}
			if (saved.stats.drained || saved.effects != null) {
				rememberDetachedPublicTarget(saved);
			} else if (selected) {
				clearActiveFields();
			}
		}
	}

	private void pruneDetachedPublicTargets(int world) {
		detachedPublicTargets.removeIf(saved -> {
			if (saved.publicWorld != world) {
				return true;
			}
			if (saved.boundActor.isDead()) {
				endedPublicBosses.add(saved.bossType);
				return true;
			}
			return false;
		});
		if (publicWorld > 0 && (publicWorld != world || bossIndex < 0 && endedPublicBosses.contains(bossType))) {
			clearActiveFields();
		}
	}

	private void rebindDetachedPublicTargets(WorldView view, boolean inInstance) {
		if (view == null || inInstance || detachedPublicTargets.isEmpty()) {
			return;
		}
		if (bossIndex < 0 && publicWorld > 0) {
			for (NPC npc : TargetResolver.liveCandidates(view, bossType)) {
				SavedState saved = detachedPublicTarget(bossType, npc);
				if (saved != null && saved.boundActor == boundActor) {
					rebindBoss(npc);
					break;
				}
			}
		} else if (bossType == null) {
			// Restore a detached public encounter.
			Set<BossDefence> bosses = new LinkedHashSet<>();
			for (SavedState saved : detachedPublicTargets) {
				bosses.add(saved.bossType);
			}
			for (BossDefence boss : bosses) {
				for (NPC npc : TargetResolver.liveCandidates(view, boss)) {
					SavedState saved = detachedPublicTarget(boss, npc);
					if (saved != null) {
						loadSavedState(saved);
						rebindBoss(npc);
						return;
					}
				}
			}
		}
	}

	private void rememberDetachedPublicTarget(SavedState saved) {
		saved.npcIndex = -1;
		detachedPublicTargets.removeIf(old -> old.boundActor == saved.boundActor);
		detachedPublicTargets.add(saved);
	}

	private SavedState detachedPublicTarget(BossDefence boss, NPC npc) {
		int world = publicWorldFor(npc);
		if (world <= 0 || !BossDefence.isLiveNpc(npc) || endedPublicBosses.contains(boss)) {
			return null;
		}
		SavedState candidate = null;
		boolean ambiguous = false;
		for (SavedState saved : detachedPublicTargets) {
			if (saved.bossType != boss || saved.publicWorld != world || saved.boundActor.isDead()) {
				continue;
			}
			if (saved.boundActor == npc) {
				return saved;
			}
			if (candidate != null) {
				ambiguous = true;
			}
			candidate = saved;
		}
		WorldPoint tile = npc.getWorldLocation();
		if (ambiguous || candidate == null || TargetResolver.uniqueLiveNpc(client.getTopLevelWorldView(), boss) != npc
				|| candidate.targetLocation != null && tile != null
						&& candidate.targetLocation.getPlane() != tile.getPlane()) {
			return null;
		}
		for (SavedState saved : tracked.values()) {
			if (saved.bossType == boss && saved.publicWorld == world && saved.boundActor != npc) {
				return null;
			}
		}
		return candidate;
	}

	private void observeBoundActor(NPC npc) {
		boundActor = npc;
		targetLocation = npc == null ? null : npc.getWorldLocation();
	}

	private DefenceState toDefenceState(SavedState saved) {
		if (saved == null || saved.bossType == null || saved.stats == null || saved.stats.defence < 0) {
			return null;
		}
		return toDefenceState(saved.npcIndex, saved.bossName, saved.bossType, saved.stats);
	}

	private DefenceState toDefenceState(int npcIndex, String name, BossDefence boss, CombatStats stats) {
		long roll = DefenceMath.magicRoll(
				stats.magicUsesDefence ? stats.defence : stats.magicLevel, stats.magicDefenceBonus);
		long baseRoll = DefenceMath.magicRoll(
				stats.magicUsesDefence ? stats.startDefence : stats.startMagicLevel,
				stats.startMagicDefenceBonus);
		return new DefenceState(npcIndex, Text.removeTags(name), stats.defence, stats.minDefence,
				stats.startDefence, roll, baseRoll, stats.magicDefenceBonus, stats.startMagicDefenceBonus,
				stats.magicLevel, stats.startMagicLevel, stats.drained, boss.has(BossDefence.Flag.TFA));
	}

	private SyncState toSyncState(SavedState saved) {
		if (saved == null || saved.bossType == null || saved.stats == null || saved.stats.defence < 0) {
			return null;
		}
		return new SyncState(
				Text.removeTags(saved.bossName),
				saved.bossType,
				saved.stats.defence,
				saved.stats.minDefence,
				saved.stats.startDefence,
				saved.stats.attackLevel,
				saved.stats.strengthLevel,
				saved.stats.magicLevel,
				saved.stats.startMagicLevel,
				saved.stats.magicDefenceBonus,
				saved.stats.startMagicDefenceBonus,
				saved.stats.magicUsesDefence,
				saved.stats.demon,
				saved.stats.accursedApplied,
				saved.stats.drained,
				Collections.unmodifiableList(new ArrayList<>(saved.history)));
	}

	// Current or most recently selected target.
	public DefenceState state() {
		if (bossType == null || stats.defence < 0) {
			return null;
		}
		return toDefenceState(bossIndex, bossName, bossType, stats);
	}

	// Every concrete target retained in memory.
	public List<DefenceState> states() {
		// Use live stats for the selected target.
		DefenceState current = bossIndex >= 0 ? state() : null;
		List<DefenceState> out = new ArrayList<>();
		for (SavedState saved : tracked.values()) {
			DefenceState state = current != null && saved.npcIndex == bossIndex
					? current
					: toDefenceState(saved);
			if (state != null) {
				out.add(state);
			}
		}
		if (current != null && !tracked.containsKey(bossIndex)) {
			out.add(current);
		}
		return out;
	}

	// Snapshot the active target for party sync.
	public SyncState syncState() {
		return toSyncState(snapshotCurrent());
	}

	// Share history only while its NPC is still attached.
	SyncState syncStateForActor(NPC npc) {
		if (npc == boundActor) {
			return syncState();
		}
		SavedState saved = tracked.get(npc.getIndex());
		return saved != null && saved.boundActor == npc ? toSyncState(saved) : null;
	}

	// Rebuild a target from specs that survived a reset.
	void replaySpecsAfterReset(NPC npc, List<SpecHistoryEntry> surviving) {
		SavedState selected = snapshotCurrent();
		SavedState target = npc == boundActor ? selected : tracked.get(npc.getIndex());
		loadSavedState(target);
		replayTimeline(surviving, npc);
		saveCurrent();
		if (selected != null && selected.npcIndex != npc.getIndex()) {
			loadSavedState(selected);
		}
	}

	// Remembered state for one boss type.
	public SyncState syncStateForBoss(BossDefence boss) {
		if (boss == null) {
			return null;
		}
		saveCurrent();
		WorldView view = client.getTopLevelWorldView();
		boolean inPublicWorld = view != null && !view.isInstance();
		if (bossType == boss && (privateInstance == null || !inPublicWorld)
				&& (publicWorld == 0 || inPublicWorld && publicWorld == client.getWorld()
						&& (boundActor == null || !boundActor.isDead()))) {
			return toSyncState(snapshotCurrent());
		}
		SavedState unbound = unboundTracked.get(boss);
		if (unbound != null) {
			return toSyncState(unbound);
		}
		SavedState best = null;
		for (SavedState saved : tracked.values()) {
			if (saved.bossType == boss && (saved.privateInstance == null || !inPublicWorld)
					&& (saved.publicWorld == 0
							|| inPublicWorld && saved.publicWorld == client.getWorld())
					&& (saved.publicWorld == 0 || saved.boundActor == null || !saved.boundActor.isDead())
					&& (best == null || saved.history.size() > best.history.size())) {
				best = saved;
			}
		}
		return toSyncState(best);
	}

	// Use world location to match a saved open-world NPC.
	SyncState publicSyncStateForBoss(BossDefence boss, int world, WorldPoint point, int tolerance) {
		if (world <= 0 || point == null || endedPublicBosses.contains(boss)) {
			return null;
		}
		saveCurrent();
		SavedState candidate = null;
		List<SavedState> candidates = new ArrayList<>(tracked.values());
		candidates.addAll(detachedPublicTargets);
		for (SavedState saved : candidates) {
			if (saved.publicWorld != world || saved.bossType != boss || !saved.stats.drained
					|| !BossDefence.isLiveNpc(saved.boundActor)) {
				continue;
			}
			if (candidate != null) {
				return null;
			}
			candidate = saved;
		}
		return candidate != null && candidate.targetLocation != null
				&& candidate.targetLocation.distanceTo(point) <= tolerance ? toSyncState(candidate) : null;
	}

	boolean hasPublicState(BossDefence boss, int world) {
		return tracked.values().stream().anyMatch(saved -> saved.bossType == boss && saved.publicWorld == world)
				|| detachedPublicTargets.stream()
						.anyMatch(saved -> saved.bossType == boss && saved.publicWorld == world);
	}

	void clearPublicState(BossDefence boss, int world, String reason) {
		// Clear only hits attached to removed public actors.
		List<SavedState> candidates = new ArrayList<>(tracked.values());
		candidates.addAll(detachedPublicTargets);
		for (SavedState saved : candidates) {
			if (saved.bossType == boss && saved.publicWorld == world) {
				clearDeferredForTarget(-1, saved.boundActor);
			}
		}
		detachedPublicTargets.removeIf(saved -> saved.bossType == boss && saved.publicWorld == world);
		tracked.values().removeIf(saved -> saved.bossType == boss && saved.publicWorld == world);
		if (bossType == boss && publicWorld == world) {
			clearActiveFields();
		}
		log.debug("Cleared public {} state in world {}: {}", boss, world, reason);
	}

	boolean hasUnprocessedSpecs() {
		return !pendingSpecs.isEmpty();
	}

	// Ignore pending specs for a known different boss.
	boolean hasUnprocessedSpecsForBoss(BossDefence boss) {
		return pendingSpecs.hasForBoss(boss);
	}

	boolean hasPendingFor(int npcIndex) {
		return pendingSpecs.hasForTarget(npcIndex);
	}

	// Merge specs with event IDs before comparing versions.
	public boolean mergeEventSyncState(SyncState incoming, NPC npc) {
		return mergeEventSyncState(incoming, npc, false);
	}

	boolean mergeEventSyncState(SyncState incoming, NPC npc, boolean matchedPublicEncounter) {
		if (incoming == null || npc == null || !BossDefence.isLiveNpc(npc)
				|| BossDefence.matchingNpc(npc) != incoming.getBossType()) {
			return false;
		}
		saveCurrent();
		SavedState target = tracked.get(npc.getIndex());
		if (target == null || target.bossType != incoming.getBossType()
				|| target.stats.startDefence != incoming.getBase()
				|| target.stats.minDefence != incoming.getMin()
				|| target.stats.startMagicLevel != incoming.getMagicBaseLevel()
				|| target.stats.startMagicDefenceBonus != incoming.getMagicBaseDef()
				|| target.stats.magicUsesDefence != incoming.isMagicUsesDefence()
				|| target.stats.demon != incoming.isDemon()) {
			return false;
		}
		List<SpecHistoryEntry> merged = EncounterTimeline.union(target.history, incoming.getHistory());
		if (merged == null || new java.util.HashSet<>(merged).equals(new java.util.HashSet<>(target.history))) {
			return false;
		}
		// A unique visible target can identify the encounter.
		boolean shared = target.history.stream().anyMatch(a -> incoming.getHistory().stream()
				.anyMatch(b -> EncounterTimeline.compatibleEvent(a, b)
						|| (a.getEventId() == null || b.getEventId() == null)
								&& EncounterTimeline.samePayload(a, b)));
		if (!shared && !(target.boundActor == npc && target.publicWorld == client.getWorld()
				&& (matchedPublicEncounter && merged.stream().allMatch(entry -> entry.getObservedAtMillis() > 0)
						&& TargetResolver.uniqueLiveNpc(client.getTopLevelWorldView(), target.bossType) == npc
						|| onlyNoOpEvents(target.history, npc) || onlyNoOpEvents(incoming.getHistory(), npc)))) {
			return false;
		}
		if (hasPendingFor(npc.getIndex())) {
			return false;
		}
		SavedState selected = snapshotCurrent();
		loadSavedState(target);
		replayTimeline(merged, npc);
		saveCurrent();
		if (selected != null && selected.npcIndex != npc.getIndex()) {
			loadSavedState(selected);
		}
		return true;
	}

	// True when no row can change defence.
	// Tekton hammer and maul misses can still drain.
	// Spells and undated rows are excluded.
	static boolean onlyNoOpEvents(List<SpecHistoryEntry> history, NPC npc) {
		return !history.isEmpty() && history.stream()
				.allMatch(entry -> entry.getSpell() == null && entry.getWeapon() != null && entry.getHit() == 0
						&& entry.getObservedAtMillis() > 0
						&& entry.getWeapon().computeDrainPercent(0, npc) <= 0);
	}

	// Skip equivalent orders that unlock the same events.
	// Hits stay distinct when the formula uses their value.
	String effectKey(SpecHistoryEntry event, NPC npc) {
		return CombatStats.effectKey(event, npc);
	}

	private boolean shouldReplayTimeline(List<SpecHistoryEntry> events) {
		return EncounterTimeline.complete(events) || events.size() > EncounterTimeline.MAX_EVENTS
				&& events.stream().allMatch(e -> e.getEventId() != null);
	}

	private SavedState timelineBaseline() {
		SavedState baseline = snapshotCurrent();
		baseline.stats = baseline.stats.undrainedBaseline(bossType);
		baseline.history = Collections.emptyList();
		return baseline;
	}

	// Replay from the actual scaled baseline.
	private void replayTimeline(List<SpecHistoryEntry> events, NPC npc) {
		events.sort(EncounterTimeline.DISPLAY_ORDER);
		SavedState baseline = timelineBaseline();
		SavedState result = EncounterTimeline.replay(events, baseline, new EncounterTimeline.Replay<SavedState>() {
			@Override
			public SavedState apply(SavedState state, SpecHistoryEntry event) {
				loadSavedState(state);
				applyHistoryEvent(event, npc);
				return snapshotCurrent();
			}

			@Override
			public SavedState conservative(SavedState a, SavedState b) {
				// Keep the highest legal value for each stat.
				// Later rebuilds still try every event order.
				a.stats.keepConservativeMaximum(b.stats);
				return a;
			}
		}, event -> effectKey(event, npc));
		loadSavedState(result);
		appendSpecHistory(events);
		stats.drained = true;
	}

	// Check that the current target has a live NPC.
	public boolean hasBoundNpc(BossDefence boss) {
		if (boss == null) {
			return false;
		}
		if (bossType == boss && hasBoundNpc()) {
			return true;
		}
		for (SavedState saved : tracked.values()) {
			if (saved != null && saved.bossType == boss) {
				NPC npc = npcByIndex(saved.npcIndex);
				if (BossDefence.isLiveNpc(npc) && (saved.boundActor == null || saved.boundActor == npc)) {
					return true;
				}
			}
		}
		return false;
	}

	// Cache remote state without changing the selected target.
	// Attach it when the NPC appears.
	public void cacheSyncState(SyncState sync) {
		if (sync == null || sync.getBossType() == null || !sync.isDrained()) {
			return;
		}

		SavedState saved = new SavedState();
		saved.npcIndex = -1;
		saved.bossName = sync.getBossName() == null ? sync.getBossType().getNpcName() : sync.getBossName();
		saved.bossType = sync.getBossType();
		saved.bossNpcId = -1;
		saved.kephriFinalResetApplied = false;
		saved.sotetsegEncounterState = initialSotetsegState(sync.getBossType());
		saved.stats = CombatStats.fromSync(sync);
		if (sync.getHistory() != null) {
			saved.history = Collections.unmodifiableList(new ArrayList<>(sync.getHistory()));
		}

		unboundTracked.put(saved.bossType, saved);
		log.debug("Cached passive BPD sync for {} def={}/{} specs={}",
				saved.bossType, saved.stats.defence, saved.stats.startDefence, saved.history.size());
	}

	// Apply snapshot state to one target.
	// Save the current target first.
	// A null NPC stores state until the boss appears.
	public void applySyncState(SyncState sync, NPC localNpc) {
		if (sync == null || sync.getBossType() == null || !sync.isDrained()) {
			return;
		}

		saveCurrent();
		SavedState previousTarget = localNpc == null ? null : tracked.get(localNpc.getIndex());
		SavedState effectTarget = localNpc == null && bossIndex < 0 && bossType == sync.getBossType()
				? unboundTracked.get(bossType)
				: previousTarget;
		effects = effectTarget != null && effectTarget.bossType == sync.getBossType()
				&& effectTarget.boundActor == localNpc ? effectTarget.effects : null;
		localTickAnchor = previousTarget == null ? null : previousTarget.localTickAnchor;
		localAnchorTick = previousTarget == null ? 0 : previousTarget.localAnchorTick;
		bossType = sync.getBossType();
		publicWorld = publicWorldFor(localNpc);
		privateInstance = privateInstanceFor(bossType, localNpc);
		bossName = sync.getBossName() == null ? bossType.getNpcName() : sync.getBossName();
		bossIndex = localNpc == null ? -1 : localNpc.getIndex();
		bossNpcId = localNpc == null ? -1 : localNpc.getId();
		observeBoundActor(localNpc);
		stats = CombatStats.fromSync(sync);
		kephriFinalResetApplied = bossType == BossDefence.KEPHRI && isKephriFinalPhaseId(bossNpcId);
		sotetsegEncounterState = initialSotetsegState(bossType);
		wasInCoxRaid = client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;

		clearSpecHistory();
		if (sync.getHistory() != null) {
			appendSpecHistory(sync.getHistory());
		}
		if (localNpc != null) {
			unboundTracked.remove(bossType);
		}
		saveCurrent();
		// Keep independent observations on other targets.
		log.debug("Applied BPD sync for {} actor={} def={}/{} specs={}",
				bossType, bossIndex, stats.defence, stats.startDefence, specHistory.size());
	}

	public BossDefence trackedBossType() {
		return bossType;
	}

	public boolean hasBoundNpc() {
		NPC npc = bossIndex < 0 ? null : npcByIndex(bossIndex);
		return BossDefence.isLiveNpc(npc) && (boundActor == null || boundActor == npc);
	}

	private SavedState snapshotCurrent() {
		if (bossType == null || stats.defence < 0) {
			return null;
		}
		SavedState s = new SavedState();
		s.npcIndex = bossIndex;
		s.bossName = bossName;
		s.bossType = bossType;
		s.publicWorld = publicWorld;
		s.privateInstance = privateInstance;
		s.bossNpcId = bossNpcId;
		s.targetLocation = targetLocation;
		s.boundActor = boundActor;
		s.kephriFinalResetApplied = kephriFinalResetApplied;
		s.sotetsegEncounterState = sotetsegEncounterState;
		s.stats = stats.copy();
		s.localTickAnchor = localTickAnchor;
		s.localAnchorTick = localAnchorTick;
		s.effects = effects;
		s.history = specHistory();
		return s;
	}

	private void saveCurrent() {
		SavedState s = snapshotCurrent();
		if (s == null) {
			return;
		}
		if (s.npcIndex >= 0) {
			tracked.put(s.npcIndex, s);
			unboundTracked.remove(s.bossType);
		} else if (s.publicWorld > 0) {
			// Keep saved open-world state until attached to an NPC.
			return;
		} else {
			unboundTracked.put(s.bossType, s);
		}
	}

	private boolean restore(int index, BossDefence expectedBoss) {
		SavedState s = tracked.get(index);
		if (s == null || (expectedBoss != null && s.bossType != expectedBoss)) {
			return false;
		}
		NPC current = npcByIndex(index);
		if (s.boundActor != null) {
			if (s.boundActor.isDead()) {
				return false;
			}
			if (current != null && current != s.boundActor
					&& !TargetResolver.matches(
							current, expectedBoss, s.bossNpcId, s.targetLocation, REMEMBERED_TARGET_DISTANCE)) {
				return false;
			}
		}
		loadSavedState(s);
		if (current != null) {
			observeBoundActor(current);
		}
		return true;
	}

	// Attach saved state when the NPC appears.
	private boolean restoreForBoss(BossDefence boss, NPC npc) {
		if (boss == null || npc == null) {
			return false;
		}

		SavedState detached = detachedPublicTarget(boss, npc);
		if (detached != null) {
			loadSavedState(detached);
			rebindBoss(npc);
			return true;
		}

		SavedState unbound = unboundTracked.remove(boss);
		if (unbound != null) {
			loadSavedState(unbound);
			bossIndex = npc.getIndex();
			bossNpcId = npc.getId();
			bossName = npc.getName();
			publicWorld = publicWorldFor(npc);
			privateInstance = privateInstanceFor(boss, npc);
			observeBoundActor(npc);
			saveCurrent();
			return true;
		}

		// Move state only when exactly one matching boss is missing.
		Integer oldKey = null;
		SavedState candidate = null;
		for (Map.Entry<Integer, SavedState> entry : tracked.entrySet()) {
			SavedState saved = entry.getValue();
			NPC oldActor = npcByIndex(saved.npcIndex);
			boolean terminalDeath = saved.boundActor != null && saved.boundActor.isDead()
					&& !isPhasePersistentBoss(saved.bossType);
			boolean oldActorGone = oldActor == null
					|| oldActor == saved.boundActor && !BossDefence.isLiveNpc(oldActor);
			boolean rememberedActorMatch = TargetResolver.matches(
					npc, saved.bossType, saved.bossNpcId, saved.targetLocation, REMEMBERED_TARGET_DISTANCE);
			boolean phaseActorTransition = isPhasePersistentBoss(saved.bossType)
					&& npc.getId() != saved.bossNpcId;
			if (saved.bossType == boss && oldActorGone && !terminalDeath
					&& (rememberedActorMatch || phaseActorTransition)) {
				if (candidate != null) {
					return false;
				}
				candidate = saved;
				oldKey = entry.getKey();
			}
		}
		if (candidate == null) {
			return false;
		}
		tracked.remove(oldKey);
		loadSavedState(candidate);
		bossIndex = npc.getIndex();
		bossNpcId = npc.getId();
		bossName = npc.getName();
		observeBoundActor(npc);
		saveCurrent();
		return true;
	}

	private void loadSavedState(SavedState s) {
		bossIndex = s.npcIndex;
		bossName = s.bossName;
		bossType = s.bossType;
		publicWorld = s.publicWorld;
		privateInstance = s.privateInstance;
		bossNpcId = s.bossNpcId;
		targetLocation = s.targetLocation;
		boundActor = s.boundActor;
		kephriFinalResetApplied = s.kephriFinalResetApplied;
		sotetsegEncounterState = s.sotetsegEncounterState;
		stats = s.stats.copy();
		localTickAnchor = s.localTickAnchor;
		localAnchorTick = s.localAnchorTick;
		effects = s.effects;
		if (specHistorySnapshot != s.history) {
			specHistory.clear();
			specHistory.addAll(s.history);
			specHistorySnapshot = s.history;
		}
	}

	private void pruneInactiveTargets() {
		Iterator<Map.Entry<Integer, SavedState>> it = tracked.entrySet().iterator();
		while (it.hasNext()) {
			Map.Entry<Integer, SavedState> entry = it.next();
			if (entry.getKey() == bossIndex) {
				continue;
			}
			NPC npc = npcByIndex(entry.getKey());
			SavedState saved = entry.getValue();
			if (npc != null && saved != null && saved.boundActor != null && npc != saved.boundActor
					&& (saved.boundActor.isDead() || !TargetResolver.matches(
							npc, saved.bossType, saved.bossNpcId, saved.targetLocation, REMEMBERED_TARGET_DISTANCE))) {
				clearDeferredForTarget(entry.getKey(), saved.boundActor);
				it.remove();
				continue;
			}
			if (npc != null && (npc.isDead() || npc.getHealthRatio() == 0)) {
				SavedState ended = saved;
				BossLifecycle mechanics = BossLifecycle.forBoss(
						ended == null ? null : ended.bossType);
				if (mechanics.preserveStateAtZeroHp(npc.getId())) {
					continue;
				}
				if (ended != null && ended.bossType != null) {
					recordBossDeath(ended.bossType, ended.publicWorld);
				}
				clearDeferredForTarget(entry.getKey(), saved == null ? null : saved.boundActor);
				it.remove();
			}
		}
	}

	// Return boss types seen ending and clear the set.
	// The plugin decides which resets should be sent to peers.
	public Set<BossDefence> consumeEndedBosses() {
		Set<BossDefence> ended = new LinkedHashSet<>(endedBosses);
		endedBosses.clear();
		return ended;
	}

	private void recordBossDeath(BossDefence boss, int world) {
		(world > 0 ? endedPublicBosses : endedBosses).add(boss);
	}

	Set<BossDefence> consumeEndedPublicBosses() {
		Set<BossDefence> ended = new LinkedHashSet<>(endedPublicBosses);
		endedPublicBosses.clear();
		return ended;
	}

	private void clearActiveFields() {
		effects = null;
		localTickAnchor = null;
		bossIndex = -1;
		bossName = "";
		bossType = null;
		publicWorld = 0;
		privateInstance = null;
		bossNpcId = -1;
		targetLocation = null;
		boundActor = null;
		kephriFinalResetApplied = false;
		sotetsegEncounterState = -1;
		stats = new CombatStats();
		clearSpecHistory();
	}

	private void removeCurrent(String reason) {
		BossDefence removedBoss = bossType;
		int removedIndex = bossIndex;
		NPC removedActor = boundActor;
		if (removedIndex >= 0) {
			tracked.remove(removedIndex);
		}
		if (removedBoss != null) {
			unboundTracked.remove(removedBoss);
		}
		clearDeferredForTarget(removedIndex, removedActor);
		log.debug("Remove tracked target {}:{}: {}", removedBoss, removedIndex, reason);
		clearActiveFields();

		List<SavedState> remaining = new ArrayList<>(tracked.values());
		for (int i = remaining.size() - 1; i >= 0; i--) {
			SavedState saved = remaining.get(i);
			NPC npc = npcByIndex(saved.npcIndex);
			if (BossDefence.isLiveNpc(npc)) {
				loadSavedState(saved);
				return;
			}
		}
	}

	void resetInstancedState(String reason) {
		List<SavedState> publicTargets = new ArrayList<>();
		for (SavedState saved : tracked.values()) {
			if (saved.publicWorld > 0) {
				publicTargets.add(saved);
			}
		}
		publicTargets.addAll(detachedPublicTargets);
		Set<BossDefence> publicDeaths = new LinkedHashSet<>(endedPublicBosses);
		reset(reason);
		publicTargets.forEach(this::rememberDetachedPublicTarget);
		endedPublicBosses.addAll(publicDeaths);
	}

	// Use the target's saved effect state.
	EffectState effectState(NPC npc, boolean remember) {
		if (!BossDefence.isLiveNpc(npc) || npcByIndex(npc.getIndex()) != npc) {
			return null;
		}
		BossDefence boss = BossDefence.matchingNpc(npc);
		if (boss == null) {
			return null;
		}
		if (boundActor == npc && bossType == boss) {
			if (remember && effects == null) {
				effects = new EffectState();
				saveCurrent();
			}
			return effects;
		}
		SavedState saved = tracked.get(npc.getIndex());
		if (saved != null && saved.boundActor == npc && saved.bossType == boss) {
			if (remember && saved.effects == null) {
				saved.effects = new EffectState();
			}
			return saved.effects;
		}
		if (!remember) {
			return null;
		}

		SavedState selected = snapshotCurrent();
		saveCurrent();
		if (!restore(npc.getIndex(), boss) && !restoreForBoss(boss, npc)) {
			setBoss(npc.getName(), npc.getIndex());
		}
		if (effects == null) {
			effects = new EffectState();
		}
		EffectState result = effects;
		saveCurrent();
		if (selected == null) {
			clearActiveFields();
		} else if (selected.npcIndex != bossIndex || selected.bossType != bossType) {
			loadSavedState(selected);
		}
		return result;
	}

	boolean hasLandedSpell(NPC npc, SpellDrain spell) {
		if (!BossDefence.isLiveNpc(npc) || npcByIndex(npc.getIndex()) != npc) {
			return false;
		}
		SavedState saved = tracked.get(npc.getIndex());
		List<SpecHistoryEntry> history = boundActor == npc
				? specHistory
				: saved != null && saved.boundActor == npc ? saved.history : Collections.emptyList();
		return history.stream().anyMatch(entry -> entry.getSpell() == spell);
	}

	Set<BossDefence> encounterLifecycleBosses() {
		return rememberedBosses(true);
	}

	// Bosses with remembered drained state.
	public Set<BossDefence> drainedBosses() {
		return rememberedBosses(false);
	}

	private Set<BossDefence> rememberedBosses(boolean includeEffects) {
		saveCurrent();
		Set<BossDefence> bosses = new LinkedHashSet<>();
		for (SavedState saved : tracked.values()) {
			if (saved != null && saved.bossType != null
					&& (saved.stats.drained || includeEffects && saved.effects != null)) {
				bosses.add(saved.bossType);
			}
		}
		for (SavedState saved : unboundTracked.values()) {
			if (saved != null && saved.bossType != null
					&& (saved.stats.drained || includeEffects && saved.effects != null)) {
				bosses.add(saved.bossType);
			}
		}
		for (SavedState saved : detachedPublicTargets) {
			if (saved.stats.drained || includeEffects && saved.effects != null) {
				bosses.add(saved.bossType);
			}
		}
		return bosses;
	}

	public boolean hasRememberedState(BossDefence boss) {
		if (boss == null) {
			return false;
		}
		if (bossType == boss && stats.defence >= 0) {
			return true;
		}
		if (unboundTracked.containsKey(boss)) {
			return true;
		}
		if (detachedPublicTargets.stream().anyMatch(saved -> saved.bossType == boss)) {
			return true;
		}
		for (SavedState saved : tracked.values()) {
			if (saved != null && saved.bossType == boss) {
				return true;
			}
		}
		return false;
	}

	// Remove one boss and retain other targets.
	public void clearBossState(BossDefence boss, String reason) {
		clearBossState(boss, reason, true);
	}

	void clearInstancedBossState(BossDefence boss, String reason) {
		clearBossState(boss, reason, false);
	}

	private void clearBossState(BossDefence boss, String reason, boolean includePublic) {
		if (boss == null) {
			return;
		}

		boolean clearingActive = bossType == boss && (includePublic || publicWorld == 0);
		Set<Integer> clearedIndices = new LinkedHashSet<>();
		Set<NPC> clearedActors = new LinkedHashSet<>();
		if (clearingActive) {
			if (bossIndex >= 0) {
				clearedIndices.add(bossIndex);
			}
			if (boundActor != null) {
				clearedActors.add(boundActor);
			}
		}
		tracked.entrySet().removeIf(entry -> {
			SavedState saved = entry.getValue();
			if (saved == null || saved.bossType != boss || !includePublic && saved.publicWorld > 0) {
				return false;
			}
			clearedIndices.add(entry.getKey());
			if (saved.boundActor != null) {
				clearedActors.add(saved.boundActor);
			}
			return true;
		});
		unboundTracked.remove(boss);
		if (includePublic) {
			detachedPublicTargets.removeIf(saved -> saved.bossType == boss);
		}
		clearDeferredForBoss(boss);
		for (Integer index : clearedIndices) {
			clearDeferredForTarget(index, null);
		}
		for (NPC actor : clearedActors) {
			clearDeferredForTarget(-1, actor);
		}

		if (!clearingActive) {
			return;
		}

		log.debug("Clear tracked boss {}: {}", boss, reason);
		clearActiveFields();

		List<SavedState> remaining = new ArrayList<>(tracked.values());
		for (int i = remaining.size() - 1; i >= 0; i--) {
			SavedState saved = remaining.get(i);
			NPC npc = npcByIndex(saved.npcIndex);
			if (BossDefence.isLiveNpc(npc)) {
				loadSavedState(saved);
				return;
			}
		}

		SavedState fallback = null;
		for (SavedState saved : unboundTracked.values()) {
			fallback = saved;
		}
		if (fallback != null) {
			loadSavedState(fallback);
		}
	}

	public void reset(String reason) {
		recentStandardSpecs.clear();
		localSpecs.clear();
		if (bossType != null || bossIndex != -1 || !tracked.isEmpty() || !unboundTracked.isEmpty()
				|| !detachedPublicTargets.isEmpty() || !pendingSpecs.isEmpty()) {
			log.debug("Reset defence tracker: {}", reason);
		}
		clearActiveFields();
		tracked.clear();
		unboundTracked.clear();
		detachedPublicTargets.clear();
		endedBosses.clear();
		endedPublicBosses.clear();
		pendingSpecs.clear();
	}

}

package net.betterpartydefence;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.party.PartyService;

// Resolves the transport scope for the current world or raid encounter.
final class EncounterScopeResolver {
	private final Client client;
	private final PartyService partyService;

	EncounterScopeResolver(Client client, PartyService partyService) {
		this.client = client;
		this.partyService = partyService;
	}

	SyncScope current() {
		int coxController = raidController(BpdDefenceSync.SCOPE_COX);
		if (coxController > 0) {
			return new SyncScope(BpdDefenceSync.SCOPE_COX, coxController);
		}

		int tobController = raidController(BpdDefenceSync.SCOPE_TOB);
		if (tobController > 0) {
			return new SyncScope(BpdDefenceSync.SCOPE_TOB, tobController);
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null) {
			return null;
		}
		if (worldView.isInstance()) {
			return instanceScope(worldView);
		}
		return new SyncScope(BpdDefenceSync.SCOPE_WORLD, 0);
	}

	SyncScope forBoss(BossDefence boss, NPC npc) {
		int raidScope = EncounterScopes.raidScopeType(boss);
		if (raidScope != -1) {
			int controller = raidController(raidScope);
			if (controller > 0) {
				return new SyncScope(raidScope, controller);
			}

			// CoX can clear its public controller after starting.
			// Use the live instance only to match party packets.
			WorldView raidWorldView = client.getTopLevelWorldView();
			if (raidWorldView != null && raidWorldView.isInstance()) {
				return instanceScope(raidWorldView);
			}
			return null;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null) {
			return null;
		}
		if (worldView.isInstance()) {
			return instanceScope(worldView);
		}
		return npc == null ? null : new SyncScope(BpdDefenceSync.SCOPE_WORLD, 0);
	}

	SyncScope currentRaidScopeForBoss(BossDefence boss) {
		int raidScope = EncounterScopes.raidScopeType(boss);
		if (raidScope != -1) {
			int controller = raidController(raidScope);
			return controller > 0 ? new SyncScope(raidScope, controller) : null;
		}

		if (!EncounterScopes.isToaBoss(boss) && !EncounterScopes.isTfaBoss(boss)) {
			return null;
		}

		WorldView worldView = client.getTopLevelWorldView();
		return worldView != null && worldView.isInstance()
				? instanceScope(worldView)
				: null;
	}

	String raidBegunScopeKey() {
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView != null && worldView.isInstance()) {
			return BpdDefenceSync.SCOPE_INSTANCE + ":" + EncounterScopes.instanceFingerprint(worldView);
		}
		SyncScope scope = current();
		return scope == null ? null : scope.getType() + ":" + scope.getId();
	}

	boolean incomingScopeMatches(BpdDefenceSync event, BossDefence boss, NPC localBoss) {
		if (!scopeMatches(event.getScopeType(), event.getScopeId(), boss)) {
			return false;
		}
		if (event.getScopeType() != BpdDefenceSync.SCOPE_WORLD) {
			return true;
		}
		if (localBoss == null) {
			return false;
		}

		// Open-world HP may be unavailable before combat.
		WorldPoint point = localBoss.getWorldLocation();
		WorldPoint remotePoint = event.getBossLocation();
		if (point == null || remotePoint == null
				|| point.distanceTo(remotePoint) > EncounterScopes.POSITION_TOLERANCE) {
			return false;
		}
		return healthMatches(localBoss, event.getHealthPercent());
	}

	boolean scopeMatches(int scopeType, int scopeId, BossDefence boss) {
		int expectedRaidScope = EncounterScopes.raidScopeType(boss);
		if (expectedRaidScope != -1) {
			// A peer can still use the instance id after the controller disappears.
			if (scopeType == BpdDefenceSync.SCOPE_INSTANCE) {
				WorldView raidWorldView = client.getTopLevelWorldView();
				return matchesInstance(raidWorldView, scopeId);
			}
			int controller = raidController(expectedRaidScope);
			return controller > 0 && scopeType == expectedRaidScope && scopeId == controller;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null) {
			return false;
		}
		if (scopeType == BpdDefenceSync.SCOPE_INSTANCE) {
			return matchesInstance(worldView, scopeId);
		}
		return scopeType == BpdDefenceSync.SCOPE_WORLD && !worldView.isInstance();
	}

	boolean syncScopeStillValid(int scopeType, int scopeId) {
		if (client.getGameState() != GameState.LOGGED_IN || !partyService.isInParty()) {
			return false;
		}
		switch (scopeType) {
			case BpdDefenceSync.SCOPE_COX:
			case BpdDefenceSync.SCOPE_TOB:
				return scopeId > 0 && raidController(scopeType) == scopeId;
			case BpdDefenceSync.SCOPE_INSTANCE:
				WorldView worldView = client.getTopLevelWorldView();
				return matchesInstance(worldView, scopeId);
			case BpdDefenceSync.SCOPE_WORLD:
			default:
				// Leaving render does not end an open-world encounter.
				return true;
		}
	}

	private static SyncScope instanceScope(WorldView worldView) {
		return new SyncScope(BpdDefenceSync.SCOPE_INSTANCE, EncounterScopes.instanceFingerprint(worldView));
	}

	private static boolean matchesInstance(WorldView worldView, int scopeId) {
		return worldView != null && worldView.isInstance()
				&& EncounterScopes.instanceFingerprint(worldView) == scopeId;
	}

	int raidController(int scopeType) {
		switch (scopeType) {
			case BpdDefenceSync.SCOPE_COX:
				return client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER);
			case BpdDefenceSync.SCOPE_TOB:
				return client.getVarpValue(VarPlayerID.TOB_MYCONTROLLER);
			default:
				return -1;
		}
	}

	static boolean healthMatches(NPC npc, int remoteHp) {
		int localHp = healthPercent(npc);
		return localHp < 0 || remoteHp < 0
				|| Math.abs(localHp - remoteHp) <= EncounterScopes.HEALTH_PERCENT_TOLERANCE;
	}

	static int healthPercent(NPC npc) {
		if (npc == null || npc.getHealthRatio() < 0 || npc.getHealthScale() <= 0) {
			return -1;
		}
		return Math.max(0, Math.min(100,
				(int) Math.round(npc.getHealthRatio() * 100.0 / npc.getHealthScale())));
	}
}

package net.betterpartydefence;

import net.runelite.api.WorldView;

/**
 * Static encounter classification shared by tracking, transport, and UI code.
 */
final class EncounterScopes
{
	static final int POSITION_TOLERANCE = 16;
	static final int HEALTH_PERCENT_TOLERANCE = 20;

	private EncounterScopes()
	{
	}

	static boolean isRaidEncounterBoss(BossDefence boss)
	{
		return raidScopeType(boss) != -1 || isToaBoss(boss) || isTfaBoss(boss);
	}

	static boolean isTfaBoss(BossDefence boss)
	{
		return boss != null && boss.has(BossDefence.Flag.TFA);
	}

	static boolean isToaBoss(BossDefence boss)
	{
		if (boss == null)
		{
			return false;
		}
		switch (boss)
		{
			case AKKHA:
			case AKKHAS_SHADOW:
			case BA_BA:
			case ELIDINIS_WARDEN:
			case KEPHRI:
			case OBELISK:
			case TUMEKENS_WARDEN:
			case ZEBAK:
				return true;
			default:
				return false;
		}
	}

	static int raidScopeType(BossDefence boss)
	{
		if (boss == null)
		{
			return -1;
		}
		if (boss.has(BossDefence.Flag.COX_SCALED))
		{
			return BpdDefenceSync.SCOPE_COX;
		}
		switch (boss)
		{
			case THE_MAIDEN_OF_SUGADINTI:
			case PESTILENT_BLOAT:
			case NYLOCAS_VASILIAS:
			case SOTETSEG:
			case XARPUS:
				return BpdDefenceSync.SCOPE_TOB;
			default:
				return -1;
		}
	}

	static int instanceFingerprint(WorldView worldView)
	{
		int hash = 17;
		hash = 31 * hash + worldView.getBaseX();
		hash = 31 * hash + worldView.getBaseY();
		int[][][] chunks = worldView.getInstanceTemplateChunks();
		if (chunks == null)
		{
			return hash;
		}
		for (int[][] plane : chunks)
		{
			if (plane == null)
			{
				continue;
			}
			for (int[] row : plane)
			{
				if (row == null)
				{
					continue;
				}
				for (int chunk : row)
				{
					hash = 31 * hash + chunk;
				}
			}
		}
		return hash;
	}
}

package net.betterpartydefence;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Function;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.betterpartydefence.DefenceTracker.SyncState;
import net.runelite.client.util.Text;

// Rules for matching events and comparing their timing.
// Ticks are relative to an event origin, not packet arrival.
// Use observation timestamps when clients have different clocks.
final class EncounterTimeline {
	static final int VERSION = 1;
	static final int MAX_EVENTS = 256;
	static final int MAX_REPLAY_STEPS = 100000;
	enum HistoryRelation {
		INITIAL, SAME, EXTENSION, STALE, CONFLICT
	}

	static final Comparator<SpecHistoryEntry> DISPLAY_ORDER = Comparator
			.comparing(SpecHistoryEntry::getTickAnchor)
			.thenComparingLong(SpecHistoryEntry::getEncounterTick)
			.thenComparing(SpecHistoryEntry::getEventId);

	private EncounterTimeline() {
	}

	static boolean hasIdentifiedEvents(List<SpecHistoryEntry> events) {
		return events != null && events.stream().anyMatch(e -> e != null && e.getEventId() != null);
	}

	static boolean containsIdentifiedEvents(List<SpecHistoryEntry> superset, List<SpecHistoryEntry> subset) {
		return subset == null || subset.stream().filter(e -> e != null && e.getEventId() != null)
				.allMatch(superset::contains);
	}

	static boolean complete(List<SpecHistoryEntry> events) {
		if (events == null || events.isEmpty() || events.size() > MAX_EVENTS) {
			return false;
		}
		Map<String, SpecHistoryEntry> ids = new HashMap<>();
		for (SpecHistoryEntry event : events) {
			if (event == null || event.getEventId() == null || event.getTickAnchor() == null
					|| event.getEventId().isEmpty() || event.getEventId().length() > 128
					|| event.getTickAnchor().isEmpty() || event.getTickAnchor().length() > 128
					|| event.getEncounterTick() < 0
					|| !event.isSupported()
					|| ids.put(event.getEventId(), event) != null) {
				return false;
			}
		}
		return true;
	}

	// Reject a merge if one event ID has different data.
	static List<SpecHistoryEntry> union(List<SpecHistoryEntry> local, List<SpecHistoryEntry> incoming) {
		if (local == null || incoming == null || local.size() + incoming.size() > MAX_EVENTS * 2) {
			return null;
		}
		List<SpecHistoryEntry> candidates = new ArrayList<>(local);
		candidates.addAll(incoming);
		local = identify(local, candidates);
		incoming = identify(incoming, candidates);
		if (!complete(local) || !complete(incoming)) {
			return null;
		}
		Map<String, SpecHistoryEntry> ids = new HashMap<>();
		for (SpecHistoryEntry event : local) {
			ids.put(event.getEventId(), event);
		}
		for (SpecHistoryEntry event : incoming) {
			SpecHistoryEntry old = ids.putIfAbsent(event.getEventId(), event);
			if (old != null) {
				if (!compatibleEvent(old, event)) {
					return null;
				}
				if (old.getObservedAtMillis() == 0L) {
					ids.put(event.getEventId(), event);
				}
			}
		}
		List<SpecHistoryEntry> result = new ArrayList<>(ids.values());
		result.sort(DISPLAY_ORDER);
		return complete(result) ? result : null;
	}

	// Assign an event ID to a standard echo only when one row matches.
	private static List<SpecHistoryEntry> identify(List<SpecHistoryEntry> events, List<SpecHistoryEntry> candidates) {
		List<SpecHistoryEntry> result = new ArrayList<>();
		for (SpecHistoryEntry event : events) {
			if (event == null) {
				return null;
			}
			if (event.getEventId() != null) {
				result.add(event);
				continue;
			}
			SpecHistoryEntry match = null;
			for (SpecHistoryEntry candidate : candidates) {
				if (candidate == null || candidate.getEventId() == null || !samePayload(event, candidate)) {
					continue;
				}
				if (match != null && !compatibleEvent(match, candidate)) {
					return null;
				}
				if (match == null || match.getObservedAtMillis() == 0L) {
					match = candidate;
				}
			}
			if (match == null || result.contains(match)) {
				return null;
			}
			// Identical old rows cannot be matched to one event ID.
			int count = 0;
			for (SpecHistoryEntry other : events) {
				if (other != null && samePayload(event, other)) {
					count++;
				}
			}
			if (count != 1) {
				return null;
			}
			result.add(match);
		}
		return result;
	}

	// Older peers may omit the observation timestamp.
	static boolean compatibleEvent(SpecHistoryEntry a, SpecHistoryEntry b) {
		return a.equals(b)
				|| ((a.getObservedAtMillis() == 0L || b.getObservedAtMillis() == 0L)
						&& a.withObservedAtMillis(0L).equals(b.withObservedAtMillis(0L)));
	}

	static boolean samePayload(SpecHistoryEntry a, SpecHistoryEntry b) {
		return Objects.equals(normalizedPlayer(a.getPlayerName()), normalizedPlayer(b.getPlayerName()))
				&& a.getWeapon() == b.getWeapon() && a.getSpell() == b.getSpell() && a.getHit() == b.getHit();
	}

	static String normalizedPlayer(String name) {
		return name == null ? "" : Text.toJagexName(Text.removeTags(name)).toLowerCase(Locale.ROOT);
	}

	// Order only when possible tick intervals do not overlap.
	// CoX sampling uncertainty stays unordered.
	static boolean before(SpecHistoryEntry a, SpecHistoryEntry b) {
		if (!Objects.equals(a.getTickAnchor(), b.getTickAnchor())) {
			return false;
		}
		long uncertainty = tickUncertainty(a.getTickAnchor());
		return a.getEncounterTick() + uncertainty < b.getEncounterTick();
	}

	// Use observation time for independent clocks.
	// Equal timestamps stay unordered; there is no minimum gap.
	private static boolean crossClockBefore(SpecHistoryEntry a, SpecHistoryEntry b) {
		return !Objects.equals(a.getTickAnchor(), b.getTickAnchor())
				&& a.getObservedAtMillis() > 0L && b.getObservedAtMillis() > 0L
				&& a.getObservedAtMillis() < b.getObservedAtMillis();
	}

	static long tickUncertainty(String anchor) {
		// The uncertainty suffix is not always at the end of the id.
		return anchor != null && anchor.contains(RaidTimerClock.TIMER_UNCERTAINTY_SUFFIX)
				? RaidTimerClock.TIMER_UNCERTAINTY_TICKS
				: 0L;
	}

	interface Replay<S> {
		S apply(S state, SpecHistoryEntry event);
		S conservative(S a, S b);
	}

	// Try every valid event order.
	// A single greedy order can miscalculate BGS spill and curses.
	// If the search limit is reached, return the undrained baseline.
	static <S> S replay(List<SpecHistoryEntry> events, S baseline, Replay<S> replay) {
		return replay(events, baseline, replay, null);
	}

	// Ignore orders that produce the same state and next events.
	static <S> S replay(List<SpecHistoryEntry> events, S baseline, Replay<S> replay,
			Function<SpecHistoryEntry, String> effectKey) {
		// Do not guess beyond the replay budget.
		if (events.size() > MAX_EVENTS) {
			return baseline;
		}
		Search<S> search = new Search<>(events, replay, effectKey);
		search.visit(baseline, new boolean[events.size()], 0);
		return search.exhausted ? baseline : search.best;
	}

	static HistoryRelation compareLegacy(SyncState local, SyncState incoming) {
		if (local == null) {
			return HistoryRelation.INITIAL;
		}
		if (local.getBossType() != incoming.getBossType()
				|| local.getBase() != incoming.getBase()
				|| local.getMin() != incoming.getMin()
				|| local.getMagicBaseLevel() != incoming.getMagicBaseLevel()
				|| local.getMagicBaseDef() != incoming.getMagicBaseDef()
				|| local.isMagicUsesDefence() != incoming.isMagicUsesDefence()
				|| local.isDemon() != incoming.isDemon()) {
			return HistoryRelation.CONFLICT;
		}

		List<SpecHistoryEntry> localHistory = local.getHistory();
		List<SpecHistoryEntry> incomingHistory = incoming.getHistory();
		if (localHistory == null || incomingHistory == null) {
			return HistoryRelation.CONFLICT;
		}

		// Any mismatch inside the shared prefix is a conflict.
		int prefix = Math.min(localHistory.size(), incomingHistory.size());
		for (int i = 0; i < prefix; i++) {
			SpecHistoryEntry localEvent = localHistory.get(i);
			SpecHistoryEntry incomingEvent = incomingHistory.get(i);
			if (localEvent == null
					|| incomingEvent == null
					|| localEvent.getWeapon() != incomingEvent.getWeapon()
					|| localEvent.getSpell() != incomingEvent.getSpell()
					|| localEvent.getHit() != incomingEvent.getHit()
					|| !normalizedPlayer(localEvent.getPlayerName())
							.equals(normalizedPlayer(incomingEvent.getPlayerName()))) {
				return HistoryRelation.CONFLICT;
			}
		}

		if (localHistory.size() > incomingHistory.size()) {
			return HistoryRelation.STALE;
		}
		if (localHistory.size() < incomingHistory.size()) {
			return HistoryRelation.EXTENSION;
		}
		return local.getCurrent() == incoming.getCurrent()
				&& local.getAttackLevel() == incoming.getAttackLevel()
				&& local.getStrengthLevel() == incoming.getStrengthLevel()
				&& local.getMagicLevel() == incoming.getMagicLevel()
				&& local.getMagicDef() == incoming.getMagicDef()
				&& local.isAccursedApplied() == incoming.isAccursedApplied()
				&& local.isDrained() == incoming.isDrained()
						? HistoryRelation.SAME
						: HistoryRelation.CONFLICT;
	}

	private static final class Search<S> {
		private final List<SpecHistoryEntry> events;
		private final Replay<S> replay;
		private final Function<SpecHistoryEntry, String> effectKey;
		private final List<List<Integer>> successors = new ArrayList<>();
		private final int[] remainingPredecessors;
		private S best;
		private int steps;
		private boolean exhausted;

		private Search(List<SpecHistoryEntry> events, Replay<S> replay,
				Function<SpecHistoryEntry, String> effectKey) {
			this.events = events;
			this.replay = replay;
			this.effectKey = effectKey;
			remainingPredecessors = new int[events.size()];
			if (buildGraph(true) && hasCycle()) {
				// Wall-clock corrections can contradict tick order.
				buildGraph(false);
			}
		}

		private boolean buildGraph(boolean useWallClock) {
			successors.clear();
			Arrays.fill(remainingPredecessors, 0);
			boolean usedWallClock = false;
			for (int i = 0; i < events.size(); i++) {
				List<Integer> next = new ArrayList<>();
				for (int j = 0; j < events.size(); j++) {
					SpecHistoryEntry a = events.get(i);
					SpecHistoryEntry b = events.get(j);
					boolean estimated = useWallClock && crossClockBefore(a, b);
					if (estimated || before(a, b)) {
						usedWallClock |= estimated;
						next.add(j);
						remainingPredecessors[j]++;
					}
				}
				successors.add(next);
			}
			return usedWallClock;
		}

		private boolean hasCycle() {
			int[] predecessors = remainingPredecessors.clone();
			ArrayDeque<Integer> ready = new ArrayDeque<>();
			for (int i = 0; i < predecessors.length; i++) {
				if (predecessors[i] == 0) {
					ready.addLast(i);
				}
			}
			int visited = 0;
			while (!ready.isEmpty()) {
				visited++;
				for (int next : successors.get(ready.removeFirst())) {
					if (--predecessors[next] == 0) {
						ready.addLast(next);
					}
				}
			}
			return visited != events.size();
		}

		private void visit(S state, boolean[] used, int depth) {
			if (++steps > MAX_REPLAY_STEPS) {
				exhausted = true;
				return;
			}
			if (depth == events.size()) {
				best = best == null ? state : replay.conservative(best, state);
				return;
			}
			Set<String> triedEffects = effectKey == null ? null : new HashSet<>();
			for (int i = 0; i < events.size() && !exhausted; i++) {
				if (!used[i] && remainingPredecessors[i] == 0) {
					if (triedEffects != null) {
						String key = effectKey.apply(events.get(i));
						if (key != null) {
							// Only combine events that release the same next events.
							key = key + "|" + successors.get(i);
							if (!triedEffects.add(key)) {
								// Same state and next events.
								continue;
							}
						}
					}
					used[i] = true;
					for (int next : successors.get(i)) {
						remainingPredecessors[next]--;
					}
					visit(replay.apply(state, events.get(i)), used, depth + 1);
					for (int next : successors.get(i)) {
						remainingPredecessors[next]++;
					}
					used[i] = false;
				}
			}
		}
	}
}

package net.betterpartydefence;

import java.util.HashMap;
import java.util.Map;

// Hide the first undrained frame while peer state loads.
final class InitialSyncDisplayGate {
	private static final class Gate {
		private final BossDefence boss;
		private final int expiresAtTick;

		private Gate(BossDefence boss, int expiresAtTick) {
			this.boss = boss;
			this.expiresAtTick = expiresAtTick;
		}
	}

	private final Map<Integer, Gate> gates = new HashMap<>();

	// Do not extend an active grace period.
	void arm(int npcIndex, BossDefence boss, int tick, int graceTicks) {
		boss = boss == null ? null : boss.trackingType();
		if (npcIndex < 0 || boss == null || graceTicks <= 0) {
			return;
		}

		Gate existing = gates.get(npcIndex);
		if (existing != null && tick < existing.expiresAtTick && existing.boss == boss) {
			return;
		}
		gates.put(npcIndex, new Gate(boss, tick + graceTicks));
	}

	// Validated party state releases the gate.
	void release(int npcIndex, BossDefence boss) {
		boss = boss == null ? null : boss.trackingType();
		Gate gate = gates.get(npcIndex);
		if (gate != null && gate.boss == boss) {
			gates.remove(npcIndex);
		}
	}

	// Clear gates for an ended encounter.
	void clearForBoss(BossDefence boss) {
		if (boss == null) {
			return;
		}
		BossDefence trackingBoss = boss.trackingType();
		gates.entrySet().removeIf(entry -> entry.getValue().boss == trackingBoss);
	}

	// Drained state is always displayable.
	boolean isWaiting(DefenceTracker.DefenceState state, int tick) {
		if (state == null || state.isDrained()) {
			return false;
		}
		Gate gate = gates.get(state.getNpcIndex());
		return gate != null && tick < gate.expiresAtTick;
	}

	void expire(int tick) {
		gates.entrySet().removeIf(entry -> tick >= entry.getValue().expiresAtTick);
	}

	void clear() {
		gates.clear();
	}
}

package net.betterpartydefence;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Hitsplat;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.FakeXpDrop;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.specialcounter.SpecialCounterUpdate;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

// Detects local defence-draining special attacks.
// Broadcasts the standard party message when SAC is inactive.
@Slf4j
@Singleton
class LocalDefenceSpecDetector {
	private static final int RALOS_UNKNOWN = -1;
	private final Client client;
	private final ClientThread clientThread;
	private final PartyService partyService;
	private final PluginManager pluginManager;
	private final DefenceTracker defenceTracker;

	private int specialPercentage = -1;
	private int lastHitPointsExperience = -1;
	private int lastHpChangeCycle = -1;

	private SpecialWeapon weapon;
	private NPC target;
	private int hitsplatTick = -1;
	private long hitsplatObservedAtMillis;
	private boolean hpChangedOnSpecCycle;
	private final List<Integer> hitsplats = new ArrayList<>();

	@Inject
	LocalDefenceSpecDetector(
			Client client,
			ClientThread clientThread,
			PartyService partyService,
			PluginManager pluginManager,
			DefenceTracker defenceTracker) {
		this.client = client;
		this.clientThread = clientThread;
		this.partyService = partyService;
		this.pluginManager = pluginManager;
		this.defenceTracker = defenceTracker;
	}

	void reset() {
		specialPercentage = -1;
		lastHitPointsExperience = -1;
		lastHpChangeCycle = -1;
		clearPending();
	}

	void onFakeXpDrop(FakeXpDrop event) {
		if (event.getSkill() == Skill.HITPOINTS) {
			lastHpChangeCycle = client.getGameCycle();
		}
	}

	void onStatChanged(StatChanged event) {
		if (event.getSkill() != Skill.HITPOINTS) {
			return;
		}

		if (event.getXp() > lastHitPointsExperience) {
			lastHpChangeCycle = client.getGameCycle();
		}
		lastHitPointsExperience = event.getXp();
	}

	void onVarbitChanged(VarbitChanged event) {
		if (event.getVarpId() != VarPlayerID.SA_ENERGY) {
			return;
		}

		int current = event.getValue();
		if (specialPercentage == -1 || current >= specialPercentage) {
			specialPercentage = current;
			return;
		}

		// Defer the equipment read, but capture the current target now.
		// The target can disappear before equipment is read.
		specialPercentage = current;
		final int serverTick = client.getTickCount();
		final NPC castTarget = interactingNpc();
		clientThread.invokeLater(() -> beginSpec(serverTick, castTarget));
	}

	private NPC interactingNpc() {
		Player local = client.getLocalPlayer();
		Actor interacting = local == null ? null : local.getInteracting();
		return interacting instanceof NPC ? (NPC) interacting : null;
	}

	// Prefer the captured cast target.
	// Only reuse the live interaction when it is the same NPC.
	NPC resolveTarget(NPC castTarget) {
		NPC live = interactingNpc();
		if (castTarget == null) {
			// No captured target; use the current interaction.
			return live;
		}
		if (live != null && sameCapturedTarget(live, castTarget)) {
			return live;
		}
		if (live != null) {
			log.debug("Local defence spec keeps captured target {} and ignores new interaction {}",
					castTarget.getName(), live.getName());
		}
		if (castTarget.getName() == null || BossDefence.matchingNpc(castTarget) == null) {
			return null;
		}
		log.debug("Local defence spec target resolved from captured actor: target={} npc={}",
				castTarget.getName(), castTarget.getIndex());
		return castTarget;
	}

	private static boolean sameCapturedTarget(NPC live, NPC cast) {
		return live == cast || (live.getId() == cast.getId() && live.getIndex() == cast.getIndex());
	}

	private void beginSpec(int serverTick, NPC castTarget) {
		SpecialWeapon used = usedSupportedWeapon();
		if (used == null) {
			return;
		}

		NPC npc = resolveTarget(castTarget);
		if (npc == null) {
			log.debug("Local defence spec {} ignored: no NPC target", used);
			return;
		}

		if (npc.getName() == null || BossDefence.matchingNpc(npc) == null) {
			log.debug("Local defence spec {} ignored: unsupported target {}", used, npc.getName());
			return;
		}

		weapon = used;
		target = npc;
		hpChangedOnSpecCycle = lastHpChangeCycle == client.getGameCycle();
		hitsplatTick = serverTick + hitDelay(used, npc);
		hitsplats.clear();
		hitsplatObservedAtMillis = 0L;
		log.debug("Local defence spec armed: weapon={} target={} npc={} expectedTick={}",
				weapon, npc.getName(), npc.getIndex(), hitsplatTick);
	}

	void onHitsplatApplied(HitsplatApplied event) {
		if (weapon == null || target == null) {
			return;
		}

		Hitsplat splat = event.getHitsplat();
		Actor observedActor = event.getActor();
		if (!splat.isMine() || !(observedActor instanceof NPC)
				|| !sameLogicalTarget(target, (NPC) observedActor)) {
			// Exclude other actors and non-owned hitsplats.
			log.debug("Local defence spec hitsplat ignored: mine={} armed={}:{} observed={}:{}",
					splat.isMine(), target.getName(), target.getId(),
					observedActor == null ? "null" : observedActor.getName(),
					observedActor instanceof NPC ? ((NPC) observedActor).getId() : -1);
			return;
		}
		target = (NPC) observedActor;

		int tick = client.getTickCount();
		if (tick == hitsplatTick) {
			if (hitsplats.isEmpty()) {
				hitsplatObservedAtMillis = System.currentTimeMillis();
			}
			hitsplats.add(splat.getAmount());
			log.debug("Local defence spec hitsplat accepted: weapon={} amount={} type={} tick={} expected={}",
					weapon, splat.getAmount(), splat.getHitsplatType(), tick, hitsplatTick);
		} else {
			log.debug("Local defence spec hitsplat ignored: tick mismatch tick={} expected={} amount={} type={}",
					tick, hitsplatTick, splat.getAmount(), splat.getHitsplatType());
		}
	}

	// Process captured hits before the tracker reads its queue.
	void onGameTick() {
		if (weapon == null || target == null) {
			return;
		}

		int tick = client.getTickCount();
		log.debug("Local defence spec tick check: weapon={} tick={} expected={} hitsplats={}",
				weapon, tick, hitsplatTick, hitsplats.size());

		// Elder Maul uses the HP-change signal.
		if (weapon == SpecialWeapon.ELDER_MAUL) {
			record(weapon, hpChangedOnSpecCycle ? 1 : 0, target);
			clearPending();
			return;
		}

		// Allow one extra tick for late hitsplat callbacks.
		if ((tick == hitsplatTick || tick == hitsplatTick + 1) && !hitsplats.isEmpty()) {
			int rawHit;
			if (weapon == SpecialWeapon.TONALZTICS_OF_RALOS) {
				// Delayed weapon hits precede thrall and Vengeance.
				// Ralos uses the first two hitsplats.
				rawHit = countConfirmedRalosHits(hitsplats);
			} else {
				// Instant hits follow thrall damage.
				rawHit = resolveObservedHit(weapon, hitsplats);
			}
			if (rawHit >= 0) {
				record(weapon, rawHit, target);
				clearPending();
				return;
			}
		}
		if (tick > hitsplatTick) {
			log.debug("Local defence spec timed out waiting for hitsplat: {}", weapon);
			clearPending();
		}
	}

	// Match RuneLite's first-vs-last hitsplat rule.
	static int resolveObservedHit(SpecialWeapon weapon, List<Integer> observedHits) {
		if (weapon == null || observedHits == null || observedHits.isEmpty()) {
			throw new IllegalArgumentException("A weapon and observed hitsplat are required");
		}
		return observedHits.get(weapon.getHitDelay(1) > 1 ? 0 : observedHits.size() - 1);
	}

	// Count Ralos from the first two glaive hitsplats.
	// Zero is a miss; incomplete pairs stay unresolved.
	static int countConfirmedRalosHits(List<Integer> orderedHitsplats) {
		if (orderedHitsplats == null || orderedHitsplats.size() < 2) {
			return RALOS_UNKNOWN;
		}
		Integer first = orderedHitsplats.get(0);
		Integer second = orderedHitsplats.get(1);
		if (first == null || second == null || first < 0 || second < 0) {
			return RALOS_UNKNOWN;
		}
		return (first > 0 ? 1 : 0) + (second > 0 ? 1 : 0);
	}

	private static boolean sameLogicalTarget(NPC armed, NPC observed) {
		if (armed == observed) {
			return true;
		}
		if (armed == null || observed == null || armed.isDead()) {
			return false;
		}

		BossDefence boss = BossDefence.matchingNpc(armed);
		if (boss == null || BossDefence.matchingNpc(observed) != boss
				|| observed.getId() != armed.getId()) {
			return false;
		}
		if (boss == BossDefence.GIANT_MOLE && armed.getIndex() == observed.getIndex()) {
			return true;
		}
		return TargetResolver.matches(
				observed, boss, armed.getId(), armed.getWorldLocation(), 2);
	}

	private void record(SpecialWeapon used, int rawHit, NPC npc) {
		if (npc == null) {
			return;
		}

		int world = client.getWorld();
		int npcIndex = npc.getIndex();
		log.debug("Local defence spec: weapon={} hit={} target={} npc={} world={}",
				used, rawHit, npc.getName(), npcIndex, world);

		Player local = client.getLocalPlayer();
		String playerName = local != null && local.getName() != null ? local.getName() : "You";

		// Apply locally before optional party broadcast.
		defenceTracker.queueLocal(used, npcIndex, rawHit, world, playerName, npc,
				hitsplatObservedAtMillis > 0 ? hitsplatObservedAtMillis : System.currentTimeMillis());

		// Special Attack Counter already sends this when active.
		if (partyService.isInParty() && !isSpecialCounterActive()) {
			if (local != null) {
				partyService.send(new SpecialCounterUpdate(npcIndex, used, rawHit, world, local.getId()));
				log.debug("Broadcast local defence spec through Hub Party session: {}", used);
			}
		}
	}

	private SpecialWeapon usedSupportedWeapon() {
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null) {
			return null;
		}

		Item item = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (item == null) {
			return null;
		}

		return SpecialWeaponRules.byItemId(item.getId());
	}

	private int hitDelay(SpecialWeapon used, Actor actor) {
		Player local = client.getLocalPlayer();
		if (local == null || actor == null) {
			return 1;
		}

		WorldPoint playerPoint = local.getWorldLocation();
		WorldArea targetArea = actor.getWorldArea();
		if (playerPoint == null || targetArea == null) {
			return 1;
		}
		return used.getHitDelay(targetArea.distanceTo(playerPoint));
	}

	private boolean isSpecialCounterActive() {
		return SpecialCounterState.isActive(pluginManager);
	}

	private void clearPending() {
		weapon = null;
		target = null;
		hitsplatTick = -1;
		hpChangedOnSpecCycle = false;
		hitsplats.clear();
		hitsplatObservedAtMillis = 0L;
	}
}

package net.betterpartydefence;

import java.awt.Dimension;
import java.awt.Graphics2D;
import net.betterpartydefence.BetterPartyDefenceConfig.DefenceOverlayPosition;
import net.betterpartydefence.DefenceTracker.DefenceState;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class NpcDefenceOverlay extends Overlay {
	private final Client client;
	private final DefenceTracker tracker;
	private final BetterPartyDefenceConfig config;
	private final DefenceOverlayRenderer renderer;
	private final InitialSyncDisplayGate initialSyncDisplayGate;

	public NpcDefenceOverlay(Client client, DefenceTracker tracker, BetterPartyDefenceConfig config,
			DefenceOverlayRenderer.IconSource skillIcons, InitialSyncDisplayGate initialSyncDisplayGate) {
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		this.renderer = new DefenceOverlayRenderer(config, skillIcons);
		this.initialSyncDisplayGate = initialSyncDisplayGate;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (!config.defenceHpBar()) {
			return null;
		}

		graphics.setFont(renderer.font());
		DefenceOverlayPosition position = config.defenceHpBarPosition();
		int yOffset = config.defenceHpBarYOffset();
		for (DefenceState state : tracker.states()) {
			if (!isDisplayable(state)) {
				continue;
			}
			NPC npc = liveNpc(state.getNpcIndex());
			if (npc != null) {
				renderAtNpc(graphics, state, npc, position, yOffset);
			}
		}
		return null;
	}

	private void renderAtNpc(Graphics2D graphics, DefenceState state, NPC npc,
			DefenceOverlayPosition position, int yOffset) {
		// Ocellus P2 uses the model midpoint as its display height.
		int zOffset;
		if (BossDefence.isAttackableOcellusPhaseTwo(npc)) {
			zOffset = (int) (npc.getLogicalHeight() * 0.5 * position.getHeightFactor());
		} else {
			zOffset = (int) (npc.getLogicalHeight() * position.getHeightFactor()) + position.getHeightOffset();
		}
		Point anchor = npc.getCanvasTextLocation(graphics, "", zOffset);
		if (anchor == null) {
			return;
		}
		int centreX = anchor.getX() + position.getXNudge();
		int baseline = anchor.getY() - yOffset;
		renderer.renderAt(graphics, state, centreX, baseline);
	}

	private boolean isDisplayable(DefenceState state) {
		// Config controls previews only; drained state is always shown.
		return state != null && (state.isDrained() || config.defenceAlwaysShow())
				&& state.getNpcIndex() >= 0
				&& !initialSyncDisplayGate.isWaiting(state, client.getTickCount());
	}

	private NPC liveNpc(int index) {
		if (index < 0 || client.getTopLevelWorldView() == null || client.getTopLevelWorldView().npcs() == null) {
			return null;
		}
		NPC npc = client.getTopLevelWorldView().npcs().byIndex(index);
		return BossDefence.isLiveNpc(npc) ? npc : null;
	}
}

package net.betterpartydefence;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.function.BiConsumer;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.betterpartydefence.DefenceTracker.SpellDrain;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

// Bounded queues for specs whose local target is not yet unambiguous.
@Slf4j
final class PendingSpecQueue {
	private static final int HELD_DRAIN_TTL_TICKS = 200;
	private static final int MAX_HELD_DRAINS = 256;
	private static final int MAX_HELD_DRAINS_PER_TARGET = 64;
	private static final int PENDING_TARGET_DISTANCE = 2;

	private final Client client;
	private final ConcurrentLinkedDeque<Observation> pending = new ConcurrentLinkedDeque<>();
	private final List<HeldQueue> held = new ArrayList<>();

	PendingSpecQueue(Client client) {
		this.client = client;
	}

	// One queued defence-draining observation.
	@Value
	static class Observation {
		SpecialWeapon weapon;
		SpellDrain spell;
		int npcIndex;
		int hit;
		int world;
		String playerName;
		String eventId;
		int observedTick;
		long observedAtMillis;
		String tickAnchor;
		int tickAnchorTick;
		long tickAnchorValue;
		TargetEvidence target;
		int receivedTick;
		DefenceTracker.SpecHistoryEntry partyEntry;
	}

	// Target details found on this client.
	@Value
	static class TargetEvidence {
		BossDefence bossType;
		int npcId;
		WorldPoint location;
		// The local NPC object is used to detect index reuse.
		NPC actor;

		static TargetEvidence from(NPC npc) {
			if (npc == null) {
				return null;
			}
			BossDefence boss = BossDefence.matchingNpc(npc);
			return boss == null ? null : new TargetEvidence(boss, npc.getId(), npc.getWorldLocation(), npc);
		}

		boolean matches(NPC npc) {
			if (actor != null) {
				return npc == actor && BossDefence.isLiveNpc(npc);
			}
			return TargetResolver.matches(npc, bossType, npcId, location, PENDING_TARGET_DISTANCE);
		}
	}

	// Ordered observations for one unresolved actor.
	private static class HeldQueue {
		final PendingTarget target;
		final List<Observation> observations = new ArrayList<>();
		// Never guess after the target becomes ambiguous.
		boolean ambiguous;

		HeldQueue(PendingTarget target) {
			this.target = target;
		}
	}

	// Exact is set when the local detector supplies the NPC.
	// Legacy party packets provide only a scene-index hint.
	private static class PendingTarget {
		final int npcIndex;
		BossDefence bossType;
		int npcId;
		WorldPoint location;
		final NPC indexedActor;
		final boolean exact;

		PendingTarget(
				int npcIndex, BossDefence bossType, int npcId, WorldPoint location,
				NPC indexedActor, boolean exact) {
			this.npcIndex = npcIndex;
			this.bossType = bossType;
			this.npcId = npcId;
			this.location = location;
			this.indexedActor = indexedActor;
			this.exact = exact;
		}

		static PendingTarget from(Observation observation, NPC indexedActor) {
			TargetEvidence target = observation.getTarget();
			if (target != null) {
				return new PendingTarget(observation.getNpcIndex(), target.getBossType(), target.getNpcId(),
						target.getLocation(), target.getActor(), true);
			}

			BossDefence boss = BossDefence.matchingNpc(indexedActor);
			if (boss != null) {
				return new PendingTarget(observation.getNpcIndex(), boss, indexedActor.getId(),
						indexedActor.getWorldLocation(), indexedActor, false);
			}
			return new PendingTarget(observation.getNpcIndex(), null, -1, null, null, false);
		}

		boolean sameTarget(PendingTarget other) {
			return other != null && exact == other.exact && npcIndex == other.npcIndex
					&& (indexedActor != null || other.indexedActor != null
							? indexedActor == other.indexedActor
							: bossType == other.bossType && npcId == other.npcId
									&& Objects.equals(location, other.location));
		}
	}

	static TargetEvidence captureTarget(NPC npc) {
		return TargetEvidence.from(npc);
	}

	void add(Observation observation, boolean priority) {
		if (priority) {
			pending.addFirst(observation);
		} else {
			pending.addLast(observation);
		}
	}

	Observation poll() {
		return pending.poll();
	}

	// A local spec includes the NPC object.
	// Legacy party specs require one unambiguous local target.
	NPC resolveTarget(Observation observation) {
		NPC indexed = npcByIndex(observation.getNpcIndex());
		if (observation.getTarget() != null) {
			return observation.getTarget().matches(indexed) ? indexed : null;
		}
		if (indexed == null || !BossDefence.isLiveNpc(indexed)) {
			return null;
		}
		BossDefence boss = BossDefence.matchingNpc(indexed);
		if (boss == null) {
			return null;
		}
		NPC unique = TargetResolver.uniqueLiveNpc(client.getTopLevelWorldView(), boss);
		if (unique != null) {
			return unique;
		}
		// Use the indexed actor only when no competing candidate exists.
		return TargetResolver.liveCandidates(client.getTopLevelWorldView(), boss).isEmpty()
				? indexed
				: null;
	}

	// Keep one queue for each unresolved NPC.
	void hold(Observation observation) {
		NPC indexed = npcByIndex(observation.getNpcIndex());
		PendingTarget target = PendingTarget.from(observation, indexed);
		HeldQueue queue = null;
		for (HeldQueue candidate : held) {
			if (candidate.target.sameTarget(target)) {
				queue = candidate;
				break;
			}
		}
		if (queue == null) {
			queue = new HeldQueue(target);
			held.add(queue);
		}
		queue.observations.add(observation);

		if (!target.exact && target.bossType != null
				&& TargetResolver.liveCandidates(client.getTopLevelWorldView(), target.bossType).size() > 1) {
			queue.ambiguous = true;
		}
		while (queue.observations.size() > MAX_HELD_DRAINS_PER_TARGET) {
			queue.observations.remove(0);
		}
		trimToCapacity();
	}

	// Retry unresolved targets independently.
	// Keep queue order within each target.
	void replay(BiConsumer<Observation, NPC> apply) {
		int tick = client.getTickCount();
		List<HeldQueue> attempt = new ArrayList<>(held);
		for (HeldQueue queue : attempt) {
			if (!held.contains(queue)) {
				continue;
			}
			int beforeExpiry = queue.observations.size();
			queue.observations.removeIf(observation ->
					tick - observation.getReceivedTick() > HELD_DRAIN_TTL_TICKS);
			if (queue.observations.isEmpty()) {
				if (beforeExpiry > 0) {
					log.debug("Dropping {} held drains for npc {} after {} ticks",
							beforeExpiry, queue.target.npcIndex, HELD_DRAIN_TTL_TICKS);
				}
				held.remove(queue);
				continue;
			}

			NPC indexed = npcByIndex(queue.target.npcIndex);
			if (queue.target.indexedActor != null && indexed != null
					&& indexed != queue.target.indexedActor) {
				log.debug("Dropping held drains for reused npc index {}", queue.target.npcIndex);
				held.remove(queue);
				continue;
			}
			if (queue.target.indexedActor != null && queue.target.indexedActor.isDead()) {
				held.remove(queue);
				continue;
			}

			NPC target = resolveHeldTarget(queue, indexed);
			if (target == null) {
				continue;
			}
			held.remove(queue);
			for (Observation observation : queue.observations) {
				apply.accept(observation, target);
			}
		}
	}

	private NPC resolveHeldTarget(HeldQueue queue, NPC indexed) {
		PendingTarget pendingTarget = queue.target;
		if (pendingTarget.exact) {
			return pendingTarget.indexedActor != null && indexed == pendingTarget.indexedActor
					&& BossDefence.isLiveNpc(indexed) ? indexed : null;
		}
		// A legacy scene index only helps find the NPC on this client.
		// Use it only when one matching NPC is visible.
		BossDefence boss = pendingTarget.bossType;
		if (boss == null && BossDefence.isLiveNpc(indexed)) {
			boss = BossDefence.matchingNpc(indexed);
		}
		if (boss == null) {
			return null;
		}

		List<NPC> candidates = TargetResolver.liveCandidates(client.getTopLevelWorldView(), boss);
		if (candidates.size() > 1) {
			queue.ambiguous = true;
		}
		if (queue.ambiguous) {
			return null;
		}
		if (candidates.size() == 1) {
			NPC candidate = candidates.get(0);
			if (pendingTarget.indexedActor == null && candidate.getIndex() != pendingTarget.npcIndex) {
				return null;
			}
			return candidate;
		}
		return candidates.isEmpty() && BossDefence.isLiveNpc(indexed)
				&& BossDefence.matchingNpc(indexed) == boss ? indexed : null;
	}

	private void trimToCapacity() {
		int total = heldCount();
		while (total > MAX_HELD_DRAINS) {
			HeldQueue oldest = null;
			for (HeldQueue queue : held) {
				if (!queue.observations.isEmpty() && (oldest == null
						|| queue.observations.get(0).getReceivedTick()
								< oldest.observations.get(0).getReceivedTick())) {
					oldest = queue;
				}
			}
			if (oldest == null) {
				break;
			}
			oldest.observations.remove(0);
			if (oldest.observations.isEmpty()) {
				held.remove(oldest);
			}
			total--;
		}
	}

	private int heldCount() {
		int count = 0;
		for (HeldQueue queue : held) {
			count += queue.observations.size();
		}
		return count;
	}

	void clearDeferredForTarget(int npcIndex, NPC actor) {
		boolean hasIndex = npcIndex >= 0;
		held.removeIf(queue -> (hasIndex && queue.target.npcIndex == npcIndex)
				|| (actor != null && queue.target.indexedActor == actor));
		pending.removeIf(observation -> (hasIndex && observation.getNpcIndex() == npcIndex)
				|| (actor != null && observation.getTarget() != null
						&& observation.getTarget().getActor() == actor));
	}

	void clearDeferredForBoss(BossDefence boss) {
		held.removeIf(queue -> queue.target.bossType == boss);
		pending.removeIf(observation -> observation.getTarget() != null
				&& observation.getTarget().getBossType() == boss);
	}

	boolean isEmpty() {
		return pending.isEmpty() && held.isEmpty();
	}

	boolean hasForBoss(BossDefence boss) {
		for (Observation observation : pending) {
			BossDefence observationBoss = bossType(observation);
			if (observationBoss == null || observationBoss == boss) {
				return true;
			}
		}
		for (HeldQueue queue : held) {
			if (queue.target.bossType == null || queue.target.bossType == boss) {
				return true;
			}
		}
		return false;
	}

	boolean hasForTarget(int npcIndex) {
		return pending.stream().anyMatch(observation -> observation.getNpcIndex() == npcIndex)
				|| held.stream().anyMatch(queue -> queue.target.npcIndex == npcIndex);
	}

	private BossDefence bossType(Observation observation) {
		if (observation.getTarget() != null) {
			return observation.getTarget().getBossType();
		}
		return BossDefence.matchingNpc(npcByIndex(observation.getNpcIndex()));
	}

	private NPC npcByIndex(int index) {
		WorldView worldView = client.getTopLevelWorldView();
		return worldView == null || worldView.npcs() == null ? null : worldView.npcs().byIndex(index);
	}

	void clear() {
		pending.clear();
		held.clear();
	}
}

package net.betterpartydefence;

import java.util.Objects;
import java.util.UUID;

// Converts verified raid timer readings to shared elapsed ticks.
// ToA/TFA use root scripts; CoX uses the locally interpolated RAIDS_TIMER.
// ToB has no verified shared timer.
final class RaidTimerClock {
	static final int SOURCE_TOA = 1;
	static final int SOURCE_TFA = 2;
	static final int SOURCE_COX = 3;

	// Root scripts expose [scriptId, elapsedTicks, stopped].
	static final int TOA_TIMER_SCRIPT = 6580;
	static final int TFA_TIMER_SCRIPT = 10036;

	static final long NO_TICK = Long.MIN_VALUE;

	// Allow small backwards corrections.
	static final int RESET_BACKWARD_TOLERANCE = 2;
	// Timer readings can differ by two ticks between clients.
	// Events with overlapping possible times stay unordered.
	static final String TIMER_UNCERTAINTY_SUFFIX = ":u2";
	static final int TIMER_UNCERTAINTY_TICKS = 2;
	// Sanity cap of about 33 hours.
	static final int MAX_ELAPSED_TICKS = 200_000;
	private static final int MAX_DOMAIN_LENGTH = 128;

	// One validated timer-script reading.
	static final class TimerInput {
		final int source;
		final int elapsedTicks;
		final boolean stopped;

		private TimerInput(int source, int elapsedTicks, boolean stopped) {
			this.source = source;
			this.elapsedTicks = elapsedTicks;
			this.stopped = stopped;
		}
	}

	private int source = -1;
	private String scopeKey;
	private String domain;
	private int anchorLocalTick;
	private int anchorRaidTick;
	private boolean stopped;
	private boolean active;
	// Starts a new timing range after an untrusted backwards jump.
	private int generation;
	// Add a random client token so separate corrections never share an id.
	private final String clientToken = UUID.randomUUID().toString().replace("-", "");

	// Check only the documented root-script arguments.
	static TimerInput parseTimerScript(int scriptId, Object[] arguments) {
		int source = sourceForScript(scriptId);
		if (source == -1 || arguments == null || arguments.length != 3) {
			return null;
		}
		Integer id = asInt(arguments[0]);
		Integer elapsed = asInt(arguments[1]);
		Integer stopped = asInt(arguments[2]);
		if (id == null || id != scriptId || elapsed == null || stopped == null
				|| stopped < 0 || stopped > 1
				|| elapsed < -1 || elapsed > MAX_ELAPSED_TICKS) {
			return null;
		}
		return new TimerInput(source, elapsed, stopped != 0);
	}

	private static Integer asInt(Object value) {
		return value instanceof Number ? ((Number) value).intValue() : null;
	}

	static int sourceForScript(int scriptId) {
		switch (scriptId) {
			case TOA_TIMER_SCRIPT :
				return SOURCE_TOA;
			case TFA_TIMER_SCRIPT :
				return SOURCE_TFA;
			default :
				return -1;
		}
	}

	static String sourceName(int source) {
		switch (source) {
			case SOURCE_TOA :
				return "toa";
			case SOURCE_TFA :
				return "tfa";
			case SOURCE_COX :
				return "cox";
			default :
				return "unknown";
		}
	}

	// Record a validated timer reading.
	boolean sample(int source, String scopeKey, int raidTick, boolean stopped, int localTick) {
		if (!isKnownSource(source) || scopeKey == null || scopeKey.isEmpty()
				|| localTick < 0 || raidTick > MAX_ELAPSED_TICKS) {
			return false;
		}
		if (raidTick < 0) {
			if (active && this.source == source) {
				clear();
			}
			return false;
		}
		// A stopped-only sample cannot start a clock.
		if (stopped && !active) {
			return false;
		}
		if (active && this.source != source) {
			clear();
		}
		String nextDomain = domain(source, scopeKey);
		int epochLength = generation > 0
				? (":" + clientToken + ":g" + generation).length()
				: 0;
		if (nextDomain.length() + epochLength > MAX_DOMAIN_LENGTH) {
			return false;
		}
		if (!active) {
			// Keep the current timing range separated.
			establish(source, nextDomain, scopeKey, raidTick, stopped, localTick);
			return true;
		}

		boolean scopeChanged = !Objects.equals(scopeKey, this.scopeKey);
		if (scopeChanged) {
			// Switch to the new instance id without trusting old timestamps.
			int expected = anchorRaidTick + (localTick - anchorLocalTick);
			if (raidTick < expected - RESET_BACKWARD_TOLERANCE) {
				// A large backwards jump in a new scene starts a new range.
				generation++;
			}
			establish(source, nextDomain, scopeKey, raidTick, stopped, localTick);
			return true;
		}

		boolean resumed = this.stopped && !stopped;
		int expected = anchorRaidTick + (localTick - anchorLocalTick);
		if (raidTick < expected) {
			if (resumed) {
				// Resuming a stopped timer starts a new range.
				generation++;
				establish(source, nextDomain, scopeKey, raidTick, stopped, localTick);
				return true;
			}
			if (expected - raidTick > RESET_BACKWARD_TOLERANCE) {
				// Unknown backwards jump; disable the clock but keep the range counter.
				invalidate();
				return false;
			}
			// Small correction; keep the existing tick mapping.
			this.stopped = stopped;
			return true;
		}

		// Move the tick anchor and keep the range separated.
		this.domain = domainWithGeneration(nextDomain);
		this.scopeKey = scopeKey;
		anchorLocalTick = localTick;
		anchorRaidTick = raidTick;
		this.stopped = stopped;
		return true;
	}

	// Stop the clock without extending it.
	void markStopped() {
		if (active) {
			stopped = true;
		}
	}

	void clear() {
		source = -1;
		scopeKey = null;
		domain = null;
		anchorLocalTick = 0;
		anchorRaidTick = 0;
		stopped = false;
		active = false;
		generation = 0;
	}

	// Disable after an unknown jump; keep the range counter.
	private void invalidate() {
		source = -1;
		domain = null;
		anchorLocalTick = 0;
		anchorRaidTick = 0;
		stopped = false;
		active = false;
		generation++;
		// Keep the instance id to detect a real change.
	}

	// Convert a local tick to elapsed raid ticks.
	long tickAt(int localTick) {
		if (!active || localTick < 0) {
			return NO_TICK;
		}
		if (stopped && localTick != anchorLocalTick) {
			return NO_TICK;
		}
		long tick = (long) anchorRaidTick + ((long) localTick - anchorLocalTick);
		return tick >= 0 ? tick : NO_TICK;
	}

	boolean isActive() {
		return active;
	}

	boolean isActiveFor(int source) {
		return active && this.source == source;
	}

	boolean isStopped() {
		return active && stopped;
	}

	String domain() {
		return active ? domain : null;
	}

	int anchorLocalTick() {
		return anchorLocalTick;
	}

	int anchorRaidTick() {
		return anchorRaidTick;
	}

	private void establish(int source, String domain, String scopeKey, int raidTick,
			boolean stopped, int localTick) {
		this.source = source;
		this.domain = domainWithGeneration(domain);
		this.scopeKey = scopeKey;
		this.anchorLocalTick = localTick;
		this.anchorRaidTick = raidTick;
		this.stopped = stopped;
		this.active = true;
	}

	// Add the client token only to corrected timing ranges.
	private String domainWithGeneration(String base) {
		return generation == 0 ? base : base + ":" + clientToken + ":g" + generation;
	}

	private static String domain(int source, String scopeKey) {
		return "raid-time:v1:" + sourceName(source) + ":" + scopeKey + TIMER_UNCERTAINTY_SUFFIX;
	}

	private static boolean isKnownSource(int source) {
		return source == SOURCE_TOA || source == SOURCE_TFA || source == SOURCE_COX;
	}
}

package net.betterpartydefence;

import java.util.function.Supplier;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ScriptEvent;
import net.runelite.api.WorldView;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;

/**
 * Converts verified raid timer readings into a shared event clock.
 */
final class RaidTimerCoordinator
{
	private static final int COX_TIMER_STALE_TICKS = 4;

	private final Client client;
	private final DefenceTracker defenceTracker;
	private final Supplier<String> raidBegunScopeKey;
	private final RaidTimerClock clock = new RaidTimerClock();

	private boolean sharedRaidClockActive;
	private int sharedRaidStartTick;
	private int lastCoxTimerValue = Integer.MIN_VALUE;
	private int lastCoxTimerAdvanceTick = -1;
	private boolean coxTimerStale;

	RaidTimerCoordinator(Client client, DefenceTracker defenceTracker, Supplier<String> raidBegunScopeKey)
	{
		this.client = client;
		this.defenceTracker = defenceTracker;
		this.raidBegunScopeKey = raidBegunScopeKey;
	}

	void tick(int tick)
	{
		pollCoxTimer(tick);
		applySharedTickAnchor(tick);
	}

	void onChatMessage(ChatMessage event)
	{
		if (event == null || event.getType() != ChatMessageType.FRIENDSCHATNOTIFICATION
			|| client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) != 1)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		if (message == null)
		{
			return;
		}
		if (message.startsWith("The raid has begun!") && !sharedRaidClockActive)
		{
			sharedRaidStartTick = client.getTickCount();
			sharedRaidClockActive = true;
			updateFallbackTickAnchor(sharedRaidStartTick);
		}
		else if (message.startsWith("Congratulations - your raid is complete!"))
		{
			sharedRaidClockActive = false;
			if (clock.isActiveFor(RaidTimerClock.SOURCE_COX))
			{
				clock.clear();
			}
			defenceTracker.setSharedTickAnchor(null, 0);
		}
	}

	void onScriptPreFired(ScriptPreFired event)
	{
		if (event == null || RaidTimerClock.sourceForScript(event.getScriptId()) == -1)
		{
			return;
		}
		ScriptEvent scriptEvent = event.getScriptEvent();
		if (scriptEvent == null)
		{
			return;
		}
		RaidTimerClock.TimerInput input = RaidTimerClock.parseTimerScript(
			event.getScriptId(), scriptEvent.getArguments());
		if (input == null)
		{
			return;
		}

		int tick = client.getTickCount();
		if (input.elapsedTicks < 0)
		{
			if (clock.isActiveFor(input.source))
			{
				clock.clear();
			}
			applySharedTickAnchor(tick);
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null || !worldView.isInstance())
		{
			return;
		}
		String scope = timerScope(input.source, worldView);
		if (scope != null)
		{
			clock.sample(input.source, scope, input.elapsedTicks, input.stopped, tick);
		}
		applySharedTickAnchor(tick);
	}

	void pollCoxTimer(int tick)
	{
		int coxInRaid = client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON);
		int coxProgress = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PROGRESS);
		if (coxInRaid == 1 && coxProgress >= 1 && coxProgress < 5)
		{
			int elapsed = client.getVarbitValue(VarbitID.RAIDS_TIMER);
			if (elapsed != lastCoxTimerValue)
			{
				lastCoxTimerValue = elapsed;
				lastCoxTimerAdvanceTick = tick;
				coxTimerStale = false;
			}
			String scope = coxTimerScope(client.getTopLevelWorldView());
			if (clock.isActiveFor(RaidTimerClock.SOURCE_COX)
				&& lastCoxTimerAdvanceTick >= 0
				&& tick - lastCoxTimerAdvanceTick > COX_TIMER_STALE_TICKS)
			{
				clock.clear();
				coxTimerStale = true;
			}
			else if (!coxTimerStale && scope != null && elapsed >= 0
				&& (elapsed > 0 || sharedRaidClockActive))
			{
				clock.sample(RaidTimerClock.SOURCE_COX, scope, elapsed, false, tick);
			}
		}
		else if (coxInRaid == 1 && coxProgress >= 5)
		{
			if (clock.isActiveFor(RaidTimerClock.SOURCE_COX))
			{
				clock.markStopped();
			}
		}
		else
		{
			if (clock.isActiveFor(RaidTimerClock.SOURCE_COX))
			{
				clock.clear();
			}
			resetCoxTimer();
		}

		WorldView worldView = client.getTopLevelWorldView();
		boolean instance = worldView != null && worldView.isInstance();
		if (!instance)
		{
			if (clock.isActiveFor(RaidTimerClock.SOURCE_TOA))
			{
				clock.clear();
			}
			if (clock.isActiveFor(RaidTimerClock.SOURCE_TFA))
			{
				clock.clear();
			}
		}
	}

	void applySharedTickAnchor(int tick)
	{
		if (clock.isActive())
		{
			if (clock.isStopped())
			{
				defenceTracker.setSharedTickAnchor(null, 0);
			}
			else
			{
				defenceTracker.setSharedTickAnchor(
					clock.domain(), clock.anchorLocalTick(), clock.anchorRaidTick());
			}
			return;
		}
		updateFallbackTickAnchor(tick);
	}

	void updateFallbackTickAnchor(int tick)
	{
		if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) != 1)
		{
			sharedRaidClockActive = false;
		}
		if (!sharedRaidClockActive)
		{
			defenceTracker.setSharedTickAnchor(null, 0);
			return;
		}

		String scope = raidBegunScopeKey.get();
		if (scope == null)
		{
			defenceTracker.setSharedTickAnchor(null, 0);
			return;
		}
		defenceTracker.setSharedTickAnchor("raid-begun:v2:cox:" + scope, sharedRaidStartTick);
	}

	void clear()
	{
		sharedRaidClockActive = false;
		clock.clear();
		resetCoxTimer();
		defenceTracker.setSharedTickAnchor(null, 0);
	}

	boolean isActiveFor(int source)
	{
		return clock.isActiveFor(source);
	}

	long tickAt(int localTick)
	{
		return clock.tickAt(localTick);
	}

	String timerScope(int source, WorldView worldView)
	{
		if (source == RaidTimerClock.SOURCE_TFA)
		{
			int controller = client.getVarpValue(VarPlayerID.TFA_MYCONTROLLER);
			return controller > 0 ? "c" + controller : null;
		}
		if (source == RaidTimerClock.SOURCE_TOA)
		{
			int controller = client.getVarpValue(VarPlayerID.TOA_MYCONTROLLER);
			if (controller > 0)
			{
				return "c" + controller;
			}
			return worldView != null && worldView.isInstance()
				? "i" + EncounterScopes.instanceFingerprint(worldView)
				: null;
		}
		return null;
	}

	private String coxTimerScope(WorldView worldView)
	{
		if (worldView != null && worldView.isInstance())
		{
			return "i" + EncounterScopes.instanceFingerprint(worldView);
		}
		int controller = client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER);
		return controller > 0 ? "c" + controller : null;
	}

	private void resetCoxTimer()
	{
		lastCoxTimerValue = Integer.MIN_VALUE;
		lastCoxTimerAdvanceTick = -1;
		coxTimerStale = false;
	}
}

package net.betterpartydefence;

import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Map;

// Ignore one duplicate party message for each adopted snapshot row.
final class SnapshotEchoGuard<K> {
	private final Map<K, ArrayDeque<Integer>> credits = new HashMap<>();
	private final int ttl;

	SnapshotEchoGuard(int ttl) {
		this.ttl = ttl;
	}

	void add(K key, int tick) {
		credits.computeIfAbsent(key, ignored -> new ArrayDeque<>()).addLast(tick);
	}

	boolean consume(K key, int tick) {
		prune(tick);
		ArrayDeque<Integer> queue = credits.get(key);
		if (queue == null) {
			return false;
		}
		queue.removeFirst();
		if (queue.isEmpty()) {
			credits.remove(key);
		}
		return true;
	}

	void prune(int tick) {
		credits.entrySet().removeIf(entry -> {
			ArrayDeque<Integer> queue = entry.getValue();
			while (!queue.isEmpty() && (tick < queue.peekFirst() || tick - queue.peekFirst() > ttl)) {
				queue.removeFirst();
			}
			return queue.isEmpty();
		});
	}

	void clear() {
		credits.clear();
	}
}

