package net.betterpartydefence;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * Resolves tracked bosses from local NPCs using stable actor and location evidence.
 */
final class TargetResolver
{
	private TargetResolver()
	{
	}

	static List<NPC> liveCandidates(WorldView worldView, BossDefence boss)
	{
		if (worldView == null || worldView.npcs() == null || boss == null)
		{
			return Collections.emptyList();
		}

		List<NPC> candidates = new ArrayList<>();
		Iterator<? extends NPC> iterator = worldView.npcs().iterator();
		while (iterator != null && iterator.hasNext())
		{
			NPC npc = iterator.next();
			if (BossDefence.isLiveNpc(npc) && npc.getName() != null
				&& BossDefence.matchingNpc(npc) == boss)
			{
				candidates.add(npc);
			}
		}
		return candidates;
	}

	static NPC uniqueLiveNpc(WorldView worldView, BossDefence boss)
	{
		return unique(liveCandidates(worldView, boss));
	}

	static NPC uniqueLiveNpcNear(
		WorldView worldView, BossDefence boss, int x, int y, int plane, int tolerance)
	{
		if (x == 0 && y == 0)
		{
			return null;
		}

		return uniqueCandidateAt(worldView, boss, -1, x, y, plane, tolerance);
	}

	static NPC uniqueLiveNpcFor(
		WorldView worldView, BossDefence boss, int npcId, WorldPoint lastLocation, int tolerance)
	{
		if (npcId < 0 || lastLocation == null)
		{
			return null;
		}
		return uniqueCandidateAt(worldView, boss, npcId,
			lastLocation.getX(), lastLocation.getY(), lastLocation.getPlane(), tolerance);
	}

	// A negative NPC id means the sender has only location evidence.
	private static NPC uniqueCandidateAt(
		WorldView worldView, BossDefence boss, int npcId, int x, int y, int plane, int tolerance)
	{
		NPC match = null;
		for (NPC npc : liveCandidates(worldView, boss))
		{
			if (npcId >= 0 && npc.getId() != npcId)
			{
				continue;
			}
			if (!isNear(npc.getWorldLocation(), x, y, plane, tolerance))
			{
				continue;
			}
			if (match != null)
			{
				return null;
			}
			match = npc;
		}
		return match;
	}

	static boolean matches(
		NPC npc, BossDefence boss, int npcId, WorldPoint lastLocation, int tolerance)
	{
		if (npc == null || boss == null || BossDefence.matchingNpc(npc) != boss || npc.getId() != npcId)
		{
			return false;
		}
		WorldPoint point = npc.getWorldLocation();
		if (lastLocation == null)
		{
			return true;
		}
		return isNear(point, lastLocation, tolerance);
	}

	private static boolean isNear(WorldPoint point, WorldPoint target, int tolerance)
	{
		return point != null && isNear(point, target.getX(), target.getY(), target.getPlane(), tolerance);
	}

	private static boolean isNear(WorldPoint point, int x, int y, int plane, int tolerance)
	{
		return point != null && point.getPlane() == plane
			&& Math.abs(point.getX() - x) <= tolerance
			&& Math.abs(point.getY() - y) <= tolerance;
	}

	private static NPC unique(List<NPC> candidates)
	{
		return candidates.size() == 1 ? candidates.get(0) : null;
	}
}

package net.betterpartydefence;

import java.util.function.BiPredicate;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;

// Tracks TFA runs while room and actor transitions replace scene NPCs.
@Slf4j
final class TfaEncounterCoordinator {
	private final Client client;
	private final DefenceTracker tracker;
	private final BiPredicate<BossDefence, String> resetEncounter;
	private final Runnable clearDisplay;
	private final Runnable clearDisplayGates;

	private boolean phaseOneEnded;

	TfaEncounterCoordinator(Client client, DefenceTracker tracker,
			BiPredicate<BossDefence, String> resetEncounter,
			Runnable clearDisplay, Runnable clearDisplayGates) {
		this.client = client;
		this.tracker = tracker;
		this.resetEncounter = resetEncounter;
		this.clearDisplay = clearDisplay;
		this.clearDisplayGates = clearDisplayGates;
	}

	void onGameTick() {
		reconcileRaidExit();
		reconcilePhaseChange();
	}

	void onNpcSpawned(NPC npc) {
		if (BossDefence.matchingNpc(npc) != BossDefence.TFA_ARCHIVE_GUARDIAN) {
			return;
		}
		if (phaseOneEnded) {
			clearAll("new TFA attempt at Archive Guardian");
			return;
		}
		for (BossDefence boss : BossDefence.values()) {
			if (EncounterScopes.isTfaBoss(boss) && boss != BossDefence.TFA_ARCHIVE_GUARDIAN
					&& tracker.hasRememberedState(boss)) {
				clearAll("fresh TFA run started at Archive Guardian");
				return;
			}
		}
	}

	boolean phaseOneEnded() {
		return phaseOneEnded;
	}

	void reset() {
		phaseOneEnded = false;
	}

	// TFA can unload NPCs during movement without ending the raid.
	private void reconcileRaidExit() {
		WorldView world = client.getTopLevelWorldView();
		if (world == null || world.isInstance()) {
			return;
		}
		clearAll("left The Fractured Archive instance");
	}

	// Ocellus phase 2 uses its own defence pool.
	// Do not carry phase 1 values into the Blade phase.
	private void reconcilePhaseChange() {
		WorldView world = client.getTopLevelWorldView();
		if (world == null || !world.isInstance()) {
			return;
		}

		TfaEncounterMechanics.PhasePresence phase = TfaEncounterMechanics.scan(world);
		if (phase.hasLeftPhaseOne() && !phaseOneEnded) {
			phaseOneEnded = true;
			// Clear old boxes on the transition tick.
			clearDisplay.run();
		}
		if (phaseOneEnded && tracker.hasRememberedState(BossDefence.TFA_OCELLUS_P1)) {
			applyReset(BossDefence.TFA_OCELLUS_P1, "Ocellus left Phase 1");
		}
		// P3 starts from its own baseline.
		// Reset only when the P3 boss NPC appears.
		if (phase.phaseThree && tracker.hasRememberedState(BossDefence.TFA_OCELLUS_P2)) {
			applyReset(BossDefence.TFA_OCELLUS_P2, "The Blade left Phase 2");
		}
	}

	private void clearAll(String reason) {
		phaseOneEnded = false;
		boolean changed = false;
		for (BossDefence boss : BossDefence.values()) {
			if (EncounterScopes.isTfaBoss(boss) && tracker.hasRememberedState(boss)) {
				applyReset(boss, reason);
				changed = true;
			}
		}
		if (changed) {
			clearDisplay.run();
			clearDisplayGates.run();
			log.debug("Cleared TFA raid: {}", reason);
		}
	}

	private void applyReset(BossDefence boss, String reason) {
		resetEncounter.test(boss, reason);
	}
}

package net.betterpartydefence;

import java.util.Iterator;
import net.betterpartydefence.boss.OcellusActors;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;

// The Fractured Archive actor transitions that affect encounter ownership.
final class TfaEncounterMechanics {
	private TfaEncounterMechanics() {
	}

	static PhasePresence scan(WorldView world) {
		boolean phaseThree = world != null
				&& TargetResolver.uniqueLiveNpc(world, BossDefence.TFA_OCELLUS_P3) != null;
		boolean phaseTwo = false;
		boolean phaseOneDefeated = false;
		if (world != null && world.npcs() != null) {
			Iterator<? extends NPC> iterator = world.npcs().iterator();
			while (iterator != null && iterator.hasNext()) {
				NPC npc = iterator.next();
				phaseTwo |= isOcellusPhaseTwoActor(npc);
				phaseOneDefeated |= isOcellusPhaseOneDefeated(npc);
			}
		}
		return new PhasePresence(phaseTwo, phaseThree, phaseOneDefeated);
	}

	static boolean isOcellusPhaseTwoActor(NPC npc) {
		return OcellusActors.marksPhaseTwo(npc);
	}

	static boolean isOcellusPhaseOneDefeated(NPC npc) {
		return OcellusActors.isPhaseOneDefeated(npc);
	}

	static final class PhasePresence {
		final boolean phaseTwo;
		final boolean phaseThree;
		final boolean phaseOneDefeated;

		private PhasePresence(boolean phaseTwo, boolean phaseThree, boolean phaseOneDefeated) {
			this.phaseTwo = phaseTwo;
			this.phaseThree = phaseThree;
			this.phaseOneDefeated = phaseOneDefeated;
		}

		boolean hasLeftPhaseOne() {
			return phaseTwo || phaseThree || phaseOneDefeated;
		}
	}
}

package net.betterpartydefence;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.VarbitID;

// Applies one reset when every occupied ToA party orb is dead.
final class ToaEncounterCoordinator {
	private static final int PARTY_MEMBER_DEAD = 30;
	private static final int[] PARTY_HEALTH_VARBITS = {
			VarbitID.TOA_CLIENT_P0, VarbitID.TOA_CLIENT_P1, VarbitID.TOA_CLIENT_P2, VarbitID.TOA_CLIENT_P3,
			VarbitID.TOA_CLIENT_P4, VarbitID.TOA_CLIENT_P5, VarbitID.TOA_CLIENT_P6, VarbitID.TOA_CLIENT_P7
	};

	private final Client client;
	private final DefenceTracker tracker;
	private final Consumer<BossDefence> resetEncounter;
	private boolean partyWasFullyDead;

	ToaEncounterCoordinator(Client client, DefenceTracker tracker, Consumer<BossDefence> resetEncounter) {
		this.client = client;
		this.tracker = tracker;
		this.resetEncounter = resetEncounter;
	}

	void onGameTick() {
		List<BossDefence> remembered = rememberedBosses();
		if (!isPartyFullyDead()) {
			partyWasFullyDead = false;
			return;
		}
		if (partyWasFullyDead || remembered.isEmpty()) {
			partyWasFullyDead = true;
			return;
		}

		partyWasFullyDead = true;
		for (BossDefence boss : remembered) {
			resetEncounter.accept(boss);
		}
	}

	void reset() {
		partyWasFullyDead = false;
	}

	private List<BossDefence> rememberedBosses() {
		List<BossDefence> bosses = new ArrayList<>();
		for (BossDefence boss : BossDefence.values()) {
			if (EncounterScopes.isToaBoss(boss) && tracker.hasRememberedState(boss)) {
				bosses.add(boss);
			}
		}
		return bosses;
	}

	private boolean isPartyFullyDead() {
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null || !worldView.isInstance()) {
			return false;
		}

		boolean anyOccupiedSlot = false;
		for (int varbit : PARTY_HEALTH_VARBITS) {
			int health = client.getVarbitValue(varbit);
			if (health == 0) {
				continue;
			}
			anyOccupiedSlot = true;
			if (health != PARTY_MEMBER_DEAD) {
				return false;
			}
		}
		return anyOccupiedSlot;
	}
}

package net.betterpartydefence.boss;

import net.betterpartydefence.BossDefence;
import net.runelite.api.gameval.NpcID;

// Encounter lifetime rules that do not belong in the boss stat catalogue.
public enum BossLifecycle {
	STANDARD(false),
	TEKTON(true),
	DREADNOTH(true),
	KEPHRI(true) {
		@Override
		public boolean preserveStateAtZeroHp(int npcId) {
			// Shielded and weak Kephri can sit at zero HP mid-encounter.
			return npcId == NpcID.TOA_KEPHRI_BOSS_SHIELDED
					|| npcId == NpcID.TOA_KEPHRI_BOSS_WEAK;
		}

		@Override
		public boolean resetsStatsOnActorEntry(int npcId) {
			return npcId == NpcID.TOA_KEPHRI_BOSS_ENRAGE;
		}

		@Override
		public boolean endsEncounterOnActorEntry(int npcId) {
			return npcId == NpcID.TOA_KEPHRI_BOSS_DEAD;
		}
	},
	SOTETSEG(true),
	TFA_PHASE_PERSISTENT(true) {
		@Override
		public boolean preserveStateAtZeroHp(int npcId) {
			return true;
		}
	};

	private final boolean phasePersistent;

	BossLifecycle(boolean phasePersistent) {
		this.phasePersistent = phasePersistent;
	}

	public boolean isPhasePersistent() {
		return phasePersistent;
	}

	public boolean preserveStateAtZeroHp(int npcId) {
		return false;
	}

	public boolean resetsStatsOnActorEntry(int npcId) {
		return false;
	}

	public boolean endsEncounterOnActorEntry(int npcId) {
		return false;
	}

	public static BossLifecycle forBoss(BossDefence boss) {
		if (boss == null) {
			return STANDARD;
		}
		switch (boss.trackingType()) {
			case TEKTON:
				return TEKTON;
			case TFA_DREADNOTH:
				return DREADNOTH;
			case KEPHRI:
				return KEPHRI;
			case SOTETSEG:
				return SOTETSEG;
			case TFA_ARCHIVE_GUARDIAN:
			case TFA_XARTH:
			case TFA_OCELLUS_P1:
			case TFA_OCELLUS_P2:
			case TFA_OCELLUS_P3:
				return TFA_PHASE_PERSISTENT;
			default:
				return STANDARD;
		}
	}
}

package net.betterpartydefence.boss;

import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import net.betterpartydefence.BossDefence;
import net.runelite.api.NPC;
import net.runelite.client.util.Text;

/**
 * Maps RuneLite NPC actors to their stable boss-stat definition.
 */
public final class BossNpcMatcher {
	private static final int DAGONHAI_MONK_FIRST_ACTOR = 16645;
	private static final int DAGONHAI_MONK_SECOND_ACTOR = 16646;

	private static final Map<BossDefence, String> NORMALIZED_NAMES = buildNormalizedNames();

	private BossNpcMatcher() {
	}

	public static BossDefence matchingNpc(NPC npc) {
		if (npc == null) {
			return null;
		}
		if (OcellusActors.isAttackablePhaseTwo(npc)) {
			return BossDefence.TFA_OCELLUS_P2;
		}
		if (npc.getName() == null) {
			return null;
		}

		String name = normalize(npc.getName());
		if ("Dagon'hai Monk".equalsIgnoreCase(name)) {
			if (npc.getId() == DAGONHAI_MONK_FIRST_ACTOR) {
				return BossDefence.TFA_DAGONHAI_MONK_16645;
			}
			if (npc.getId() == DAGONHAI_MONK_SECOND_ACTOR) {
				return BossDefence.TFA_DAGONHAI_MONK_16646;
			}
			return null;
		}
		if (OcellusActors.isBladeName(name)) {
			return null;
		}
		if (OcellusActors.isOcellusName(name)) {
			return OcellusActors.matchingOcellus(npc);
		}
		return matchingNpcName(name);
	}

	public static BossDefence matchingNpcName(String name) {
		if (name == null || name.trim().isEmpty()) {
			return null;
		}

		String normalized = normalize(name);
		if (OcellusActors.isBladeName(normalized)) {
			return null;
		}

		BossDefence prefixMatch = null;
		for (Map.Entry<BossDefence, String> entry : NORMALIZED_NAMES.entrySet()) {
			BossDefence boss = entry.getKey();
			if (boss == BossDefence.TFA_DREADNOTH && isDreadnothJellied(normalized)) {
				return boss;
			}

			String candidate = entry.getValue();
			if (candidate.equalsIgnoreCase(normalized)) {
				return boss.trackingType();
			}
			if (prefixMatch == null
				&& normalized.regionMatches(true, 0, candidate, 0, candidate.length())
				&& normalized.length() > candidate.length()
				&& normalized.charAt(candidate.length()) == ' ') {
				prefixMatch = boss;
			}
		}
		return prefixMatch == null ? null : prefixMatch.trackingType();
	}

	public static boolean isAttackableOcellusPhaseTwo(NPC npc) {
		return OcellusActors.isAttackablePhaseTwo(npc);
	}

	public static boolean isLiveNpc(NPC npc) {
		return npc != null && !npc.isDead()
			&& (npc.getHealthRatio() != 0 || isAttackableOcellusPhaseTwo(npc));
	}

	private static boolean isDreadnothJellied(String name) {
		String normalized = name.toLowerCase(Locale.ROOT);
		return normalized.contains("dreadnoth") && normalized.contains("jellied");
	}

	private static String normalize(String name) {
		return Text.removeTags(name).trim();
	}

	private static Map<BossDefence, String> buildNormalizedNames() {
		Map<BossDefence, String> names = new EnumMap<>(BossDefence.class);
		for (BossDefence boss : BossDefence.values()) {
			names.put(boss, normalize(boss.getNpcName()));
		}
		return names;
	}
}

package net.betterpartydefence.boss;

import net.betterpartydefence.BossDefence;
import net.runelite.api.NPC;
import net.runelite.client.util.Text;

// Ocellus actor identity is separate from encounter lifecycle and base stats.
public final class OcellusActors {
	private static final int PHASE_ONE_ACTOR = 16673;
	private static final int PHASE_ONE_ALT_ACTOR = 16674;
	private static final int TRANSITION_ACTOR = 16675;
	private static final int PHASE_TWO_ACTOR = 16676;
	private static final int BLADE_PROP = 16683;
	private static final int PHASE_THREE_COMBAT_LEVEL = 1197;
	private static final int PHASE_THREE_ALT_COMBAT_LEVEL = 1601;
	private static final String OCELLUS_NAME = "Ocellus";
	private static final String BLADE_NAME = "The Blade";

	private OcellusActors() {
	}

	// Only this actor owns the P2 defence pool, regardless of its name.
	public static boolean isAttackablePhaseTwo(NPC npc) {
		return npc != null && npc.getId() == PHASE_TWO_ACTOR;
	}

	static boolean isOcellusName(String name) {
		return OCELLUS_NAME.equalsIgnoreCase(name);
	}

	static boolean isBladeName(String name) {
		return BLADE_NAME.equalsIgnoreCase(name);
	}

	static BossDefence matchingOcellus(NPC npc) {
		if (npc.getId() == TRANSITION_ACTOR) {
			return null;
		}
		if (npc.getCombatLevel() == PHASE_THREE_COMBAT_LEVEL
				|| npc.getCombatLevel() == PHASE_THREE_ALT_COMBAT_LEVEL) {
			return BossDefence.TFA_OCELLUS_P3;
		}
		return isPhaseOneId(npc.getId()) ? BossDefence.TFA_OCELLUS_P1 : null;
	}

	// Props mark the phase boundary but never own defence state.
	public static boolean marksPhaseTwo(NPC npc) {
		if (npc == null) {
			return false;
		}
		if (isAttackablePhaseTwo(npc)) {
			return true;
		}
		if (npc.getName() == null) {
			return false;
		}
		String name = Text.removeTags(npc.getName()).trim();
		return (isOcellusName(name) && npc.getId() == TRANSITION_ACTOR)
				|| (isBladeName(name) && npc.getId() == BLADE_PROP);
	}

	// Seeing P1 at zero health ends P1 even if the NPC disappears.
	public static boolean isPhaseOneDefeated(NPC npc) {
		return npc != null && npc.getName() != null
				&& isOcellusName(Text.removeTags(npc.getName()).trim())
				&& isPhaseOneId(npc.getId())
				&& (npc.isDead() || npc.getHealthRatio() == 0);
	}

	private static boolean isPhaseOneId(int npcId) {
		return npcId == PHASE_ONE_ACTOR || npcId == PHASE_ONE_ALT_ACTOR;
	}
}

package net.betterpartydefence;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.specialcounter.SpecialCounterUpdate;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import org.junit.Before;
import org.junit.Test;

/**
 * Regression coverage for the observed TFA Archive Guardian Ralos rejection. The test models a fresh sender heartbeat
 * whose scope differs from the receiver's while both players and one unambiguous opponent are present in the local
 * world view.
 */
public class ArchiveGuardianScopeRegressionTest {
	private static final int WORLD = 474;
	private static final int NPC_INDEX = 55828;
	private static final int SENDER_PLAYER_ID = 1733;
	private static final long SENDER_MEMBER_ID = 7L;

	private BetterPartyDefencePlugin plugin;
	private DefenceTracker tracker;
	private Client client;
	private WorldView worldView;
	private IndexedObjectSet<NPC> npcs;
	private IndexedObjectSet<Player> players;
	private NPC guardian;
	private Player sender;
	private PartyService party;
	private PartyMember senderMember;

	@Before
	@SuppressWarnings("unchecked")
	public void setUp() throws Exception {
		client = mock(Client.class);
		worldView = mock(WorldView.class);
		npcs = mock(IndexedObjectSet.class);
		players = mock(IndexedObjectSet.class);
		guardian = mock(NPC.class);
		sender = mock(Player.class);
		party = mock(PartyService.class);
		senderMember = mock(PartyMember.class);

		when(client.getWorld()).thenReturn(WORLD);
		when(client.getTickCount()).thenReturn(100);
		when(client.getTopLevelWorldView()).thenReturn(worldView);
		when(worldView.isInstance()).thenReturn(true);
		doReturn(npcs).when(worldView).npcs();
		doReturn(players).when(worldView).players();

		when(guardian.getName()).thenReturn("Archive Guardian");
		when(guardian.getIndex()).thenReturn(NPC_INDEX);
		when(guardian.getId()).thenReturn(0);
		when(guardian.getHealthRatio()).thenReturn(1);
		when(guardian.getHealthScale()).thenReturn(1);
		when(guardian.getWorldLocation()).thenReturn(new WorldPoint(0, 0, 0));
		when(npcs.byIndex(NPC_INDEX)).thenReturn(guardian);
		when(npcs.iterator()).thenAnswer(invocation -> Collections.singletonList(guardian).iterator());

		when(sender.getId()).thenReturn(SENDER_PLAYER_ID);
		when(players.iterator()).thenAnswer(invocation -> Collections.singletonList(sender).iterator());

		when(party.isInParty()).thenReturn(true);
		when(party.getMemberById(SENDER_MEMBER_ID)).thenReturn(senderMember);
		when(senderMember.getDisplayName()).thenReturn("RalosPlayer");

		BetterPartyDefenceConfig config = mock(BetterPartyDefenceConfig.class);
		tracker = new DefenceTracker(client, config);

		ClientThread clientThread = mock(ClientThread.class);
		doAnswer(invocation -> {
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));

		plugin = new BetterPartyDefencePlugin();
		setPluginField("client", client);
		setPluginField("config", config);
		setPluginField("defenceTracker", tracker);
		setPluginField("partyService", party);
		setPluginField("clientThread", clientThread);
	}

	@Test
	public void archiveGuardianRalosAcceptedDespiteDifferentScopeWhenTargetEvidenceMatches() throws Exception {
		rememberSenderScope(instanceFingerprint() + 1);

		deliverRalos();
		tracker.onGameTick();

		assertEquals("the current encounter target must not be discarded solely on scope mismatch",
				1, tracker.specHistory().size());
		assertEquals(SpecialWeapon.TONALZTICS_OF_RALOS,
				tracker.specHistory().get(0).getWeapon());
		assertEquals(BossDefence.TFA_ARCHIVE_GUARDIAN, tracker.trackedBossType());
	}

	@Test
	public void scopeMismatchAcceptedWhenSenderIsNotRenderedButTargetIsUnique() throws Exception {
		when(players.iterator()).thenAnswer(invocation -> Collections.emptyIterator());
		rememberSenderScope(instanceFingerprint() + 1);

		deliverRalos();
		tracker.onGameTick();

		assertEquals("sender rendering is not evidence about the combat target",
				1, tracker.specHistory().size());
		assertEquals(BossDefence.TFA_ARCHIVE_GUARDIAN, tracker.trackedBossType());
	}

	@Test
	public void scopeMismatchStillRejectedWhenTargetIsAmbiguous() throws Exception {
		NPC secondGuardian = mock(NPC.class);
		when(secondGuardian.getName()).thenReturn("Archive Guardian");
		when(secondGuardian.getIndex()).thenReturn(NPC_INDEX + 1);
		when(secondGuardian.getHealthRatio()).thenReturn(1);
		when(npcs.iterator()).thenAnswer(invocation -> Arrays.asList(guardian, secondGuardian).iterator());
		rememberSenderScope(instanceFingerprint() + 1);

		deliverRalos();
		tracker.onGameTick();

		assertTrue("two live same-type targets cannot be resolved by the sender hint",
				tracker.specHistory().isEmpty());
		assertNull(tracker.state());
	}

	@Test
	public void scopeMismatchStillRejectedWhenEventTargetIsUnidentified() throws Exception {
		when(npcs.byIndex(NPC_INDEX)).thenReturn(null);
		rememberSenderScope(instanceFingerprint() + 1);

		deliverRalos();
		tracker.onGameTick();

		assertTrue("an unknown local NPC index is not sufficient target evidence",
				tracker.specHistory().isEmpty());
		assertNull(tracker.state());
	}

	private void deliverRalos() {
		SpecialCounterUpdate packet = new SpecialCounterUpdate(
				NPC_INDEX, SpecialWeapon.TONALZTICS_OF_RALOS, 2, WORLD, SENDER_PLAYER_ID);
		packet.setMemberId(SENDER_MEMBER_ID);
		plugin.onSpecialCounterUpdate(packet);
	}

	private void rememberSenderScope(int scopeId) throws Exception {
		Method remember = BetterPartyDefencePlugin.class.getDeclaredMethod(
				"rememberSenderEncounterPresence",
				long.class, int.class, int.class, int.class, long.class);
		remember.setAccessible(true);
		remember.invoke(plugin, SENDER_MEMBER_ID, WORLD,
				BpdDefenceSync.SCOPE_INSTANCE, scopeId, System.currentTimeMillis());
	}

	private int instanceFingerprint() throws Exception {
		Method method = BetterPartyDefencePlugin.class.getDeclaredMethod(
				"instanceFingerprint", WorldView.class);
		method.setAccessible(true);
		return (int) method.invoke(null, worldView);
	}

	private void setPluginField(String name, Object value) throws Exception {
		Field field = BetterPartyDefencePlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}
}

package net.betterpartydefence;

import org.junit.Test;
import static org.junit.Assert.*;

public class AuditEpochIsolationRegressionTest {
	private RaidTimerClock isolated() {
		RaidTimerClock clock = new RaidTimerClock();
		assertTrue(clock.sample(RaidTimerClock.SOURCE_TOA, "c77", 500, false, 1000));
		assertFalse(clock.sample(RaidTimerClock.SOURCE_TOA, "c77", 10, false, 1004));
		assertFalse(clock.isActive());
		assertTrue(clock.sample(RaidTimerClock.SOURCE_TOA, "c77", 11, false, 1005));
		return clock;
	}

	@Test
	public void ordinaryResampleMustNotRejoinPreCorrectionDomain() {
		RaidTimerClock clock = isolated();
		String isolatedDomain = clock.domain();
		assertTrue(isolatedDomain.endsWith(":g1"));
		assertTrue(clock.sample(RaidTimerClock.SOURCE_TOA, "c77", 12, false, 1006));
		assertEquals("Normal timer updates must preserve the isolated epoch", isolatedDomain, clock.domain());
	}

	@Test
	public void isolatedEpochMustRetainAdvertisedUncertainty() {
		RaidTimerClock clock = isolated();
		assertEquals("Appending generation must not turn an uncertain timer into an exact clock",
				RaidTimerClock.TIMER_UNCERTAINTY_TICKS, EncounterTimeline.tickUncertainty(clock.domain()));
	}

	@Test
	public void separateAmbiguousResetsMustNotReuseTheSameEpoch() {
		RaidTimerClock clock = isolated();
		String firstEpoch = clock.domain();
		assertFalse(clock.sample(RaidTimerClock.SOURCE_TOA, "c77", 3, false, 1010));
		assertTrue(clock.sample(RaidTimerClock.SOURCE_TOA, "c77", 4, false, 1011));
		assertNotEquals("Two incompatible mappings cannot reuse the same epoch domain", firstEpoch, clock.domain());
	}
}

package net.betterpartydefence;

import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.Test;
import static org.junit.Assert.*;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

public class AuditFollowupRegressionTest {
	private SpecHistoryEntry event(String id, String domain, long tick, SpecialWeapon weapon, int hit) {
		return new SpecHistoryEntry(id, weapon, hit, id, domain, tick);
	}

	private EncounterTimeline.Replay<Integer> corp() {
		return new EncounterTimeline.Replay<Integer>() {
			public Integer apply(Integer defence, SpecHistoryEntry e) {
				return e.getWeapon() == SpecialWeapon.DRAGON_WARHAMMER
						? defence - defence * 30 / 100
						: Math.max(0, defence - e.getHit() * 2);
			}
			public Integer conservative(Integer a, Integer b) {
				return Math.max(a, b);
			}
		};
	}

	@Test
	public void ignoredCorrectionMustNotForceSimultaneousClientsIntoExactOrder() {
		RaidTimerClock continuing = new RaidTimerClock();
		RaidTimerClock joining = new RaidTimerClock();
		continuing.sample(RaidTimerClock.SOURCE_TOA, "c77", 100, false, 1000);
		// Both now receive raid100 at the same actual game tick. One client has history,
		// the other establishes its mapping from the corrected sample.
		continuing.sample(RaidTimerClock.SOURCE_TOA, "c77", 100, false, 1002);
		joining.sample(RaidTimerClock.SOURCE_TOA, "c77", 100, false, 5000);
		assertEquals(continuing.domain(), joining.domain());
		List<SpecHistoryEntry> sameTick = Arrays.asList(
				event("bgs", continuing.domain(), continuing.tickAt(1002), SpecialWeapon.BANDOS_GODSWORD, 20),
				event("dwh", joining.domain(), joining.tickAt(5000), SpecialWeapon.DRAGON_WARHAMMER, 1));
		assertEquals("Same-tick specs must retain the smallest-drain bound after a correction",
				Integer.valueOf(189), EncounterTimeline.replay(sameTick, 310, corp()));
	}

	@Test
	public void largerCorrectionMustNotReverseEarlierImmutableEvents() {
		RaidTimerClock clock = new RaidTimerClock();
		clock.sample(RaidTimerClock.SOURCE_TOA, "c77", 100, false, 1000);
		SpecHistoryEntry first = event("bgs", clock.domain(), clock.tickAt(1001), SpecialWeapon.BANDOS_GODSWORD, 20);
		clock.sample(RaidTimerClock.SOURCE_TOA, "c77", 100, false, 1004);
		SpecHistoryEntry second = event("dwh", clock.domain(), clock.tickAt(1004), SpecialWeapon.DRAGON_WARHAMMER, 1);
		assertFalse("A larger backward sample cannot reuse an exact domain and reverse old events",
				EncounterTimeline.before(second, first));
	}

	@Test
	public void scopeTransitionMustNotBeLostWhenSampleIsSlightlyBehind() {
		RaidTimerClock continuing = new RaidTimerClock();
		RaidTimerClock joining = new RaidTimerClock();
		continuing.sample(RaidTimerClock.SOURCE_TOA, "i111", 100, false, 1000);
		continuing.sample(RaidTimerClock.SOURCE_TOA, "c77", 109, false, 1010);
		joining.sample(RaidTimerClock.SOURCE_TOA, "c77", 109, false, 5000);
		assertEquals("The old scene fallback must not stick after a controller becomes available",
				joining.domain(), continuing.domain());
	}

	@Test
	public void successorAwarePruningMatchesFullSearchAcrossClockLayouts() {
		Random random = new Random(627);
		for (int trial = 0; trial < 256; trial++) {
			List<SpecHistoryEntry> events = new ArrayList<>();
			for (int i = 0; i < 6; i++) {
				SpecialWeapon weapon = random.nextBoolean()
						? SpecialWeapon.DRAGON_WARHAMMER
						: SpecialWeapon.BANDOS_GODSWORD;
				events.add(event("e" + i, "clock" + random.nextInt(3), random.nextInt(3), weapon,
						weapon == SpecialWeapon.DRAGON_WARHAMMER ? 1 : 10 + 10 * random.nextInt(3)));
			}
			assertEquals("Trial " + trial, EncounterTimeline.replay(events, 310, corp()),
					EncounterTimeline.replay(events, 310, corp(), e -> e.getWeapon().name() + ":" + e.getHit()));
		}
	}
}

package net.betterpartydefence;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

public class AuditRegressionTest {
	private SpecHistoryEntry event(String id, String clock, long tick, SpecialWeapon weapon, int hit) {
		return new SpecHistoryEntry(id, weapon, hit, id, clock, tick);
	}

	private EncounterTimeline.Replay<Integer> corp() {
		return new EncounterTimeline.Replay<Integer>() {
			public Integer apply(Integer defence, SpecHistoryEntry event) {
				if (event.getWeapon() == SpecialWeapon.DRAGON_WARHAMMER)
					return defence - defence * 30 / 100;
				return Math.max(0, defence - event.getHit() * 2);
			}
			public Integer conservative(Integer a, Integer b) {
				return Math.max(a, b);
			}
		};
	}

	@Test
	public void equivalentEffectsWithDifferentSuccessorsMustNotLoseLegalOrder() {
		List<SpecHistoryEntry> events = Arrays.asList(
				event("a", "clock-a", 0, SpecialWeapon.DRAGON_WARHAMMER, 1),
				event("c", "clock-a", 1, SpecialWeapon.BANDOS_GODSWORD, 20),
				event("b", "clock-b", 0, SpecialWeapon.DRAGON_WARHAMMER, 1),
				event("d", "clock-b", 1, SpecialWeapon.BANDOS_GODSWORD, 50));
		Integer exhaustive = EncounterTimeline.replay(events, 310, corp());
		assertEquals(Integer.valueOf(42), exhaustive);
		Integer optimized = EncounterTimeline.replay(events, 310, corp(),
				e -> e.getWeapon().name() + ":" + e.getHit());
		assertEquals("Optimization must preserve the highest Defence legal order", exhaustive, optimized);
	}

	@Test
	public void smallBackwardCorrectionMustNotReverseAcceptedLocalChronology() {
		RaidTimerClock clock = new RaidTimerClock();
		clock.sample(RaidTimerClock.SOURCE_TOA, "i1", 100, false, 1000);
		String domain = clock.domain();
		SpecHistoryEntry earlier = event("bgs", domain, clock.tickAt(1001), SpecialWeapon.BANDOS_GODSWORD, 20);
		clock.sample(RaidTimerClock.SOURCE_TOA, "i1", 100, false, 1002);
		SpecHistoryEntry later = event("dwh", clock.domain(), clock.tickAt(1002), SpecialWeapon.DRAGON_WARHAMMER, 1);
		assertFalse("A later local observation cannot precede an already accepted event",
				EncounterTimeline.before(later, earlier));
	}

	@Test
	public void lateJoinInCurrentRoomMustShareDomainWithContinuingClient() {
		RaidTimerClock continuing = new RaidTimerClock();
		RaidTimerClock joining = new RaidTimerClock();
		continuing.sample(RaidTimerClock.SOURCE_TOA, "i111", 100, false, 1000);
		continuing.sample(RaidTimerClock.SOURCE_TOA, "i222", 200, false, 1100);
		joining.sample(RaidTimerClock.SOURCE_TOA, "i222", 200, false, 5000);
		assertEquals(continuing.tickAt(1100), joining.tickAt(5000));
		assertEquals("Same raid/room time must use a comparable domain", continuing.domain(), joining.domain());
	}

	@Test
	public void coxOneTickSamplingUncertaintyMustNotForceSameTickAttacksIntoOrder() {
		RaidTimerClock alice = new RaidTimerClock();
		RaidTimerClock bob = new RaidTimerClock();
		alice.sample(RaidTimerClock.SOURCE_COX, "i1", 100, false, 1000);
		bob.sample(RaidTimerClock.SOURCE_COX, "i1", 101, false, 5000);
		// CoX docs explicitly allow a one-tick client sampling-phase difference.
		// These can be simultaneous game actions even though the samples differ by one.
		List<SpecHistoryEntry> simultaneous = Arrays.asList(
				event("dwh", alice.domain(), alice.tickAt(1000), SpecialWeapon.DRAGON_WARHAMMER, 1),
				event("bgs", bob.domain(), bob.tickAt(5000), SpecialWeapon.BANDOS_GODSWORD, 20));
		assertEquals("Unknown same-tick execution must retain the 189 conservative bound",
				Integer.valueOf(189), EncounterTimeline.replay(simultaneous, 310, corp()));
	}
}

package net.betterpartydefence;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

public class AuditScopeReturnRegressionTest {
	private SpecHistoryEntry event(String id, RaidTimerClock clock, int tick, SpecialWeapon weapon, int hit) {
		return new SpecHistoryEntry(id, weapon, hit, id, clock.domain(), clock.tickAt(tick));
	}

	private void assertConservative(SpecHistoryEntry earlier, SpecHistoryEntry later) {
		Integer result = EncounterTimeline.replay(Arrays.asList(earlier, later), 310,
				new EncounterTimeline.Replay<Integer>() {
					public Integer apply(Integer defence, SpecHistoryEntry e) {
						return e.getWeapon() == SpecialWeapon.DRAGON_WARHAMMER
								? defence - defence * 30 / 100
								: Math.max(0, defence - e.getHit() * 2);
					}
					public Integer conservative(Integer a, Integer b) {
						return Math.max(a, b);
					}
				});
		assertEquals("A room change cannot certify compatibility with pre-correction timestamps",
				Integer.valueOf(189), result);
	}

	@Test
	public void returningToPreviousRoomMustNotRestorePreCorrectionDomain() {
		RaidTimerClock clock = new RaidTimerClock();
		clock.sample(RaidTimerClock.SOURCE_TOA, "i111", 500, false, 1000);
		SpecHistoryEntry earlier = event("bgs", clock, 1001, SpecialWeapon.BANDOS_GODSWORD, 20);
		assertFalse(clock.sample(RaidTimerClock.SOURCE_TOA, "i111", 10, false, 1004));
		assertTrue(clock.sample(RaidTimerClock.SOURCE_TOA, "i111", 11, false, 1005));
		clock.sample(RaidTimerClock.SOURCE_TOA, "i222", 12, false, 1006);
		clock.sample(RaidTimerClock.SOURCE_TOA, "i111", 13, false, 1007);
		SpecHistoryEntry later = event("dwh", clock, 1007, SpecialWeapon.DRAGON_WARHAMMER, 1);
		assertConservative(earlier, later);
	}

	@Test
	public void scopeChangeWhileInactiveMustNotRestoreOldDomainOnReturn() {
		RaidTimerClock clock = new RaidTimerClock();
		clock.sample(RaidTimerClock.SOURCE_TOA, "i111", 500, false, 1000);
		SpecHistoryEntry earlier = event("bgs", clock, 1001, SpecialWeapon.BANDOS_GODSWORD, 20);
		assertFalse(clock.sample(RaidTimerClock.SOURCE_TOA, "i111", 10, false, 1004));
		assertTrue(clock.sample(RaidTimerClock.SOURCE_TOA, "i222", 11, false, 1005));
		clock.sample(RaidTimerClock.SOURCE_TOA, "i111", 12, false, 1006);
		SpecHistoryEntry later = event("dwh", clock, 1006, SpecialWeapon.DRAGON_WARHAMMER, 1);
		assertConservative(earlier, later);
	}
}

