package net.betterpartydefence;

import java.util.Arrays;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.betterpartydefence.DefenceTracker.SyncState;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import org.junit.Test;
import static org.junit.Assert.*;
import static net.betterpartydefence.EncounterTimeline.HistoryRelation.*;

public class EncounterTimelineLegacyComparisonTest {
	private final SpecHistoryEntry a = new SpecHistoryEntry("Alice", SpecialWeapon.DRAGON_WARHAMMER, 1);
	private final SpecHistoryEntry b = new SpecHistoryEntry("Bob", SpecialWeapon.BANDOS_GODSWORD, 50);
	private final SpecHistoryEntry c = new SpecHistoryEntry("Carol", SpecialWeapon.BANDOS_GODSWORD, 20);

	private SyncState state(long defence, SpecHistoryEntry... events) {
		return new SyncState("Chaos Elemental", BossDefence.CHAOS_ELEMENTAL, defence, 0, 270,
				100, 100, 100, 100, 0, 0, false, false, false, true, Arrays.asList(events));
	}
	@Test
	public void reversedTeamOrderIsConflictInBothDirections() {
		assertEquals(CONFLICT, EncounterTimeline.compareLegacy(state(139, a, b), state(154, b, a)));
		assertEquals(CONFLICT, EncounterTimeline.compareLegacy(state(154, b, a), state(139, a, b)));
	}
	@Test
	public void sharedPrefixWithDifferentSuffixesCannotBeAppendedInArrivalOrder() {
		assertEquals(CONFLICT, EncounterTimeline.compareLegacy(state(139, a, b), state(169, a, c)));
		assertEquals(CONFLICT, EncounterTimeline.compareLegacy(state(169, a, c), state(139, a, b)));
	}
	@Test
	public void longerHistoryIsNotProofWhenItOmitsALocalSpec() {
		assertEquals(CONFLICT, EncounterTimeline.compareLegacy(state(220, b), state(169, a, c)));
	}
	@Test
	public void realExtensionSupportsCatchupAndRejectsRollback() {
		assertEquals(INITIAL, EncounterTimeline.compareLegacy(null, state(139, a, b)));
		assertEquals(EXTENSION, EncounterTimeline.compareLegacy(state(189, a), state(139, a, b)));
		assertEquals(STALE, EncounterTimeline.compareLegacy(state(139, a, b), state(189, a)));
		assertEquals(SAME, EncounterTimeline.compareLegacy(state(139, a, b), state(139, a, b)));
	}
	@Test
	public void sameHistoryButDifferentValuesIsAlsoAConflict() {
		assertEquals(CONFLICT, EncounterTimeline.compareLegacy(state(139, a, b), state(154, a, b)));
	}
}

package net.betterpartydefence;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.mockito.Mockito.mock;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.runelite.api.Client;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import org.junit.Test;

public class EncounterTimelineReplayTest {
	private static SpecHistoryEntry event(String player, SpecialWeapon weapon, int hit, String id) {
		return new SpecHistoryEntry(player, weapon, hit, id, "clock", 0);
	}

	private static EncounterTimeline.Replay<Integer> multiplicative() {
		return new EncounterTimeline.Replay<Integer>() {
			@Override
			public Integer apply(Integer state, SpecHistoryEntry event) {
				return state - state * 30 / 100;
			}

			@Override
			public Integer conservative(Integer a, Integer b) {
				return Math.min(a, b);
			}
		};
	}

	@Test
	public void eightSameTickEquivalentsNoLongerExhaustTheBudget() {
		List<SpecHistoryEntry> events = new ArrayList<>();
		for (int i = 0; i < 8; i++) {
			events.add(event("P" + i, SpecialWeapon.DRAGON_WARHAMMER, i + 1, "e" + i));
		}

		// Without a symmetry key all 8! interleavings are distinct to the search and the
		// 100k budget is exhausted, so the old behaviour is the undrained baseline.
		assertEquals(Integer.valueOf(310), EncounterTimeline.replay(events, 310, multiplicative()));

		// The tracker's key treats every positive warhammer as the same state transition.
		Integer reduced = EncounterTimeline.replay(events, 310, multiplicative(),
				e -> "dragon-warhammer:positive");
		assertEquals(Integer.valueOf(19), reduced);
	}

	@Test
	public void symmetryReductionMatchesFullSearchOnAMixedSet() {
		List<SpecHistoryEntry> events = Arrays.asList(
				event("A", SpecialWeapon.DRAGON_WARHAMMER, 5, "a"),
				event("B", SpecialWeapon.DRAGON_WARHAMMER, 5, "b"),
				event("C", SpecialWeapon.BANDOS_GODSWORD, 10, "c"),
				event("D", SpecialWeapon.ARCLIGHT, 7, "d"),
				event("E", SpecialWeapon.SEERCULL, 4, "e"),
				event("F", SpecialWeapon.BANDOS_GODSWORD, 20, "f"));

		EncounterTimeline.Replay<Long> replay = new EncounterTimeline.Replay<Long>() {
			@Override
			public Long apply(Long state, SpecHistoryEntry event) {
				return state * 31L + event.getWeapon().ordinal() * 17L + event.getHit();
			}

			@Override
			public Long conservative(Long a, Long b) {
				return Math.max(a, b);
			}
		};

		Long full = EncounterTimeline.replay(events, 0L, replay);
		Long reduced = EncounterTimeline.replay(events, 0L, replay,
				e -> e.getWeapon().name() + ":" + e.getHit());
		assertEquals(full, reduced);
	}

	@Test
	public void distinctEventsAreNotCollapsed() {
		List<SpecHistoryEntry> events = Arrays.asList(
				event("A", SpecialWeapon.BANDOS_GODSWORD, 5, "a"),
				event("B", SpecialWeapon.BANDOS_GODSWORD, 6, "b"),
				event("C", SpecialWeapon.BANDOS_GODSWORD, 7, "c"),
				event("D", SpecialWeapon.DRAGON_WARHAMMER, 5, "d"),
				event("E", SpecialWeapon.ARCLIGHT, 5, "e"));

		EncounterTimeline.Replay<Long> replay = new EncounterTimeline.Replay<Long>() {
			@Override
			public Long apply(Long state, SpecHistoryEntry event) {
				return state * 17L + event.getHit();
			}

			@Override
			public Long conservative(Long a, Long b) {
				return Math.max(a, b);
			}
		};

		Long full = EncounterTimeline.replay(events, 0L, replay);
		Long reduced = EncounterTimeline.replay(events, 0L, replay,
				e -> e.getWeapon().name() + ":" + e.getHit());
		assertEquals(full, reduced);
	}

	@Test
	public void closeCrossClockHitsOrderByMilliseconds() {
		// Independent clocks (an open-world encounter): the event stamps decide the order, with
		// no minimum separation. 500 ms apart is still an order, not an ambiguous pair.
		SpecHistoryEntry first = event("A", SpecialWeapon.ARCLIGHT, 1, "a").withObservedAtMillis(10_000);
		SpecHistoryEntry second = new SpecHistoryEntry("B", SpecialWeapon.DRAGON_WARHAMMER, 1,
				"b", "peer-clock", 0).withObservedAtMillis(10_500);
		assertEquals("ab", EncounterTimeline.replay(List.of(first, second), "", recordingOrder()));
		assertEquals("ab", EncounterTimeline.replay(List.of(second, first), "", recordingOrder()));
	}

	@Test
	public void sharedTicksOverrideWallClockAndClockCycles() {
		SpecHistoryEntry first = event("A", SpecialWeapon.ARCLIGHT, 1, "a").withObservedAtMillis(30_000);
		SpecHistoryEntry second = new SpecHistoryEntry("A", SpecialWeapon.DRAGON_WARHAMMER, 1,
				"b", "clock", 1).withObservedAtMillis(10_000);
		SpecHistoryEntry other = new SpecHistoryEntry("B", SpecialWeapon.ARCLIGHT, 1,
				"c", "peer-clock", 0).withObservedAtMillis(20_000);
		assertEquals("cab", EncounterTimeline.replay(List.of(first, second, other), "", recordingOrder()));
	}

	@Test
	public void mergingAnOlderCopyPreservesTheOriginTimestamp() {
		SpecHistoryEntry old = event("A", SpecialWeapon.ARCLIGHT, 1, "a");
		SpecHistoryEntry timed = old.withObservedAtMillis(10_000);
		assertEquals(List.of(timed), EncounterTimeline.union(List.of(old), List.of(timed)));
		assertEquals(List.of(timed), EncounterTimeline.union(List.of(timed), List.of(old)));
	}

	private static EncounterTimeline.Replay<String> recordingOrder() {
		return new EncounterTimeline.Replay<String>() {
			@Override
			public String apply(String state, SpecHistoryEntry event) {
				return state + event.getEventId();
			}

			@Override
			public String conservative(String a, String b) {
				return a.compareTo(b) >= 0 ? a : b;
			}
		};
	}

	@Test
	public void trackerEffectKeyGroupsOnlyFormulaEquivalents() {
		DefenceTracker tracker = new DefenceTracker(mock(Client.class),
				mock(BetterPartyDefenceConfig.class));

		assertEquals(tracker.effectKey(event("A", SpecialWeapon.DRAGON_WARHAMMER, 5, "a"), null),
				tracker.effectKey(event("B", SpecialWeapon.DRAGON_WARHAMMER, 40, "b"), null));
		assertNotEquals(tracker.effectKey(event("A", SpecialWeapon.BANDOS_GODSWORD, 5, "a"), null),
				tracker.effectKey(event("B", SpecialWeapon.BANDOS_GODSWORD, 6, "b"), null));
		assertEquals(tracker.effectKey(event("A", SpecialWeapon.ARCLIGHT, 5, "a"), null),
				tracker.effectKey(event("B", SpecialWeapon.ARCLIGHT, 40, "b"), null));
		assertEquals(tracker.effectKey(event("A", SpecialWeapon.ACCURSED_SCEPTRE, 1, "a"), null),
				tracker.effectKey(event("B", SpecialWeapon.ACCURSED_SCEPTRE, 30, "b"), null));
		assertNotEquals(tracker.effectKey(event("A", SpecialWeapon.SEERCULL, 4, "a"), null),
				tracker.effectKey(event("B", SpecialWeapon.SEERCULL, 5, "b"), null));
		assertNotEquals(tracker.effectKey(event("A", SpecialWeapon.TONALZTICS_OF_RALOS, 1, "a"), null),
				tracker.effectKey(event("B", SpecialWeapon.TONALZTICS_OF_RALOS, 2, "b"), null));
	}
}

package net.betterpartydefence;

import static org.junit.Assert.assertEquals;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import org.junit.Test;

/** Verifies RuneLite-compatible hitsplat selection for supported special attacks. */
public class HitResolutionTest {
	@Test
	public void delayedSpecIgnoresTrailingThrallAndVengeance() {
		assertEquals(38, LocalDefenceSpecDetector.resolveObservedHit(
				SpecialWeapon.EYE_OF_AYAK, Arrays.asList(38, 3, 12)));
		assertEquals(38, LocalDefenceSpecDetector.resolveObservedHit(
				SpecialWeapon.SEERCULL, Arrays.asList(38, 3, 12)));
		assertEquals(0, LocalDefenceSpecDetector.resolveObservedHit(
				SpecialWeapon.ACCURSED_SCEPTRE, Arrays.asList(0, 3)));
	}

	@Test
	public void instantMeleeIgnoresPrecedingThrallAndVengeance() {
		assertEquals(38, LocalDefenceSpecDetector.resolveObservedHit(
				SpecialWeapon.BANDOS_GODSWORD, Arrays.asList(3, 12, 38)));
		assertEquals(0, LocalDefenceSpecDetector.resolveObservedHit(
				SpecialWeapon.DRAGON_WARHAMMER, Arrays.asList(3, 0)));
	}

	@Test
	public void realRalosHitsAreTakenFromTheFirstTwoSlots() {
		assertEquals(2, LocalDefenceSpecDetector.countConfirmedRalosHits(Arrays.asList(1, 2, 3)));
		assertEquals(1, LocalDefenceSpecDetector.countConfirmedRalosHits(Arrays.asList(0, 2, 3)));
		assertEquals(1, LocalDefenceSpecDetector.countConfirmedRalosHits(Arrays.asList(2, 0, 3)));
		assertEquals(0, LocalDefenceSpecDetector.countConfirmedRalosHits(Arrays.asList(0, 0, 3)));
		assertEquals(0, LocalDefenceSpecDetector.countConfirmedRalosHits(Arrays.asList(0, 0, 2)));
		assertEquals(2, LocalDefenceSpecDetector.countConfirmedRalosHits(Arrays.asList(2, 2, 2)));
		assertEquals(1, LocalDefenceSpecDetector.countConfirmedRalosHits(
				Arrays.asList(0, 1, 3, 44, 88)));
		assertEquals(2, LocalDefenceSpecDetector.countConfirmedRalosHits(
				Arrays.asList(1, 1, 2, 0, 10)));
	}

	@Test
	public void incompleteRalosPairStaysUnresolved() {
		assertEquals(-1, LocalDefenceSpecDetector.countConfirmedRalosHits(null));
		assertEquals(-1, LocalDefenceSpecDetector.countConfirmedRalosHits(Collections.emptyList()));
		assertEquals(-1, LocalDefenceSpecDetector.countConfirmedRalosHits(Collections.singletonList(3)));
		assertEquals(-1, LocalDefenceSpecDetector.countConfirmedRalosHits(Arrays.asList(-1, 3)));
	}

	@Test
	public void exhaustiveRalosRollsIgnoreSameTickThrall() {
		for (int first = 0; first <= 75; first++) {
			for (int second = 0; second <= 75; second++) {
				for (int thrall = 0; thrall <= 3; thrall++) {
					List<Integer> hits = Arrays.asList(first, second, thrall);
					int expected = (first > 0 ? 1 : 0) + (second > 0 ? 1 : 0);
					assertEquals("Ralos=" + first + "," + second + "; thrall=" + thrall,
							expected, LocalDefenceSpecDetector.countConfirmedRalosHits(hits));
				}
			}
		}
	}
}

package net.betterpartydefence;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class InitialSyncDisplayGateTest {
	private DefenceTracker.DefenceState state(int index, boolean drained) {
		return new DefenceTracker.DefenceState(index, "Example boss",
				100, 0, 100, 0, 0, 0, 0, 0, 0, drained, false);
	}

	@Test
	public void waitsOnlyForTheShortInitialPeriod() {
		InitialSyncDisplayGate gate = new InitialSyncDisplayGate();
		gate.arm(7, BossDefence.TEKTON, 100, 4);
		assertTrue(gate.isWaiting(state(7, false), 100));
		assertTrue(gate.isWaiting(state(7, false), 103));
		assertFalse(gate.isWaiting(state(7, false), 104));
		gate.expire(104);
		assertFalse(gate.isWaiting(state(7, false), 104));
	}

	@Test
	public void doesNotHideDrainAndDoesNotAffectOtherTargets() {
		InitialSyncDisplayGate gate = new InitialSyncDisplayGate();
		gate.arm(7, BossDefence.TEKTON, 100, 4);
		assertFalse(gate.isWaiting(state(7, true), 101));
		assertFalse(gate.isWaiting(state(8, false), 101));
	}

	@Test
	public void releaseTreatsEnragedTektonAsTekton() {
		InitialSyncDisplayGate gate = new InitialSyncDisplayGate();
		gate.arm(7, BossDefence.TEKTON, 100, 4);
		gate.release(7, BossDefence.TEKTON_ENRAGED);
		assertFalse(gate.isWaiting(state(7, false), 101));
	}

	@Test
	public void duplicatePresenceDoesNotExtendGracePeriod() {
		InitialSyncDisplayGate gate = new InitialSyncDisplayGate();
		gate.arm(7, BossDefence.TEKTON, 100, 4);
		gate.arm(7, BossDefence.TEKTON, 102, 4);
		assertFalse(gate.isWaiting(state(7, false), 104));
	}

	@Test
	public void clearOnRaidExitOrReset() {
		InitialSyncDisplayGate gate = new InitialSyncDisplayGate();
		gate.arm(7, BossDefence.TEKTON, 100, 4);
		gate.clear();
		assertFalse(gate.isWaiting(state(7, false), 100));
	}

	@Test
	public void clearForBossLeavesOtherBossGatesUntouched() {
		InitialSyncDisplayGate gate = new InitialSyncDisplayGate();
		gate.arm(7, BossDefence.TEKTON, 100, 4);
		gate.arm(8, BossDefence.VORKATH, 100, 4);
		gate.clearForBoss(BossDefence.TEKTON);
		assertFalse(gate.isWaiting(state(7, false), 101));
		assertTrue(gate.isWaiting(state(8, false), 101));
	}
}

