		NPC bossB = h.addNpc(BOSS_B_INDEX, "Corporeal Beast");
		h.selectAndDrain(bossB, "LocalPlayer");
		h.trackPartySpec(bossA, "Alice");

		h.renderOverlay();

		assertEquals("the active target must remain Boss B", BOSS_B_INDEX,
				h.tracker.state().getNpcIndex());
