	private static final class Harness {
		private final Map<Integer, NPC> npcsByIndex = new LinkedHashMap<>();
		private final Map<Integer, BossDefence> bossByIndex = new LinkedHashMap<>();
		private final Client client = mock(Client.class);
		private final WorldView worldView = mock(WorldView.class);
		@SuppressWarnings("unchecked")
		private final IndexedObjectSet<NPC> npcs = mock(IndexedObjectSet.class);
		@SuppressWarnings("unchecked")
		private final IndexedObjectSet<Player> players = mock(IndexedObjectSet.class);
		private final Player localPlayer = mock(Player.class);
		private final BetterPartyDefenceConfig config = mock(BetterPartyDefenceConfig.class);
		private final Graphics2D graphics = mock(Graphics2D.class);
		private final FontMetrics fontMetrics = mock(FontMetrics.class);
		private final BufferedImage skillImage = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		private final SkillIconManager skillIconManager = mock(SkillIconManager.class);
		private final InitialSyncDisplayGate initialSyncDisplayGate = new InitialSyncDisplayGate();
		private final DefenceTracker tracker;
		private final NpcDefenceOverlay overlay;

		private boolean alwaysShow;
		private boolean defenceEnabled = true;
		private DefenceOverlayPosition position = DefenceOverlayPosition.ABOVE_HP_BAR;
		private int tick = 100;
		private NPC interacting;

		@SuppressWarnings("unchecked")
		private Harness() {
			when(client.getTopLevelWorldView()).thenReturn(worldView);
			when(client.getLocalPlayer()).thenReturn(localPlayer);
			when(client.getTickCount()).thenAnswer(invocation -> tick);
			when(client.getWorld()).thenReturn(WORLD);
			doReturn(npcs).when(worldView).npcs();
			doReturn(players).when(worldView).players();
			when(npcs.byIndex(anyInt())).thenAnswer(
					invocation -> npcsByIndex.get(invocation.getArgument(0)));
			when(npcs.iterator()).thenAnswer(
					invocation -> new ArrayList<>(npcsByIndex.values()).iterator());
			when(players.iterator()).thenReturn(java.util.Collections.emptyIterator());
			when(localPlayer.getInteracting()).thenAnswer(invocation -> interacting);
			when(localPlayer.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
			when(skillIconManager.getSkillImage(any())).thenReturn(skillImage);

			when(config.defenceHpBar()).thenAnswer(invocation -> defenceEnabled);
			when(config.defenceAlwaysShow()).thenAnswer(invocation -> alwaysShow);
			when(config.defenceHpBarPosition()).thenAnswer(invocation -> position);
			when(config.defenceHpBarYOffset()).thenReturn(0);
			when(config.defenceValueFormat()).thenReturn(DefenceValueFormat.CURRENT);
			when(config.defenceDrainFormat()).thenReturn(DefenceDrainFormat.AMOUNT);
			when(config.defenceInfoBoxValue()).thenReturn(DefenceInfoBoxValue.CURRENT);
			when(config.defenceShowFullLevel()).thenReturn(false);
			when(config.defenceShowIcons()).thenReturn(false);
			when(config.defenceUseThemeSkillIcons()).thenReturn(false);
			when(config.defenceTextPlate()).thenReturn(false);
			when(config.defenceLowThresholdUnit()).thenReturn(DefenceThresholdUnit.LEVELS);
			when(config.defenceLowThreshold()).thenReturn(10);
			when(config.defenceHighColor()).thenReturn(Color.WHITE);
			when(config.defenceLowColor()).thenReturn(Color.YELLOW);
			when(config.defenceCappedColor()).thenReturn(Color.GREEN);
			when(config.defenceDrainColor()).thenReturn(Color.RED);
			when(config.magicDefence()).thenReturn(false);
			when(config.defenceFont()).thenReturn(TrackerFont.SANS_SERIF);
			when(config.defenceFontSize()).thenReturn(12);
			when(config.defenceBoldText()).thenReturn(false);

			when(graphics.getFontMetrics()).thenReturn(fontMetrics);
			when(fontMetrics.stringWidth(anyString())).thenReturn(10);
			when(fontMetrics.getHeight()).thenReturn(12);
			when(fontMetrics.getAscent()).thenReturn(9);
			when(fontMetrics.getDescent()).thenReturn(3);

			tracker = new DefenceTracker(client, config);
			overlay = new NpcDefenceOverlay(client, tracker, config,
					new DefenceOverlayRenderer.IconSource(client, skillIconManager, config),
					initialSyncDisplayGate);
		}

		private NPC addNpc(int index, String name) {
			NPC npc = mock(NPC.class);
			when(npc.getName()).thenReturn(name);
			when(npc.getIndex()).thenReturn(index);
			when(npc.getId()).thenReturn(0);
			when(npc.getHealthRatio()).thenReturn(1);
			when(npc.getHealthScale()).thenReturn(1);
			when(npc.isDead()).thenReturn(false);
			when(npc.getLogicalHeight()).thenReturn(100);
			when(npc.getWorldLocation()).thenReturn(new WorldPoint(3200 + index, 3200, 0));
			Point anchor = mock(Point.class);
			when(anchor.getX()).thenReturn(100);
			when(anchor.getY()).thenReturn(100);
			when(npc.getCanvasTextLocation(any(Graphics2D.class), anyString(), anyInt()))
					.thenReturn(anchor);
			npcsByIndex.put(index, npc);
			bossByIndex.put(index, BossDefence.matchingNpcName(name));
			return npc;
		}

		private void removeNpc(NPC npc) {
			npcsByIndex.remove(npc.getIndex());
		}

		private void restoreNpc(NPC npc) {
			npcsByIndex.put(npc.getIndex(), npc);
		}

		private void selectAndDrain(NPC npc, String playerName) {
			interacting = npc;
			tracker.queueLocal(SpecialWeapon.DRAGON_WARHAMMER, npc.getIndex(), 1, WORLD,
					playerName, npc);
			advanceTick();
		}

		private void trackPartySpec(NPC npc, String playerName) {
			tracker.queue(SpecialWeapon.DRAGON_WARHAMMER, npc.getIndex(), 1, WORLD,
					playerName, npc);
			advanceTick();
		}

		private void advanceTick() {
			tick++;
			tracker.onGameTick();
		}

		private void renderOverlay() {
			overlay.render(graphics);
		}

		private DefenceInfoBox infoBox() {
			return new DefenceInfoBox(
					new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB),
					mock(Plugin.class), tracker, config);
		}

		private int historySize(int npcIndex) {
			BossDefence boss = bossByIndex.get(npcIndex);
			SyncState state = boss == null ? null : tracker.syncStateForBoss(boss);
			return state == null || state.getHistory() == null ? 0 : state.getHistory().size();
		}
	}
}

package net.betterpartydefence;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class NpcTargetMatchingTest {
	private final WorldView worldView = mock(WorldView.class);
	private final List<NPC> sceneNpcs = new ArrayList<>();

	@SuppressWarnings("unchecked")
	private void loadScene() {
		IndexedObjectSet<? extends NPC> npcs = mock(IndexedObjectSet.class);
		doReturn(npcs).when(worldView).npcs();
		when(npcs.iterator()).thenAnswer(invocation -> sceneNpcs.iterator());
	}

	private NPC npc(String name, int id, int index, WorldPoint location) {
		NPC npc = mock(NPC.class);
		when(npc.getName()).thenReturn(name);
		when(npc.getId()).thenReturn(id);
		when(npc.getIndex()).thenReturn(index);
		when(npc.getWorldLocation()).thenReturn(location);
		when(npc.getHealthRatio()).thenReturn(1);
		sceneNpcs.add(npc);
		return npc;
	}

	@Test
	public void twoSameTypeActorsRemainAmbiguousWithoutNewEvidence() {
		loadScene();
		npc("Chaos Elemental", 1, 10, new WorldPoint(1000, 1000, 0));
		npc("Chaos Elemental", 2, 11, new WorldPoint(1001, 1000, 0));

		assertNull(TargetResolver.uniqueLiveNpc(worldView, BossDefence.CHAOS_ELEMENTAL));
	}

	@Test
	public void senderCoordinatesSelectOneSameTypeActor() {
		loadScene();
		NPC first = npc("Chaos Elemental", 1, 10, new WorldPoint(1000, 1000, 0));
		npc("Chaos Elemental", 2, 11, new WorldPoint(1020, 1020, 0));

		assertEquals(first, TargetResolver.uniqueLiveNpcNear(
				worldView, BossDefence.CHAOS_ELEMENTAL, 1000, 1000, 0, 2));
	}

	@Test
	public void rememberedNpcIdAndLocationSelectTheOriginalTarget() {
		loadScene();
		npc("Chaos Elemental", 1, 10, new WorldPoint(1000, 1000, 0));
		NPC second = npc("Chaos Elemental", 2, 11, new WorldPoint(1020, 1020, 0));

		assertEquals(second, TargetResolver.uniqueLiveNpcFor(
				worldView, BossDefence.CHAOS_ELEMENTAL, 2, new WorldPoint(1020, 1020, 0), 2));
	}

	@Test
	public void rememberedTargetDoesNotMatchActorWithoutCurrentTile() {
		loadScene();
		npc("Chaos Elemental", 1, 10, new WorldPoint(1000, 1000, 0));
		NPC replacement = npc("Chaos Elemental", 1, 10, null);

		assertFalse(TargetResolver.matches(
				replacement, BossDefence.CHAOS_ELEMENTAL, 1, new WorldPoint(1000, 1000, 0), 2));
	}

	@Test
	public void locationToleranceIncludesDiagonalBoundaryButNotAnotherPlane() {
		loadScene();
		NPC target = npc("Chaos Elemental", 1, 10, new WorldPoint(1002, 1002, 0));
		NPC otherPlane = npc("Chaos Elemental", 1, 11, new WorldPoint(1000, 1000, 1));
		WorldPoint origin = new WorldPoint(1000, 1000, 0);

		assertEquals(target, TargetResolver.uniqueLiveNpcNear(
				worldView, BossDefence.CHAOS_ELEMENTAL, 1000, 1000, 0, 2));
		assertEquals(target, TargetResolver.uniqueLiveNpcFor(
				worldView, BossDefence.CHAOS_ELEMENTAL, 1, origin, 2));
		assertTrue(TargetResolver.matches(target, BossDefence.CHAOS_ELEMENTAL, 1, origin, 2));
		assertFalse(TargetResolver.matches(otherPlane, BossDefence.CHAOS_ELEMENTAL, 1, origin, 2));
	}

	@Test
	public void queuedEvidenceKeepsActorIdentityAndLocationGuards() {
		NPC target = npc("Chaos Elemental", 1, 10, new WorldPoint(1000, 1000, 0));
		NPC replacement = npc("Chaos Elemental", 1, 10, new WorldPoint(1000, 1000, 0));
		PendingSpecQueue.TargetEvidence exact = PendingSpecQueue.TargetEvidence.from(target);
		PendingSpecQueue.TargetEvidence location = new PendingSpecQueue.TargetEvidence(
				BossDefence.CHAOS_ELEMENTAL, 1, new WorldPoint(1000, 1000, 0), null);

		assertTrue(exact.matches(target));
		assertFalse(exact.matches(replacement));
		assertTrue(location.matches(replacement));
		when(replacement.getWorldLocation()).thenReturn(new WorldPoint(1003, 1000, 0));
		assertFalse(location.matches(replacement));
	}
}

package net.betterpartydefence;

import java.util.Arrays;
import java.util.Collections;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.betterpartydefence.DefenceTracker.SpellDrain;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Regression coverage for the three review points on the generalised encounter handling: independently clocked
 * ordering, the no-op merge predicate, and target capture.
 */
public class OrderingAndTargetCaptureRegressionTest {
	private static SpecHistoryEntry event(String id, String anchor, long tick,
			SpecialWeapon weapon, int hit, long observedAtMillis) {
		return new SpecHistoryEntry("Alice", weapon, hit, id, anchor, tick)
				.withObservedAtMillis(observedAtMillis);
	}

	/** DWH is order-sensitive against BGS: DWH first drains more in total. */
	private static EncounterTimeline.Replay<Integer> defenceReplay() {
		return new EncounterTimeline.Replay<Integer>() {
			@Override
			public Integer apply(Integer defence, SpecHistoryEntry entry) {
				if (entry.getWeapon() == SpecialWeapon.DRAGON_WARHAMMER) {
					return defence - defence * 30 / 100;
				}
				return Math.max(0, defence - entry.getHit());
			}

			@Override
			public Integer conservative(Integer a, Integer b) {
				return Math.max(a, b);
			}
		};
	}

	private static int replay(SpecHistoryEntry... events) {
		return EncounterTimeline.replay(Arrays.asList(events), 310, defenceReplay());
	}

	// 1. Independent clocks: order by the event's own millisecond stamp, with no minimum gap.
	@Test
	public void independentClocksOrderByMillisecondsWithoutAMinimumGap() {
		SpecHistoryEntry warhammer = event("dwh", "open:a", 10,
				SpecialWeapon.DRAGON_WARHAMMER, 1, 1_000L);
		SpecHistoryEntry godsword = event("bgs", "open:b", 20,
				SpecialWeapon.BANDOS_GODSWORD, 30, 1_100L);

		// Ordered: 310 -> 217 -> 187. Unordered would take the larger of both orders, 196.
		assertEquals(187, replay(warhammer, godsword));
		assertEquals(187, replay(godsword, warhammer));
	}

	@Test
	public void independentClocksOneMillisecondApartAreStillOrdered() {
		SpecHistoryEntry warhammer = event("dwh", "open:a", 10,
				SpecialWeapon.DRAGON_WARHAMMER, 1, 1_000L);
		SpecHistoryEntry godsword = event("bgs", "open:b", 20,
				SpecialWeapon.BANDOS_GODSWORD, 30, 1_001L);

		assertEquals(187, replay(warhammer, godsword));
	}

	@Test
	public void equalMillisecondStampsStayUnordered() {
		SpecHistoryEntry warhammer = event("dwh", "open:a", 10,
				SpecialWeapon.DRAGON_WARHAMMER, 1, 1_000L);
		SpecHistoryEntry godsword = event("bgs", "open:b", 20,
				SpecialWeapon.BANDOS_GODSWORD, 30, 1_000L);

		// No evidence of which came first, so both orders are legal: conservative maximum.
		assertEquals(196, replay(warhammer, godsword));
	}

	// 2. Shared raid ticks keep tick ordering, and the stamps cannot override it.
	@Test
	public void sharedAnchorKeepsTickOrderingEvenWhenStampsDisagree() {
		SpecHistoryEntry warhammer = event("dwh", "raid-time:v1:toa:i1:u2", 10,
				SpecialWeapon.DRAGON_WARHAMMER, 1, 9_000L);
		SpecHistoryEntry godsword = event("bgs", "raid-time:v1:toa:i1:u2", 20,
				SpecialWeapon.BANDOS_GODSWORD, 30, 1_000L);

		assertEquals(187, replay(warhammer, godsword));
		assertEquals(187, replay(godsword, warhammer));
	}

	@Test
	public void sameTickSameAnchorStaysUnordered() {
		SpecHistoryEntry first = event("dwh1", "raid-time:v1:toa:i1:u2", 10,
				SpecialWeapon.DRAGON_WARHAMMER, 1, 1_000L);
		SpecHistoryEntry second = event("dwh2", "raid-time:v1:toa:i1:u2", 10,
				SpecialWeapon.DRAGON_WARHAMMER, 1, 1_050L);

		// Same shared tick: the two stamps are sampling noise, so the reduction stays exact.
		assertEquals(310 - 310 * 30 / 100 - (310 - 310 * 30 / 100) * 30 / 100,
				replay(first, second));
	}

	// 3. The no-op merge predicate must follow each weapon's drain formula.
	@Test
	public void zeroHitWarhammerThatStillDrainsIsNotANoOp() {
		NPC npc = mock(NPC.class);
		SpecialWeapon weapon = mock(SpecialWeapon.class);
		// RuneLite reports Tekton's guaranteed-on-miss drain as a positive percentage.
		when(weapon.computeDrainPercent(0, npc)).thenReturn(5.0f);

		SpecHistoryEntry miss = new SpecHistoryEntry("Alice", weapon, 0, "e1", "open", 1)
				.withObservedAtMillis(1_000L);

		assertFalse(DefenceTracker.onlyNoOpEvents(Collections.singletonList(miss), npc));
	}

	@Test
	public void zeroHitWithNoDrainPercentageIsANoOp() {
		NPC npc = mock(NPC.class);
		SpecialWeapon weapon = mock(SpecialWeapon.class);
		when(weapon.computeDrainPercent(0, npc)).thenReturn(0.0f);

		SpecHistoryEntry miss = new SpecHistoryEntry("Alice", weapon, 0, "e1", "open", 1)
				.withObservedAtMillis(1_000L);

		assertTrue(DefenceTracker.onlyNoOpEvents(Collections.singletonList(miss), npc));
	}

	@Test
	public void undatedRowsAndSpellsAreNeverNoOps() {
		NPC npc = mock(NPC.class);
		SpecialWeapon weapon = mock(SpecialWeapon.class);
		when(weapon.computeDrainPercent(0, npc)).thenReturn(0.0f);

		SpecHistoryEntry undated = new SpecHistoryEntry("Alice", weapon, 0, "e1", "open", 1);
		assertFalse(DefenceTracker.onlyNoOpEvents(Collections.singletonList(undated), npc));

		SpecHistoryEntry spell = new SpecHistoryEntry("Alice", null, SpellDrain.VULNERABILITY,
				1, "e2", "open", 1).withObservedAtMillis(1_000L);
		assertFalse(DefenceTracker.onlyNoOpEvents(Collections.singletonList(spell), npc));
	}

	// 4. Target capture: a target change after the spec must not steal it.
	@Test
	public void capturedTargetWinsWhenTheInteractionChanged() {
		Client client = mock(Client.class);
		Player local = mock(Player.class);
		NPC captured = mock(NPC.class);
		NPC newTarget = mock(NPC.class);
		when(captured.getId()).thenReturn(1_234);
		when(captured.getIndex()).thenReturn(100);
		when(captured.getName()).thenReturn("Chaos Elemental");
		when(newTarget.getId()).thenReturn(1_234);
