public class RaidTimerPluginTest {
	private BetterPartyDefencePlugin plugin;
	private DefenceTracker tracker;
	private Client client;
	private WorldView world;
	private NPC npc;

	private void set(String name, Object value) throws Exception {
		Field field = BetterPartyDefencePlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	@Before
	@SuppressWarnings("unchecked")
	public void setup() throws Exception {
		client = mock(Client.class);
		world = mock(WorldView.class);
		IndexedObjectSet<? extends NPC> npcs = mock(IndexedObjectSet.class);
		npc = mock(NPC.class);
		when(client.getWorld()).thenReturn(301);
		when(client.getTopLevelWorldView()).thenReturn(world);
		doReturn(npcs).when(world).npcs();
		when(npcs.byIndex(1)).thenReturn(npc);
		when(npcs.iterator()).thenAnswer(i -> Collections.singletonList(npc).iterator());
		when(npc.getName()).thenReturn("Corporeal Beast");
		when(npc.getIndex()).thenReturn(1);
		when(npc.getId()).thenReturn(-1);
		when(npc.getHealthRatio()).thenReturn(1);

		tracker = new DefenceTracker(client, mock(BetterPartyDefenceConfig.class));
		plugin = new BetterPartyDefencePlugin();
		set("client", client);
		set("defenceTracker", tracker);
	}

	private void timerScript(int scriptId, int elapsed, int stopped) {
		ScriptEvent scriptEvent = mock(ScriptEvent.class);
		when(scriptEvent.getArguments()).thenReturn(new Object[]{scriptId, elapsed, stopped});
		ScriptPreFired event = new ScriptPreFired(scriptId);
		event.setScriptEvent(scriptEvent);
		plugin.onScriptPreFired(event);
	}

	private SpecHistoryEntry localSpec(int tick) {
		when(client.getTickCount()).thenReturn(tick);
		tracker.queueLocal(SpecialWeapon.DRAGON_WARHAMMER, 1, 1, 301, "Alice");
		tracker.onGameTick();
		return tracker.specHistory().get(0);
	}

	private void coxPoll(int tick) throws Exception {
		Method update = BetterPartyDefencePlugin.class.getDeclaredMethod("updateRaidTimerClock", int.class);
		update.setAccessible(true);
		update.invoke(plugin, tick);
		Method apply = BetterPartyDefencePlugin.class.getDeclaredMethod("applySharedRaidTickAnchor", int.class);
		apply.setAccessible(true);
		apply.invoke(plugin, tick);
	}

	@Test
	public void tfaTimerScriptAnchorsRaidElapsedTicks() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarpValue(net.runelite.api.gameval.VarPlayerID.TFA_MYCONTROLLER)).thenReturn(77);
		when(client.getTickCount()).thenReturn(5_000);

		timerScript(RaidTimerClock.TFA_TIMER_SCRIPT, 0, 0);
		SpecHistoryEntry entry = localSpec(5_007);

		assertEquals("raid-time:v1:tfa:c77:u2", entry.getTickAnchor());
		assertEquals(7L, entry.getEncounterTick());
	}

	@Test
	public void toaTimerUsesAStableControllerScopeAcrossRooms() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarpValue(net.runelite.api.gameval.VarPlayerID.TOA_MYCONTROLLER)).thenReturn(88);
		when(client.getTickCount()).thenReturn(5_000);
		timerScript(RaidTimerClock.TOA_TIMER_SCRIPT, 0, 0);

		when(world.getBaseX()).thenReturn(4_000);
		when(client.getTickCount()).thenReturn(5_005);
		timerScript(RaidTimerClock.TOA_TIMER_SCRIPT, 5, 0);
		SpecHistoryEntry entry = localSpec(5_007);

		assertEquals("raid-time:v1:toa:c88:u2", entry.getTickAnchor());
		assertEquals(7L, entry.getEncounterTick());
	}

	@Test
	public void toaTimerScriptUsesTheSharedInstanceScope() {
		when(world.isInstance()).thenReturn(true);
		when(client.getTickCount()).thenReturn(9_000);

		timerScript(RaidTimerClock.TOA_TIMER_SCRIPT, 120, 0);
		SpecHistoryEntry entry = localSpec(9_004);

		assertTrue(entry.getTickAnchor().startsWith("raid-time:v1:toa:i"));
		assertEquals(124L, entry.getEncounterTick());
	}

	@Test
	public void tfaTimerKeepsItsControllerScopeAcrossRoomScenes() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarpValue(net.runelite.api.gameval.VarPlayerID.TFA_MYCONTROLLER)).thenReturn(77);
		when(client.getTickCount()).thenReturn(5_000);
		timerScript(RaidTimerClock.TFA_TIMER_SCRIPT, 0, 0);

		// A later room has a different scene, but the same party controller and the same
		// running timer. The established domain must not change mid-raid.
		when(world.getBaseX()).thenReturn(4_000);
		when(client.getTickCount()).thenReturn(5_005);
		timerScript(RaidTimerClock.TFA_TIMER_SCRIPT, 5, 0);
		SpecHistoryEntry entry = localSpec(5_007);

		assertEquals("raid-time:v1:tfa:c77:u2", entry.getTickAnchor());
		assertEquals(7L, entry.getEncounterTick());
	}

	@Test
	public void stoppedTimerStopsAnchoringNewSpecs() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarpValue(net.runelite.api.gameval.VarPlayerID.TFA_MYCONTROLLER)).thenReturn(77);
		when(client.getTickCount()).thenReturn(5_000);
		timerScript(RaidTimerClock.TFA_TIMER_SCRIPT, 0, 0);

		when(client.getTickCount()).thenReturn(5_020);
		timerScript(RaidTimerClock.TFA_TIMER_SCRIPT, 20, 1);
		SpecHistoryEntry entry = localSpec(5_021);

		assertEquals(entry.getEventId(), entry.getTickAnchor());
		assertEquals(0L, entry.getEncounterTick());
	}

	@Test
	public void clearedTimerDoesNotLeaveAStaleAnchor() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarpValue(net.runelite.api.gameval.VarPlayerID.TFA_MYCONTROLLER)).thenReturn(77);
		when(client.getTickCount()).thenReturn(5_000);
		timerScript(RaidTimerClock.TFA_TIMER_SCRIPT, 0, 0);

		when(client.getTickCount()).thenReturn(5_010);
		timerScript(RaidTimerClock.TFA_TIMER_SCRIPT, -1, 0);
		SpecHistoryEntry entry = localSpec(5_011);

		assertEquals(entry.getEventId(), entry.getTickAnchor());
	}

	@Test
	public void timerOutsideAnInstanceIsIgnored() {
		when(world.isInstance()).thenReturn(false);
		when(client.getTickCount()).thenReturn(5_000);
		timerScript(RaidTimerClock.TFA_TIMER_SCRIPT, 0, 0);

		SpecHistoryEntry entry = localSpec(5_005);

		assertEquals(entry.getEventId(), entry.getTickAnchor());
	}

	@Test
	public void coxProgressZeroIsStillTheLobby() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_INDUNGEON)).thenReturn(1);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_PROGRESS)).thenReturn(0);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_TIMER)).thenReturn(0);
		when(client.getTickCount()).thenReturn(5_000);

		try {
			coxPoll(5_000);
		} catch (Exception e) {
			throw new AssertionError(e);
		}
		SpecHistoryEntry entry = localSpec(5_003);

		assertEquals(entry.getEventId(), entry.getTickAnchor());
	}

	@Test
	public void coxRunningTimerAnchorsProgressElapsedTicks() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_INDUNGEON)).thenReturn(1);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_PROGRESS)).thenReturn(1);
		when(client.getTickCount()).thenReturn(5_000);

		for (int i = 0; i < 5; i++) {
			when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_TIMER)).thenReturn(30 + i);
			try {
				coxPoll(5_000 + i);
			} catch (Exception e) {
				throw new AssertionError(e);
			}
		}
		SpecHistoryEntry entry = localSpec(5_006);

		assertTrue(entry.getTickAnchor().startsWith("raid-time:v1:cox:i"));
		assertEquals(36L, entry.getEncounterTick());
	}

	@Test
	public void frozenCoxTimerFallsBackInsteadOfFreezingElapsedTime() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_INDUNGEON)).thenReturn(1);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_PROGRESS)).thenReturn(1);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_TIMER)).thenReturn(30);
		when(client.getTickCount()).thenReturn(5_000);

		for (int tick = 5_000; tick <= 5_010; tick++) {
			try {
				coxPoll(tick);
			} catch (Exception e) {
				throw new AssertionError(e);
			}
		}
		SpecHistoryEntry entry = localSpec(5_011);

		assertEquals(entry.getEventId(), entry.getTickAnchor());
	}

	@Test
	public void coxExitClearsTheTimerDomain() {
		when(world.isInstance()).thenReturn(true);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_INDUNGEON)).thenReturn(1);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_PROGRESS)).thenReturn(1);
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_TIMER)).thenReturn(30);
		when(client.getTickCount()).thenReturn(5_000);
		try {
			coxPoll(5_000);
		} catch (Exception e) {
			throw new AssertionError(e);
		}

		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.RAIDS_CLIENT_INDUNGEON)).thenReturn(0);
		try {
			coxPoll(5_001);
		} catch (Exception e) {
			throw new AssertionError(e);
		}
		SpecHistoryEntry entry = localSpec(5_002);

		assertEquals(entry.getEventId(), entry.getTickAnchor());
	}
}

package net.betterpartydefence;

import org.junit.Test;
import static org.junit.Assert.*;

public class SnapshotEchoGuardTest {
	@Test
	public void creditIsConsumedOnlyOnce() {
		SnapshotEchoGuard<String> guard = new SnapshotEchoGuard<>(2);
		guard.add("boss1/Alice/BGS/50", 10);
		assertTrue(guard.consume("boss1/Alice/BGS/50", 10));
		assertFalse(guard.consume("boss1/Alice/BGS/50", 11));
	}
	@Test
	public void repeatedNewRowsReceiveSeparateCredits() {
		SnapshotEchoGuard<String> guard = new SnapshotEchoGuard<>(2);
		guard.add("same", 10);
		guard.add("same", 10);
		assertTrue(guard.consume("same", 11));
		assertTrue(guard.consume("same", 11));
		assertFalse(guard.consume("same", 11));
	}
	@Test
	public void anotherTargetAndExpiredEchoCannotSuppressAHit() {
		SnapshotEchoGuard<String> guard = new SnapshotEchoGuard<>(2);
		guard.add("boss1", 10);
		assertFalse(guard.consume("boss2", 10));
		assertFalse(guard.consume("boss1", 13));
	}
	@Test
	public void resetAndTickRollbackDiscardCredits() {
		SnapshotEchoGuard<String> guard = new SnapshotEchoGuard<>(2);
		guard.add("a", 10);
		guard.clear();
		assertFalse(guard.consume("a", 11));
		guard.add("a", 10);
		assertFalse(guard.consume("a", 1));
	}
}

package net.betterpartydefence;

import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.Map;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import org.junit.Test;

/** Ensures icon values use precisely the accepted BPD hit history. */
public class SpecWeaponInfoBoxTest {
	private SpecHistoryEntry hit(String player, SpecialWeapon weapon, int amount) {
		return new SpecHistoryEntry(player, weapon, amount);
	}

	@Test
	public void percentageSpecsCountHitsWhileDamageSpecsSumTheirAmounts() {
		Map<SpecialWeapon, SpecWeaponSummary> result = SpecWeaponSummary.fromHistory(Arrays.asList(
				hit("A", SpecialWeapon.DRAGON_WARHAMMER, 45),
				hit("B", SpecialWeapon.DRAGON_WARHAMMER, 12),
				hit("A", SpecialWeapon.BANDOS_GODSWORD, 25),
				hit("B", SpecialWeapon.BANDOS_GODSWORD, 19),
				hit("A", SpecialWeapon.EYE_OF_AYAK, 18),
				hit("B", SpecialWeapon.TONALZTICS_OF_RALOS, 2)));
		assertEquals(2, result.get(SpecialWeapon.DRAGON_WARHAMMER).value);
		assertEquals(44, result.get(SpecialWeapon.BANDOS_GODSWORD).value);
		assertEquals(18, result.get(SpecialWeapon.EYE_OF_AYAK).value);
		assertEquals(2, result.get(SpecialWeapon.TONALZTICS_OF_RALOS).value);
	}

	@Test
	public void missesNeverInflateHitsOrDamage() {
		SpecWeaponSummary dwh = SpecWeaponSummary.fromHistory(Arrays.asList(
				hit("A", SpecialWeapon.DRAGON_WARHAMMER, 0),
				hit("B", SpecialWeapon.DRAGON_WARHAMMER, 12),
				hit("B", SpecialWeapon.DRAGON_WARHAMMER, 0)))
				.get(SpecialWeapon.DRAGON_WARHAMMER);
		assertEquals(1, dwh.value);
		assertEquals(2, dwh.missedAttempts);
		assertEquals(1, dwh.players.get("B").misses);
		assertTrue(dwh.tooltip().contains("Misses: 2"));
	}

	@Test
	public void currentHistoryAloneControlsVisibilityAndFreshEncounterResets() {
		assertTrue(SpecWeaponSummary.fromHistory(Collections.emptyList()).isEmpty());
		Map<SpecialWeapon, SpecWeaponSummary> first = SpecWeaponSummary.fromHistory(Arrays.asList(
				hit("A", SpecialWeapon.BANDOS_GODSWORD, 30)));
		Map<SpecialWeapon, SpecWeaponSummary> next = SpecWeaponSummary.fromHistory(Arrays.asList(
				hit("A", SpecialWeapon.BANDOS_GODSWORD, 4)));
		assertEquals(30, first.get(SpecialWeapon.BANDOS_GODSWORD).value);
		assertEquals(4, next.get(SpecialWeapon.BANDOS_GODSWORD).value);
	}
}

package net.betterpartydefence;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import org.junit.Test;

public class SpecialWeaponRulesTest {
	@Test
	public void supportedWeaponsUseOneClassification() {
		assertTrue(SpecialWeaponRules.isSupported(SpecialWeapon.DRAGON_WARHAMMER));
		assertTrue(SpecialWeaponRules.drainsDefence(SpecialWeapon.DRAGON_WARHAMMER));
		assertFalse(SpecialWeaponRules.drainsMagicDefence(SpecialWeapon.DRAGON_WARHAMMER));

		assertTrue(SpecialWeaponRules.isSupported(SpecialWeapon.SEERCULL));
		assertFalse(SpecialWeaponRules.drainsDefence(SpecialWeapon.SEERCULL));
		assertTrue(SpecialWeaponRules.drainsMagicDefence(SpecialWeapon.SEERCULL));

		assertFalse(SpecialWeaponRules.isSupported(SpecialWeapon.BULWARK));
		assertFalse(SpecialWeaponRules.drainsDefence(null));
	}

	@Test
	public void equipmentIdIndexContainsEverySupportedVariantOnly() {
		for (SpecialWeapon weapon : SpecialWeapon.values()) {
			for (int itemId : weapon.getItemID()) {
				SpecialWeapon match = SpecialWeaponRules.byItemId(itemId);
				if (SpecialWeaponRules.isSupported(weapon)) {
					assertSame(weapon, match);
				} else {
					assertNull(match);
				}
			}
		}
		assertSame(SpecialWeapon.DRAGON_WARHAMMER,
				SpecialWeaponRules.byItemId(ItemID.BH_DRAGON_WARHAMMER_CORRUPTED));
	}

	@Test
	public void reportedValuesPreserveDamageAndCountWeapons() {
		assertEquals(25, SpecialWeaponRules.reportedValue(SpecialWeapon.BANDOS_GODSWORD, 25));
		assertEquals(2, SpecialWeaponRules.reportedValue(SpecialWeapon.TONALZTICS_OF_RALOS, 2));
		assertEquals(1, SpecialWeaponRules.reportedValue(SpecialWeapon.DRAGON_WARHAMMER, 42));
		assertEquals(0, SpecialWeaponRules.reportedValue(SpecialWeapon.BANDOS_GODSWORD, -1));
	}
}

package net.betterpartydefence;

import static org.junit.Assert.*;

import java.util.HashSet;
import java.util.Set;
import net.betterpartydefence.boss.BossLifecycle;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import org.junit.Test;
import static org.mockito.Mockito.*;

/** Current Jagex 21 October TFA caps, distinct same-name actors, and phase transitions. */
public class TfaBossDefenceTest {
	private static NPC npc(String name, int id, int combat) {
		NPC n = mock(NPC.class);
		when(n.getName()).thenReturn(name);
		when(n.getId()).thenReturn(id);
		when(n.getCombatLevel()).thenReturn(combat);
		return n;
	}

	@Test
	public void defenceFloorsMatchJagexOctober21Hotfix() {
		Object[][] cases = {
				{BossDefence.TFA_ARCHIVE_GUARDIAN, 260, 156},
				{BossDefence.TFA_EZEKIEL, 130, 78},
				{BossDefence.TFA_BORK, 300, 180},
				{BossDefence.TFA_SMORKS, 220, 0},
				{BossDefence.TFA_MOIA, 195, 117},
				{BossDefence.TFA_DREADNOTH, 125, 0},
				{BossDefence.TFA_XARTH, 170, 102},
				{BossDefence.TFA_DAGONHAI_ELDER, 100, 0},
				{BossDefence.TFA_DAGONHAI_MONK_16645, 100, 0},
				{BossDefence.TFA_DAGONHAI_MONK_16646, 100, 0},
				{BossDefence.TFA_OCELLUS_P1, 215, 129},
				{BossDefence.TFA_OCELLUS_P2, 250, 0},
				{BossDefence.TFA_OCELLUS_P3, 250, 150}
		};
		for (Object[] entry : cases) {
			BossDefence boss = (BossDefence) entry[0];
			int base = (Integer) entry[1];
			int floor = (Integer) entry[2];
			assertTrue(boss.name(), boss.has(BossDefence.Flag.TFA));
			assertEquals(boss.name(), base, boss.getBaseDef());
			assertEquals(boss.name(), floor, boss.getMinDef());
			assertTrue(boss.getMinDef() >= 0 && boss.getMinDef() <= boss.getBaseDef());
		}
	}

	@Test
	public void allDagonhaiTrioActorsAreIndependent() {
		BossDefence elder = BossDefence.matchingNpc(npc("Dagon'hai Elder", 16643, 427));
		BossDefence monkA = BossDefence.matchingNpc(npc("Dagon'hai Monk", 16645, 427));
		BossDefence monkB = BossDefence.matchingNpc(npc("Dagon'hai Monk", 16646, 427));
		Set<BossDefence> distinct = new HashSet<>();
		distinct.add(elder);
		distinct.add(monkA);
		distinct.add(monkB);
		assertEquals(3, distinct.size());
		assertNull(BossDefence.matchingNpc(npc("Dagon'hai Monk", 16699, 427)));
		assertNull(BossDefence.matchingNpcName("Dagon'hai Monk"));
	}

	@Test
	public void ocellusPhaseOneThreeAndIdleActorAreDistinct() {
		assertNull(BossDefence.matchingNpc(npc("Ocellus", 16672, 0)));
		assertEquals(BossDefence.TFA_OCELLUS_P1,
				BossDefence.matchingNpc(npc("Ocellus", 16673, 1121)));
		assertEquals(BossDefence.TFA_OCELLUS_P1,
				BossDefence.matchingNpc(npc("Ocellus", 16674, 1121)));
		assertEquals(BossDefence.TFA_OCELLUS_P3,
				BossDefence.matchingNpc(npc("Ocellus", 16677, 1197)));
		assertEquals(BossDefence.TFA_OCELLUS_P3,
				BossDefence.matchingNpc(npc("Ocellus", 16677, 1601)));
		assertNull(BossDefence.matchingNpc(npc("Ocellus", 16675, 0)));
		assertEquals(BossDefence.TFA_OCELLUS_P2,
				BossDefence.matchingNpc(npc("Ocellus", 16676, 1200))); // exact NPC ID
		assertNull(BossDefence.matchingNpc(npc("The Blade", 16683, 0)));
		assertNull(BossDefence.matchingNpc(npc("The Blade", 62706, 0)));
		assertNull(BossDefence.matchingNpc(npc("The Blade", 16684, 0)));
		assertNull(BossDefence.matchingNpcName("The Blade"));
		assertNull(BossDefence.matchingNpcName("Ocellus"));
	}

	private static NPC actorWithActions(int id, String... actions) {
		NPC n = npc("Ocellus", id, 1200);
		NPCComposition comp = mock(NPCComposition.class);
		when(comp.getActions()).thenReturn(actions);
		when(n.getTransformedComposition()).thenReturn(comp);
		return n;
	}

	@Test
	public void ocellusPhaseTwoTracksOnlyConfirmed16676CombatTarget() {
		NPC attackable = actorWithActions(16676, null, "Attack", "Examine");
		when(attackable.getHealthRatio()).thenReturn(0); // no visible health bar yet
		assertTrue(BossDefence.isAttackableOcellusPhaseTwo(attackable));
		assertEquals(BossDefence.TFA_OCELLUS_P2, BossDefence.matchingNpc(attackable));
		assertTrue(BossDefence.isLiveNpc(attackable));

		NPC actionsMissing = actorWithActions(16676, "Examine");
		assertTrue(BossDefence.isAttackableOcellusPhaseTwo(actionsMissing));
		assertEquals(BossDefence.TFA_OCELLUS_P2, BossDefence.matchingNpc(actionsMissing));

		NPC transition = actorWithActions(16675, "Attack", "Examine");
		assertFalse(BossDefence.isAttackableOcellusPhaseTwo(transition));
		assertNull(BossDefence.matchingNpc(transition));
		assertFalse(BossDefence.isLiveNpc(transition));

		assertNull(BossDefence.matchingNpc(npc("The Blade", 16683, 0)));
		assertNull(BossDefence.matchingNpcName("The Blade"));
		assertNull(BossDefence.matchingNpc(npc("Ocellus", 16672, 0)));
	}

	@Test
	public void ocellusPhaseTwoIdentificationDoesNotDependOnCompositionActions() {
		NPC n = npc("Ocellus", 16676, 1200);
		NPCComposition transformed = mock(NPCComposition.class);
		when(transformed.getActions()).thenReturn(new String[]{"Examine"});
		when(n.getTransformedComposition()).thenReturn(transformed);
		assertEquals(BossDefence.TFA_OCELLUS_P2, BossDefence.matchingNpc(n));

		when(n.getTransformedComposition()).thenReturn(null);
		assertEquals(BossDefence.TFA_OCELLUS_P2, BossDefence.matchingNpc(n));
	}

	@Test
	public void quadrantTransitionsCannotResetOcellusPhaseThree() {
		BossLifecycle m = BossLifecycle.forBoss(BossDefence.TFA_OCELLUS_P3);
		assertTrue(m.isPhasePersistent());
		assertTrue(m.preserveStateAtZeroHp(16677));
		assertFalse(m.resetsStatsOnActorEntry(16677));
		assertFalse(m.endsEncounterOnActorEntry(16677));
		assertFalse(BossLifecycle.forBoss(BossDefence.TFA_OCELLUS_P1)
				.resetsStatsOnActorEntry(16674));
	}
	@Test
	public void ocellusP2MatchesVerifiedActorIdRegardlessOfName() {
		NPC sword = npc("The Blade", 16676, 1200);
		when(sword.getHealthRatio()).thenReturn(0);
		assertEquals(BossDefence.TFA_OCELLUS_P2, BossDefence.matchingNpc(sword));
		assertTrue(BossDefence.isAttackableOcellusPhaseTwo(sword));
		assertTrue(BossDefence.isLiveNpc(sword));
		assertTrue(TfaEncounterMechanics.isOcellusPhaseTwoActor(sword));

		NPC ocellus = npc("Ocellus", 16676, 1200);
		assertEquals(BossDefence.TFA_OCELLUS_P2, BossDefence.matchingNpc(ocellus));

		NPC otherName = npc("Charged Blade", 16676, 1200);
		assertEquals(BossDefence.TFA_OCELLUS_P2, BossDefence.matchingNpc(otherName));

		assertNull(BossDefence.matchingNpc(npc("Ocellus", 16675, 1200)));
		assertNull(BossDefence.matchingNpc(npc("The Blade", 16683, 0)));
		assertEquals(BossDefence.TFA_OCELLUS_P1,
				BossDefence.matchingNpc(npc("Ocellus", 16673, 1121)));
		assertEquals(BossDefence.TFA_OCELLUS_P3,
				BossDefence.matchingNpc(npc("Ocellus", 16677, 1601)));
	}


	@Test
	public void ocellusTransitionMarkersDoNotOwnDefenceState() {
		NPC transition = npc("<col=ff0000>Ocellus</col>", 16675, 1601);
		NPC prop = npc("The Blade", 16683, 0);
		NPC missingName = npc(null, 16676, 0);

		assertTrue(TfaEncounterMechanics.isOcellusPhaseTwoActor(transition));
		assertTrue(TfaEncounterMechanics.isOcellusPhaseTwoActor(prop));
		assertNull(BossDefence.matchingNpc(transition));
		assertNull(BossDefence.matchingNpc(prop));
		assertTrue(TfaEncounterMechanics.isOcellusPhaseTwoActor(missingName));
		assertEquals(BossDefence.TFA_OCELLUS_P2, BossDefence.matchingNpc(missingName));
	}
}

package net.betterpartydefence;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class ToaEncounterCoordinatorTest {
	@Test
	public void fullPartyWipeResetsRememberedBossOncePerWipe() {
		Client client = mock(Client.class);
		WorldView world = mock(WorldView.class);
		DefenceTracker tracker = mock(DefenceTracker.class);
		when(client.getTopLevelWorldView()).thenReturn(world);
		when(world.isInstance()).thenReturn(true);
		when(client.getVarbitValue(VarbitID.TOA_CLIENT_P0)).thenReturn(30);
		when(client.getVarbitValue(VarbitID.TOA_CLIENT_P1)).thenReturn(30);
		when(tracker.hasRememberedState(BossDefence.BA_BA)).thenReturn(true);

		List<BossDefence> resets = new ArrayList<>();
		ToaEncounterCoordinator coordinator =
				new ToaEncounterCoordinator(client, tracker, resets::add);
		coordinator.onGameTick();
		coordinator.onGameTick();
		assertEquals(List.of(BossDefence.BA_BA), resets);

		when(client.getVarbitValue(VarbitID.TOA_CLIENT_P1)).thenReturn(20);
		coordinator.onGameTick();
		when(client.getVarbitValue(VarbitID.TOA_CLIENT_P1)).thenReturn(30);
		coordinator.onGameTick();
		assertEquals(List.of(BossDefence.BA_BA, BossDefence.BA_BA), resets);
	}
}
